// ─────────────────────────────────────────────────────────────────
// API HELPERS
// ─────────────────────────────────────────────────────────────────
function displayStat(liveVal, previewFallback, emptyFallback) {
  const _empty = emptyFallback !== undefined ? emptyFallback : '—';
  if (liveVal !== null && liveVal !== undefined && liveVal !== '') return String(liveVal);
  return PREVIEW_MODE ? String(previewFallback) : _empty;
}

function getOverviewApiPath() {
  return '/api/overview?range=' + encodeURIComponent(STATE.overviewRange || '7d');
}

const _apiFetchInFlight = new Map();
const _apiFetchCache    = new Map();
const _API_CACHE_TTL    = 30_000;

function _fpCurrentSessionToken() {
  try { return sessionStorage.getItem('fp_session_token') || ''; } catch(_) { return ''; }
}

function _fpSessionFetchOptions(options = {}) {
  const token = _fpCurrentSessionToken();
  return {
    ...options,
    // Always include the cookie (primary auth). The Bearer token is only an
    // additional per-tab override; it never replaces the cookie.
    credentials: 'include',
    headers: {
      ...(options.headers || {}),
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
    },
  };
}

// ── Session-reset debounce guard ──────────────────────────────────────────────
// A single transient 401 from a background poll (audit, activity, GA4 live)
// must NOT immediately destroy the session.  We count background 401s and only
// redirect after a confirmation fetch to /api/me also returns 401.
var _401BackgroundCount = 0;
var _401ConfirmTimer    = null;

function _confirmSessionExpired() {
  // Use plain fetch (not apiFetch) to avoid recursion through this handler.
  fetch('/api/me', _fpSessionFetchOptions())
    .then(function(r) {
      var ts = new Date().toISOString();
      if (r.status === 401) {
        console.warn('[FP-AUTH]', ts, 'Confirmation /api/me → 401. Session truly expired. Redirecting.');
        _401BackgroundCount = 0;
        // Clear auth artefacts. sessionStorage is tab-isolated so removing
        // fp_session_token here does NOT affect sibling tabs — each tab has its
        // own independent sessionStorage context.
        ['token','fp_token','fp-token','fp-auth','fp-session','fp-user'].forEach(function(k) {
          try { localStorage.removeItem(k); } catch(_) {}
        });
        try { sessionStorage.removeItem('fp_session_token'); } catch(_) {}
        try { sessionStorage.removeItem('fp-state-cache'); } catch(_) {}
        window.location.href = '/login.html';
      } else {
        console.warn('[FP-AUTH]', ts, 'Confirmation /api/me →', r.status, '— session still valid, ignoring background 401.');
        _401BackgroundCount = 0;
      }
    })
    .catch(function(e) {
      // Network error on confirmation — session likely valid; reset counter.
      console.warn('[FP-AUTH]', new Date().toISOString(), 'Confirmation /api/me network error:', e.message, '— treating as transient.');
      _401BackgroundCount = 0;
    });
}

async function apiFetch(path, opts = {}) {
  const isGet = !opts.method || opts.method === 'GET';
  if (isGet && opts.force) { _apiFetchCache.delete(path); _apiFetchInFlight.delete(path); }
  if (isGet) {
    const cached = _apiFetchCache.get(path);
    if (cached && (Date.now() - cached.ts < _API_CACHE_TTL)) return cached.data;
    const inflight = _apiFetchInFlight.get(path);
    if (inflight) return inflight;
  }
  const _promise = (async () => {
    // Auth architecture (three-tier):
    //   Tier 1 — HttpOnly cookie: PRIMARY. Sent automatically by the browser via
    //            credentials:'include'. No JS access needed. Covers all normal sessions.
    //   Tier 2 — sessionStorage Bearer: per-tab OVERRIDE only. Used when two users are
    //            testing simultaneously in the same browser — each tab has its own
    //            sessionStorage and therefore its own identity. Middleware reads Bearer
    //            first, so this takes priority over the shared cookie when present.
    //   Tier 3 — localStorage token: REMOVED. Writing a token there is shared across
    //            all tabs on the domain and was the root cause of cross-user contamination.
    const token = (function() {
      try { var t = sessionStorage.getItem('fp_session_token'); if (t) return t; } catch(_) {}
      return ''; // No localStorage fallback — rely on HttpOnly cookie instead
    })();
    // Cache-buster for GET to bypass CDN/browser cache
    const _path = isGet && !path.includes('?')
      ? `${path}?_cb=${Date.now()}`
      : isGet ? `${path}&_cb=${Date.now()}` : path;
    // Timeout guard: abort if the server goes silent (e.g. mid-restart TCP hang).
    // 15 s is generous enough for slow connections but short enough to surface hangs.
    const _fetchTimeout = opts.timeout || 15000;
    const _ctrl = new AbortController();
    const _abortTimer = setTimeout(() => _ctrl.abort(), _fetchTimeout);
    let res;
    try {
      res = await fetch(_path, {
        ...opts,
        signal: _ctrl.signal,
        headers: {
          'Content-Type': 'application/json',
          ...(isGet ? { 'Cache-Control': 'no-cache, no-store' } : {}),
          // Send Bearer when a per-tab token is present (takes priority over cookie on server).
          // Cookie is always sent as primary auth — never omit credentials.
          ...(token ? { Authorization: `Bearer ${token}` } : {}),
          ...(opts.headers || {}),
        },
        // Always include the cookie. Bearer is only an additional per-tab override.
        credentials: 'include',
      });
    } finally {
      clearTimeout(_abortTimer);
    }
    if (res.status === 401) {
      const _ts = new Date().toISOString();
      if (opts.backgroundPoll) {
        // Background poll 401 — do NOT redirect immediately.
        // A single transient 401 (network hiccup, rolling deploy, JWT clock drift)
        // must not destroy a valid session.  Confirm via /api/me before acting.
        _401BackgroundCount++;
        console.warn('[FP-AUTH]', _ts, 'Background poll 401 on', path,
          '— count:', _401BackgroundCount, '— scheduling confirmation fetch in 3s.');
        if (!_401ConfirmTimer) {
          _401ConfirmTimer = setTimeout(function() {
            _401ConfirmTimer = null;
            _confirmSessionExpired();
          }, 3000);
        }
        return null;
      }
      // Foreground 401 — session is definitively invalid; clear and redirect.
      console.warn('[FP-AUTH]', _ts, 'Foreground 401 on', path, '— clearing session and redirecting.');
      _401BackgroundCount = 0;
      if (_401ConfirmTimer) { clearTimeout(_401ConfirmTimer); _401ConfirmTimer = null; }
      ['token','fp_token','fp-token','fp-auth','fp-session','fp-user'].forEach(k => localStorage.removeItem(k));
      // sessionStorage is tab-isolated — removing fp_session_token here only
      // affects THIS tab; sibling tabs each have their own sessionStorage context.
      try { sessionStorage.removeItem('fp_session_token'); } catch(_) {}
      try { sessionStorage.removeItem('fp-state-cache'); } catch(_) {}
      window.location.href = '/login.html';
      return null;
    }
    // Any successful foreground response resets the background 401 counter.
    if (!opts.backgroundPoll) { _401BackgroundCount = 0; }
    if (!res.ok) {
      if (isGet) _apiFetchInFlight.delete(path);
      throw new Error(`HTTP ${res.status}`);
    }
    const data = await res.json();
    if (isGet) {
      _apiFetchCache.set(path, { data, ts: Date.now() });
      _apiFetchInFlight.delete(path);
    }
    return data;
  })();
  if (isGet) _apiFetchInFlight.set(path, _promise);
  return _promise;
}

// Normalize API responses that may be plain arrays or wrapped objects.
// Normalize a Mongo document: remap _id → id and coerce date strings.
function normalizeDoc(doc) {
  if (!doc || typeof doc !== 'object') return doc;
  const out = { ...doc };
  if (!out.id && out._id) out.id = String(out._id);
  delete out._id;
  // Coerce usage shape for /api/me compatibility
  if (out.usage && !out.usage.audit && out.usage.audits) out.usage.audit = out.usage.audits;
  return out;
}

function normArr(raw, key) {
  if (!raw) return null;
  let arr = null;
  if (Array.isArray(raw)) arr = raw;
  else if (Array.isArray(raw[key])) arr = raw[key];
  return arr ? arr.map(normalizeDoc) : null;
}

async function apiAction(method, path, body, options = {}) {
  // Non-idempotent writes (POST/PUT/PATCH/DELETE) default to 0 retries.
  // A failed write must NOT be silently retried — it can create duplicate rows,
  // duplicate emails or other irreversible side-effects.
  // GET / HEAD are safe-to-retry up to 2 times.
  const _idempotent = method === 'GET' || method === 'HEAD';
  const retries = (options.retries !== undefined) ? options.retries : (_idempotent ? 2 : 0);
  const _t0 = performance.now();
  let lastErr;
  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      const result = await apiFetch(path, { method, body: body ? JSON.stringify(body) : undefined });
      const ms = Math.round(performance.now() - _t0);
      if(window.__DEV__) console.log('[FP_ACTION] method=' + method + ' route=' + path + ' status=ok ms=' + ms + ' attempt=' + attempt);
      return result;
    } catch (e) {
      lastErr = e;
      if (attempt < retries) {
        const delay = Math.min(1000 * Math.pow(2, attempt), 5000);
        await new Promise(r => setTimeout(r, delay));
      }
    }
  }
  const ms = Math.round(performance.now() - _t0);
  console.warn('[FP_ACTION] method=' + method + ' route=' + path + ' status=error ms=' + ms + ' retries=' + retries, lastErr?.message);
  if (PREVIEW_MODE) { return null; }
  throw lastErr;
}

// ─── HELPERS GLOBAUX ─────────────────────────────────────────────────────────

function exportCsv(headerRow, dataRows, filename) {
  const bom = '\ufeff';
  const csv = bom + [headerRow, ...dataRows].join('\n');
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = filename; a.click();
  URL.revokeObjectURL(url);
}

async function downloadReportPdf(reportId, name, triggerEl) {
  const filename = (name || 'rapport') + '.pdf';
  if (triggerEl) { triggerEl.disabled = true; triggerEl.dataset._origText = triggerEl.textContent; triggerEl.textContent = '…'; }
  try {
    const res = await fetch(`/api/reports/${reportId}/download`,
      _fpSessionFetchOptions({ headers: { 'Cache-Control': 'no-cache' } }));
    if (!res.ok) {
      const msg = res.status === 401 ? 'Session expirée — reconnectez-vous'
                : res.status === 403 ? 'Accès refusé à ce rapport'
                : res.status === 404 ? 'Rapport introuvable'
                : `Erreur serveur (${res.status})`;
      showToast('error', msg); return;
    }
    const ct = res.headers.get('Content-Type') || '';
    if (!ct.includes('application/pdf') && !ct.includes('octet-stream')) {
      showToast('error', 'Réponse inattendue — le fichier n\'est pas un PDF'); return;
    }
    const blob = await res.blob();
    if (blob.size === 0) { showToast('error', 'PDF vide — réessayez'); return; }
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = filename;
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    URL.revokeObjectURL(url);
  } catch(e) {
    showToast('error', 'Erreur lors du téléchargement : ' + (e?.message || ''));
  } finally {
    if (triggerEl) { triggerEl.disabled = false; triggerEl.textContent = triggerEl.dataset._origText || triggerEl.textContent; }
  }
}

