async function loadAuditHistory(audit) {
  const container = document.getElementById(`fp-audit-history-${audit.id}`);
  const content = document.getElementById('fp-audit-hist-content');
  const csvBtn = document.getElementById('fp-audit-hist-csv-btn');
  if (!content) return;

  let history = [];
  try {
    history = await apiFetch(`/api/audits/history?url=${encodeURIComponent(audit.url)}&days=90`);
    if (!Array.isArray(history)) history = [];
  } catch(_) { history = []; }

  if (history.length < 2) {
    content.innerHTML = `<div style="text-align:center;color:var(--fp-text-faint);font-size:12px;padding:12px 0">
      <div style="font-size:20px;margin-bottom:4px">📊</div>
      <div>Données insuffisantes — au moins 2 audits requis</div>
      <div style="font-size:11px;margin-top:2px;color:var(--fp-text-faint)">Relancez un audit pour commencer à construire l'historique.</div>
    </div>`;
    return;
  }

  const sorted = [...history].sort((a, b) => new Date(a.date) - new Date(b.date));
  const scores = sorted.map(h => h.score);
  const dates = sorted.map(h => new Date(h.date).toLocaleDateString('fr-FR', { day:'2-digit', month:'short' }));

  // Trend line (linear regression)
  const n = scores.length;
  const sumX = scores.reduce((s, _, i) => s + i, 0);
  const sumY = scores.reduce((s, v) => s + v, 0);
  const sumXY = scores.reduce((s, v, i) => s + i * v, 0);
  const sumX2 = scores.reduce((s, _, i) => s + i * i, 0);
  const slope = (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX || 1);
  const intercept = (sumY - slope * sumX) / n;
  const trendPts = scores.map((_, i) => Math.round(intercept + slope * i));

  // SVG chart
  const W = 240, H = 72, pad = { t: 6, r: 6, b: 18, l: 28 };
  const iW = W - pad.l - pad.r, iH = H - pad.t - pad.b;
  const minS = Math.max(0, Math.min(...scores) - 10);
  const maxS = Math.min(100, Math.max(...scores) + 10);
  const range = maxS - minS || 1;
  const xPos = (i) => pad.l + (i / (n - 1)) * iW;
  const yPos = (v) => pad.t + iH - ((v - minS) / range) * iH;

  const scorePts = scores.map((v, i) => `${xPos(i).toFixed(1)},${yPos(v).toFixed(1)}`).join(' ');
  const trendLine = `${xPos(0).toFixed(1)},${yPos(trendPts[0]).toFixed(1)} ${xPos(n-1).toFixed(1)},${yPos(trendPts[n-1]).toFixed(1)}`;

  // Dots with tooltip metadata
  const dots = scores.map((v, i) => {
    const delta = i > 0 ? v - scores[i-1] : 0;
    const color = v >= 70 ? '#22c55e' : v >= 45 ? '#f59e0b' : '#ef4444';
    return `<circle cx="${xPos(i).toFixed(1)}" cy="${yPos(v).toFixed(1)}" r="3" fill="${color}" stroke="var(--fp-bg-card)" stroke-width="1.5" title="${dates[i]}: ${v}/100${i>0?(delta>=0?' +':' ')+delta+' pts':''}"/>`;
  }).join('');

  // Y-axis labels
  const yLabels = [minS, Math.round((minS+maxS)/2), maxS].map(v =>
    `<text x="${pad.l - 4}" y="${(yPos(v)+4).toFixed(1)}" text-anchor="end" font-size="8" fill="var(--fp-text-faint)">${v}</text>`
  ).join('');

  // X-axis labels (first, mid, last)
  const xLabelIdxs = [0, Math.floor((n-1)/2), n-1];
  const xLabels = xLabelIdxs.map(i =>
    `<text x="${xPos(i).toFixed(1)}" y="${(H - 2).toFixed(1)}" text-anchor="middle" font-size="8" fill="var(--fp-text-faint)">${dates[i]}</text>`
  ).join('');

  const last = scores[n-1];
  const first = scores[0];
  const totalDelta = last - first;
  const trendDir = slope > 0.1 ? '↑' : slope < -0.1 ? '↓' : '→';
  const trendColor = slope > 0.1 ? '#22c55e' : slope < -0.1 ? '#ef4444' : '#94a3b8';

  content.innerHTML = `
    <div style="display:flex;flex-direction:column;gap:8px">
      <div style="display:flex;gap:12px;flex-wrap:wrap">
        <span style="font-size:11px;color:var(--fp-text-muted)">Premier audit : <b style="color:var(--fp-text)">${first}/100</b></span>
        <span style="font-size:11px;color:var(--fp-text-muted)">Dernier : <b style="color:${last>=70?'#22c55e':last>=45?'#f59e0b':'#ef4444'}">${last}/100</b></span>
        <span style="font-size:11px;color:${trendColor};font-weight:700">${trendDir} ${totalDelta >= 0 ? '+' : ''}${totalDelta} pts sur 90j</span>
      </div>
      <svg width="${W}" height="${H}" viewBox="0 0 ${W} ${H}" style="width:100%;height:auto;overflow:visible">
        <line x1="${pad.l}" y1="${pad.t}" x2="${pad.l}" y2="${pad.t + iH}" stroke="var(--fp-border)" stroke-width="1"/>
        <line x1="${pad.l}" y1="${pad.t + iH}" x2="${pad.l + iW}" y2="${pad.t + iH}" stroke="var(--fp-border)" stroke-width="1"/>
        ${yLabels}${xLabels}
        <polyline points="${trendLine}" fill="none" stroke="rgba(245,158,11,0.45)" stroke-width="1" stroke-dasharray="3,2"/>
        <polyline points="${scorePts}" fill="none" stroke="#2563EB" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
        ${dots}
      </svg>
      <table style="width:100%;border-collapse:collapse;font-size:11px;margin-top:2px">
        <thead><tr>
          <th style="text-align:left;color:var(--fp-text-muted);font-weight:600;padding:3px 0;border-bottom:1px solid var(--fp-border)">Date</th>
          <th style="text-align:center;color:var(--fp-text-muted);font-weight:600;padding:3px 0;border-bottom:1px solid var(--fp-border)">Score</th>
          <th style="text-align:center;color:var(--fp-text-muted);font-weight:600;padding:3px 0;border-bottom:1px solid var(--fp-border)">Δ</th>
          <th style="text-align:center;color:var(--fp-text-muted);font-weight:600;padding:3px 0;border-bottom:1px solid var(--fp-border)">Origine</th>
        </tr></thead>
        <tbody>
          ${sorted.slice().reverse().slice(0, 8).map((h, i, arr) => {
            const delta = i < arr.length - 1 ? h.score - arr[i+1].score : null;
            const dc = delta === null ? '#94a3b8' : delta > 0 ? '#22c55e' : delta < 0 ? '#ef4444' : '#94a3b8';
            return `<tr>
              <td style="padding:3px 0;color:var(--fp-text-muted)">${new Date(h.date).toLocaleDateString('fr-FR',{day:'2-digit',month:'short',year:'2-digit'})}</td>
              <td style="text-align:center;font-weight:700;color:${scoreColor(h.score)}">${h.score}</td>
              <td style="text-align:center;color:${dc};font-weight:600">${delta === null ? '—' : (delta > 0 ? '+' : '') + delta + 'pt'}</td>
              <td style="text-align:center"><span style="font-size:9px;padding:1px 5px;border-radius:3px;${(h.origin||'manual')==='auto'?'background:rgba(139,92,246,0.15);color:#8b5cf6':'background:var(--fp-track);color:var(--fp-text-faint)'}">${h.origin === 'auto' ? 'Auto' : 'Manuel'}</span></td>
            </tr>`;
          }).join('')}
        </tbody>
      </table>
    </div>
  `;

  if (csvBtn) {
    csvBtn.style.display = 'inline-block';
    csvBtn.onclick = () => {
      const rows = sorted.map((h, i) => {
        const delta = i > 0 ? h.score - sorted[i-1].score : '';
        return `${new Date(h.date).toLocaleDateString('fr-FR')},${h.score},${delta},${h.origin||'manual'},${h.speed||''}`;
      });
      exportCsv('Date,Score SEO,Delta,Origine,Vitesse', rows, `historique-${audit.url.replace(/[^a-z0-9]/gi,'_').slice(0,30)}.csv`);
    };
  }
}

async function bindAuditPanelBtns(audit) {
  await new Promise(r => setTimeout(r, 60));
  loadAuditHistory(audit).catch(() => {});
  const rerunBtn = document.getElementById('audit-panel-rerun');
  const exportBtn = document.getElementById('audit-panel-export');
  if (rerunBtn) {
    rerunBtn.addEventListener('click', async () => {
      rerunBtn.disabled = true;
      rerunBtn.textContent = 'Audit en cours…';
      try {
        const res = await apiAction('POST', '/api/audits', { url: audit.url });
        if (res) {
          const idx = STATE.audits.findIndex(x => x.id === audit.id);
          if (idx >= 0) STATE.audits.splice(idx, 1);
          STATE.audits.unshift(res);
          if (typeof startAuditPolling === 'function') startAuditPolling(res.id);
        }
        showToast('success', `Audit relancé pour ${escHtml(audit.url)}`);
        closeFloatPanel();
        render();
      } catch(e) {
        showToast('error', 'Erreur lors du relancement');
        rerunBtn.disabled = false;
        rerunBtn.textContent = '🔄 Relancer l\'audit';
      }
    });
  }
  if (exportBtn) {
    exportBtn.addEventListener('click', async () => {
      exportBtn.disabled = true;
      exportBtn.textContent = 'Génération…';
      try {
        const host = (audit.url || '').replace(/^https?:\/\//, '').split('/')[0];
        const name = `Audit ${host} — ${new Date().toLocaleDateString('fr-FR')}`;
        const res = await apiAction('POST', '/api/reports', { name, auditId: audit.id, format: 'PDF' });
        const r = res || { id: 'r' + Date.now(), name };
        STATE.reports.unshift(r);
        showToast('success', 'Téléchargement du rapport PDF…');
        downloadReportPdf(r.id, name);
      } catch(e) {
        showToast('error', 'Erreur lors de la génération PDF');
      }
      exportBtn.disabled = false;
      exportBtn.textContent = '⬇ Exporter PDF';
    });
  }
  const missionBtn = document.getElementById('audit-panel-mission');
  if (missionBtn) {
    missionBtn.addEventListener('click', async () => {
      const domain = (audit.url || '').replace(/^https?:\/\//, '').split('/')[0];
      const title = `Optimiser SEO — ${domain}`;
      const existing = STATE.missions.find(m => m.title.toLowerCase().trim() === title.toLowerCase().trim() && m.status !== 'done');
      if (existing) {
        missionBtn.textContent = 'Voir mission →';
        missionBtn.style.color = '#22c55e';
        missionBtn.onclick = () => { closeFloatPanel(); navigate('missions'); };
        showToast('info', 'Mission déjà créée pour cet audit');
        return;
      }
      missionBtn.textContent = 'Création…';
      missionBtn.disabled = true;
      try {
        const m = await apiAction('POST', '/api/missions', { title, category: 'Audits', source: 'audit', auditId: audit.id, status: 'todo', priority: 'high', impact: 'Élevé' });
        const mission = m || { id: 'ms'+Date.now(), title, category: 'Audits', status: 'todo', priority: 'high' };
        STATE.missions.unshift(mission);
        missionBtn.textContent = '✓ Mission créée →';
        missionBtn.style.color = '#22c55e';
        missionBtn.style.borderColor = 'rgba(34,197,94,0.3)';
        missionBtn.disabled = false;
        missionBtn.onclick = () => { closeFloatPanel(); navigate('missions'); };
        showToast('success', 'Mission créée depuis l\'audit');
      } catch(e) {
        missionBtn.textContent = '+ Mission';
        missionBtn.disabled = false;
        showToast('error', 'Erreur lors de la création de la mission');
      }
    });
  }
}

function markAllAlertsRead() {
  (STATE.competitorAlerts || []).forEach(a => { a.read = true; });
  (STATE.alertsData || []).forEach(a => { a.read = true; });
  showToast('success', 'Toutes les alertes marquées comme lues ✓');
  render();
}

async function changeTeamMemberRole(memberId, currentRole) {
  const roles = ['viewer', 'editor', 'admin'];
  openFloatPanel('Changer le rôle', `
    <div class="fp-form-group">
      <label class="fp-form-label">Nouveau rôle pour ce membre</label>
      <select class="fp-select" id="role-picker" style="width:100%">
        ${roles.map(r => `<option value="${r}"${r === currentRole ? ' selected' : ''}>${r.charAt(0).toUpperCase() + r.slice(1)}</option>`).join('')}
      </select>
    </div>
    <button class="fp-btn fp-btn-primary" style="width:100%;margin-top:8px" id="role-confirm">Confirmer le rôle</button>
  `);
  await new Promise(r => setTimeout(r, 60));
  document.getElementById('role-confirm')?.addEventListener('click', async () => {
    const role = document.getElementById('role-picker')?.value;
    try {
      await apiAction('PATCH', `/api/team/${memberId}`, { role });
    } catch(e) { console.warn('[FP] Role patch fallback'); }
    const m = STATE.team.find(t => t.id === memberId);
    if (m) m.role = role;
    showToast('success', 'Rôle mis à jour !');
    closeFloatPanel();
    render();
  });
}

async function createShareLink() {
  const token = 'fp-' + Math.random().toString(36).slice(2, 10) + Date.now().toString(36);
  const base = location.pathname.replace('dashboard.html', 'report-view.html');
  const url = `${location.origin}${base}?token=${token}`;
  localStorage.setItem('fp:share-' + token, JSON.stringify({
    createdAt: new Date().toISOString(),
    expiresAt: new Date(Date.now() + 30 * 24 * 3600 * 1000).toISOString()
  }));
  try { await navigator.clipboard.writeText(url); } catch(e) {}
  showToast('success', 'Lien créé et copié ! Valable 30 jours.');
}

function fullscreenPresent() {
  const el = document.getElementById('fp-main') || document.body;
  if (document.fullscreenElement) {
    document.exitFullscreen().catch(() => {});
    showToast('info', 'Mode présentation désactivé');
  } else {
    el.requestFullscreen().catch(() => {
      showToast('info', 'Mode présentation : appuyez sur F11');
    });
  }
}

function openPasswordChangePanel() {
  const email = STATE.me?.email || '';
  openFloatPanel('S\u00e9curit\u00e9 du compte', `
    <div style="background:rgba(37,99,235,0.06);border:1px solid rgba(37,99,235,0.2);border-radius:10px;padding:14px 16px;margin-bottom:16px">
      <div style="font-size:13px;font-weight:700;color:var(--fp-text);margin-bottom:4px">\uD83D\uDD11 Authentification sans mot de passe</div>
      <div style="font-size:12px;color:var(--fp-text-muted);line-height:1.6">FlowPoint utilise des <strong>liens magiques s\u00e9curis\u00e9s</strong> — aucun mot de passe \u00e0 m\u00e9moriser. Pour acc\u00e9der \u00e0 votre compte depuis un nouvel appareil, cliquez sur le bouton ci-dessous pour recevoir un lien de connexion par email.</div>
    </div>
    <div class="fp-form-group"><label class="fp-form-label">Email de connexion</label><input class="fp-input" type="email" id="sec-email" value="${escHtml(email)}" placeholder="votre@email.com"/></div>
    <button class="fp-btn fp-btn-primary" style="width:100%;margin-top:8px" id="sec-send">Envoyer un nouveau lien de connexion</button>
    <div style="font-size:10px;color:var(--fp-text-faint);text-align:center;margin-top:10px">\u23F1\uFE0F Le lien expire dans 30 minutes</div>
  `);
  setTimeout(() => {
    document.getElementById('sec-send')?.addEventListener('click', async () => {
      const btn = document.getElementById('sec-send');
      const emailVal = document.getElementById('sec-email')?.value.trim();
      if (!emailVal || !emailVal.includes('@')) { showToast('warning', 'Email invalide'); return; }
      if (btn) { btn.disabled = true; btn.textContent = 'Envoi\u2026'; }
      const r = await apiAction('POST', '/api/auth/login-request', { email: emailVal }).catch(() => null);
      if (btn) { btn.disabled = false; btn.textContent = 'Envoyer un nouveau lien de connexion'; }
      if (r && !r.error) { showToast('success', 'Lien de connexion envoy\u00e9 \u00e0 ' + emailVal + ' !'); closeFloatPanel(); }
      else { showToast('error', r?.error || 'Erreur lors de l\'envoi'); }
    });
  }, 60);
}

function applyThemeChoice(t) {
  if (t === 'auto') { STATE.settings.themeAuto = true; STATE.theme = 'dark'; STATE.settings.theme = 'dark'; }
  else { STATE.settings.themeAuto = false; STATE.theme = t; STATE.settings.theme = t; }
  localStorage.setItem('fp:theme', STATE.theme);
  applyTheme();
  saveSettings();
  showToast('success', 'Thème appliqué !');
  // Re-render so the active-ring (border + colour) updates on the theme buttons.
  render();
}

