function showFatalError(msg) {
  document.body.innerHTML = `<div style="display:flex;align-items:center;justify-content:center;height:100vh;background:#050810;color:#ef4444;font-family:Inter,sans-serif;text-align:center;padding:32px"><div><div style="font-size:48px;margin-bottom:16px">⚠</div><div style="font-size:18px;font-weight:700;margin-bottom:8px">Connexion au serveur impossible</div><div style="color:#94a3b8;font-size:14px">${escHtml(msg)}</div></div></div>`;
}

async function loadData() {
  // ── Loading state: show skeleton immediately before any API call ──
  STATE.loading = true;
  render();
  // ── Safety timeout: if loadData hangs (e.g. TCP connection frozen after server restart),
  //    force STATE.loading = false after 12 s so the skeleton never stays permanently.
  const _loadSafetyTimer = setTimeout(() => {
    if (STATE.loading) {
      console.warn('[FP] loadData safety timeout — forcing render after 12s hang');
      STATE.loading = false;
      render();
    }
  }, 12000);
  // ── Phase 0: Instant render from sessionStorage cache (stale-while-revalidate) ──
  try {
    const _sc = sessionStorage.getItem('fp-state-cache');
    if (_sc) {
      const _cp = JSON.parse(_sc);
      if (Date.now() - (_cp._ts || 0) < 300000) {
        if (_cp.me)            STATE.me            = _cp.me;
        if (_cp.overview)      STATE.overview      = _cp.overview;
        if (_cp.audits)        STATE.audits        = _cp.audits;
        if (_cp.monitors)      STATE.monitors      = _cp.monitors;
        if (_cp.reports)       STATE.reports       = _cp.reports;
        if (_cp.team)          STATE.team          = _cp.team;
        if (_cp.alertRules)      STATE.alertRules      = _cp.alertRules;
        if (_cp.notifications)   STATE.notifications   = _cp.notifications;
        if (_cp.ga4Status)     { STATE.ga4Status = _cp.ga4Status; if (!window.FP_DATA) window.FP_DATA = {}; window.FP_DATA.ga4 = _cp.ga4Status; }
        if (_cp.gsc)             STATE.gsc             = _cp.gsc;
        if (_cp.googleConnected) STATE.googleConnected = _cp.googleConnected;
        // Mark cache as restored so the 401 handler knows stale state is present.
        STATE._cacheRestored = true;
        // Cache restores partial STATE — do NOT render yet; wait for full live data
        // (keywords, competitors, missions, connectors, activityEvents are not in cache)
      }
    }
  } catch(_) {}
  // ── Phase 0.5: Session restore — per-tab token bootstrap ────────────────────
  // When a tab is opened by typing the URL, from a bookmark, or by duplicating
  // a tab in some browsers, sessionStorage is empty.  Without a per-tab token
  // apiFetch() falls back to the shared HttpOnly cookie, which always reflects
  // the LAST account that logged in — causing all tabs to show the same user.
  // Fix: ask the server to echo back the cookie's token so we can store it in
  // sessionStorage.  Each tab then sends its OWN Bearer and stays on its own
  // account across refreshes.
  if (!sessionStorage.getItem('fp_session_token')) {
    try {
      const _sr = await fetch('/api/auth/session-restore', {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
      });
      if (_sr.ok) {
        const _srData = await _sr.json().catch(() => null);
        if (_srData && _srData.token) {
          sessionStorage.setItem('fp_session_token', _srData.token);
          if (!sessionStorage.getItem('fp_tab_uid')) {
            sessionStorage.setItem('fp_tab_uid', Math.random().toString(36).slice(2));
          }
        }
      }
    } catch(_srErr) { /* non-fatal — cookie auth continues as before */ }
  }

  // ── Phase 1: Critical identity — /api/me is mandatory; everything else is resilient ──
  let me = null, overview = null, audits = null, monitors = null, reports = null, team = null;
  try {
    me = await apiFetch('/api/me');
    // /api/me succeeded — clear the stale-cache flag and reset background 401 counter.
    STATE._cacheRestored = false;
    _401BackgroundCount = 0;
  } catch (e) {
    if (PREVIEW_MODE) {
      console.warn('[FP] Preview mode: using mock /api/me', e);
    } else {
      clearTimeout(_loadSafetyTimer);
      showFatalError('Impossible de joindre /api/me. Vérifiez que le backend est démarré.');
      return;
    }
  }
  STATE.me = me || (PREVIEW_MODE ? MOCK_ME : null);
  if (!STATE.me) { clearTimeout(_loadSafetyTimer); showFatalError('/api/me n\'a pas répondu.'); return; }
  if (STATE.me?.plan) STATE.me.plan = STATE.me.plan.charAt(0).toUpperCase() + STATE.me.plan.slice(1);

  // ── Phase 2: Overview + plan definitions — resilient, any failure is non-blocking ──
  const [_ovRes, _pdRes] = await Promise.allSettled([
    apiFetch(getOverviewApiPath()),
    apiFetch('/api/plans/definitions').catch(() => null),
  ]);
  if (_ovRes.status === 'fulfilled') overview = _ovRes.value;
  if (_pdRes.status === 'fulfilled' && _pdRes.value && typeof _pdRes.value === 'object') {
    STATE.planDefs = _pdRes.value;
    try { sessionStorage.setItem('fp-plan-defs', JSON.stringify({ ..._pdRes.value, _ts: Date.now() })); } catch(_) {}
  }

  // ── Phase 3: Section data — each section fails independently, dashboard stays usable ──
  // classifySectionError maps an Error message to a type code for per-section rendering
  function classifySectionError(reason) {
    if (!reason) return 'unknown';
    const msg = reason.message || String(reason);
    if (/401/.test(msg)) return 'session';    // expired token / re-login required
    if (/403/.test(msg)) return 'permission'; // insufficient rights
    if (/404/.test(msg)) return 'route';      // backend route missing
    if (/5\d\d/.test(msg)) return 'server';   // 5xx backend error
    if (/timeout|abort|network|fetch/i.test(msg)) return 'network'; // connectivity
    return 'unknown';
  }
  STATE.sectionErrors = {};
  const [_auRes, _moRes, _reRes, _teRes] = await Promise.allSettled([
    apiFetch('/api/audits'), apiFetch('/api/monitors'),
    apiFetch('/api/reports'), apiFetch('/api/team'),
  ]);
  if (_auRes.status === 'fulfilled') { audits   = _auRes.value; } else { STATE.sectionErrors.audits   = classifySectionError(_auRes.reason); console.warn('[FP] /api/audits failed:', _auRes.reason?.message || _auRes.reason); }
  if (_moRes.status === 'fulfilled') { monitors = _moRes.value; } else { STATE.sectionErrors.monitors = classifySectionError(_moRes.reason); console.warn('[FP] /api/monitors failed:', _moRes.reason?.message || _moRes.reason); }
  if (_reRes.status === 'fulfilled') { reports  = _reRes.value; } else { STATE.sectionErrors.reports  = classifySectionError(_reRes.reason); console.warn('[FP] /api/reports failed:', _reRes.reason?.message || _reRes.reason); }
  if (_teRes.status === 'fulfilled') { team     = _teRes.value; } else { STATE.sectionErrors.team     = classifySectionError(_teRes.reason); console.warn('[FP] /api/team failed:', _teRes.reason?.message || _teRes.reason); }

  const _aud = normArr(audits,   'audits');   STATE.audits   = (_aud   && _aud.length   > 0) ? _aud   : (PREVIEW_MODE ? MOCK_AUDITS   : []);
  const _mon = normArr(monitors, 'monitors'); STATE.monitors = (_mon   && _mon.length   > 0) ? _mon   : (PREVIEW_MODE ? MOCK_MONITORS : []);
  const _rep = normArr(reports,  'reports');  STATE.reports  = (_rep   && _rep.length   > 0) ? _rep   : (PREVIEW_MODE ? MOCK_REPORTS  : []);
  const _team= normArr(team,     'members');  STATE.team     = (_team  && _team.length  > 0) ? _team  : (PREVIEW_MODE ? MOCK_TEAM     : []);
  STATE.pendingInvitations = (team && Array.isArray(team.pendingInvitations)) ? team.pendingInvitations : [];
  STATE.seatUsage          = (team && team.seatUsage) ? team.seatUsage : null;

  STATE.calendarEvents = [];
  STATE.clients = [];
  STATE.overview = overview;
  // Map GBP fields from overview response to STATE.gbp (used throughout dashboard)
  if (overview && typeof overview === 'object') {
    STATE.gbp = {
      connected:        !!overview.gbpConnected,
      averageRating:    overview.gbpRating       ?? null,
      totalReviews:     overview.gbpReviewCount  ?? null,
      unansweredReviews:overview.gbpUnansweredCount ?? null,
      completionScore:  overview.gbpCompletionPct  ?? null,
      listings:         [],
      locations:        [],
    };
  }
  if (!STATE.historySiteUrl && STATE.audits.length > 0) STATE.historySiteUrl = STATE.audits[0].url;

  // ── Phase 3: Early render with primary data so the UI is visible immediately ──
  clearTimeout(_loadSafetyTimer);
  STATE.loading = false;
  render();

  // ── Phase 4: All secondary fetches in one parallel batch ─────────────────────
  const _domain = (STATE.audits[0] && (() => { try { return new URL(STATE.audits[0].url).hostname; } catch(_){ return ''; } })()) || '';
  const [
    _schedRes, _udRes, _upcomingRes, _alertRulesRes, _alertEventsRes,
    _activityRes, _teamMsgsRes, _prefsRes, _storageRes, _clRes, _notifsRes, _blRes, _llmRes,
    _clientsRes, _calRes,
  ] = await Promise.allSettled([
    apiFetch('/api/audits/schedule'),
    apiFetch('/api/billing/usage-details'),
    apiFetch('/api/audits/upcoming'),
    apiFetch('/api/alert-rules'),
    apiFetch('/api/alert-events'),
    apiFetch('/api/activity'),
    apiFetch('/api/team/messages/all'),
    apiFetch('/api/me/prefs'),
    apiFetch('/api/me/storage').catch(() => null),
    apiFetch('/api/overview/checklist').catch(() => null),
    apiFetch('/api/notifications'),
    _domain ? apiFetch('/api/seo/backlinks?domain='      + encodeURIComponent(_domain)) : Promise.resolve(null),
    _domain ? apiFetch('/api/seo/llm-visibility?domain=' + encodeURIComponent(_domain)) : Promise.resolve(null),
    apiFetch('/api/reports/clients'),
    apiFetch('/api/calendar-events'),
  ]);

  STATE.auditSchedules  = (_schedRes.status      === 'fulfilled' && Array.isArray(_schedRes.value))                                ? _schedRes.value      : [];
  STATE.usageDetails    = (_udRes.status          === 'fulfilled' && _udRes.value && typeof _udRes.value === 'object')              ? _udRes.value         : {};
  STATE.auditUpcoming   = (_upcomingRes.status    === 'fulfilled' && Array.isArray(_upcomingRes.value))                             ? _upcomingRes.value   : [];
  STATE.alertRules      = (_alertRulesRes.status  === 'fulfilled' && Array.isArray(_alertRulesRes.value))                           ? _alertRulesRes.value : [];
  STATE.alertEvents     = (_alertEventsRes.status === 'fulfilled' && Array.isArray(_alertEventsRes.value))                          ? _alertEventsRes.value: [];
  STATE.activityEvents  = (_activityRes.status    === 'fulfilled' && Array.isArray(_activityRes.value))                             ? _activityRes.value   : [];
  // Populate channelMessages from all-channels response and keep teamChatHistory in sync
  const _allMsgs = (_teamMsgsRes.status === 'fulfilled' && _teamMsgsRes.value && typeof _teamMsgsRes.value === 'object' && !Array.isArray(_teamMsgsRes.value))
    ? _teamMsgsRes.value : null;
  if (_allMsgs) {
    const _toChEntry = m => ({
      id: m.id || null,
      from: m.from, text: m.text,
      time: m.createdAt ? new Date(m.createdAt).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'}) : '',
      createdAt: m.createdAt || null,
      read: true, self: !!m.self, attachmentUrl: m.attachmentUrl||null, attachmentName: m.attachmentName||null,
    });
    STATE.channelMessages = {
      general:  (Array.isArray(_allMsgs.general)  ? _allMsgs.general  : []).map(_toChEntry),
      seo:      (Array.isArray(_allMsgs.seo)       ? _allMsgs.seo      : []).map(_toChEntry),
      rapports: (Array.isArray(_allMsgs.rapports)  ? _allMsgs.rapports : []).map(_toChEntry),
      support:  (Array.isArray(_allMsgs.support)   ? _allMsgs.support  : []).map(_toChEntry),
    };
  } else if (!STATE.channelMessages) {
    STATE.channelMessages = {general:[],seo:[],rapports:[],support:[]};
  }
  STATE.teamChatHistory = (STATE.channelMessages[STATE.msgChannel||'general'] || []).map(m => ({
    id: m.id || null, from: m.from, msg: m.text || (m.attachmentName ? `📎 ${m.attachmentName}` : ''),
    time: m.time, createdAt: m.createdAt || null, attachmentUrl: m.attachmentUrl||null, attachmentName: m.attachmentName||null,
  }));
  const _apiNotifs      = _notifsRes.status       === 'fulfilled' ? _notifsRes.value   : null;
  STATE.notifications   = Array.isArray(_apiNotifs) ? _apiNotifs : Array.isArray(_apiNotifs?.notifications) ? _apiNotifs.notifications : [];
  if (_domain) {
    const _blData  = _blRes.status  === 'fulfilled' ? _blRes.value  : null;
    const _llmData = _llmRes.status === 'fulfilled' ? _llmRes.value : null;
    if (_blData  && typeof _blData  === 'object') STATE.backlinks     = _blData;  else STATE.backlinks     = null;
    if (_llmData && typeof _llmData === 'object') STATE.llmVisibility = _llmData; else STATE.llmVisibility = null;
  }

  const _clientsRaw = (_clientsRes.status === 'fulfilled' && Array.isArray(_clientsRes.value)) ? _clientsRes.value : [];
  STATE.clients = _clientsRaw.filter(c => c.name);
  const _calRaw = (_calRes.status === 'fulfilled' && Array.isArray(_calRes.value)) ? _calRes.value : [];
  STATE.calendarEvents = _calRaw.map(e => ({
    id: e.id, title: e.title, site: e.site||'', type: e.type||'Autre',
    date: e.date||'', startTime: e.startTime||'', duration: e.duration||60, notes: e.notes||'',
  }));

  // ── Checklist from server (P0-01: replaces localStorage) ──────────────────
  if (_clRes && _clRes.status === 'fulfilled' && _clRes.value && typeof _clRes.value === 'object') {
    if (Array.isArray(_clRes.value.items)) STATE.checklist = _clRes.value.items;
    if (_clRes.value.extra && typeof _clRes.value.extra === 'object') STATE.checklistExtra = _clRes.value.extra;
  }
  const _storage = _storageRes.status === 'fulfilled' ? _storageRes.value : null;
  if (_storage && typeof _storage === 'object' && ('counts' in _storage || 'totalBytes' in _storage)) { STATE.storage = _storage; }

  const _prefs = _prefsRes.status === 'fulfilled' ? _prefsRes.value : null;
  if (_prefs) {
    if (typeof _prefs.streak === 'number') STATE.streak = _prefs.streak;
    if (_prefs.pinned && typeof _prefs.pinned === 'object') STATE.pinned = _prefs.pinned;
    var _serverHasItems = _clRes?.status === 'fulfilled' && Array.isArray(_clRes.value?.items) && _clRes.value.items.length > 0;
    var _serverHasExtra = _clRes?.status === 'fulfilled' && _clRes.value?.extra && Object.keys(_clRes.value.extra).length > 0;
    var _serverHasData  = _serverHasItems || _serverHasExtra;
    if (!_serverHasData && _prefs?.checklist && !localStorage.getItem('fp-checklist-migrated')) {
      STATE.checklist = _prefs.checklist;
      if (_prefs.checklist_extra && typeof _prefs.checklist_extra === 'object') STATE.checklistExtra = _prefs.checklist_extra;
      apiAction('PUT', '/api/overview/checklist', { items: _prefs.checklist, extra: _prefs.checklist_extra || {} })
        .then(function() { localStorage.setItem('fp-checklist-migrated', '1'); })
        .catch(function() { /* network failure — keep local data, retry on next load */ });
    } else if (!_serverHasData && _prefs?.checklist_extra && typeof _prefs.checklist_extra === 'object') {
      STATE.checklistExtra = _prefs.checklist_extra;
    }
    if (_prefs.settings && typeof _prefs.settings === 'object') {
      STATE.settings = { ...STATE.settings, ..._prefs.settings };
      // Theme priority: manual-local > backend-manual > auto-system.
      // A valid localStorage entry written by a prior manual toggle must
      // never be overwritten by backend prefs (backend may still have
      // themeAuto:true from before the user toggled manually).
      const _localManualTheme = localStorage.getItem('fp:theme');
      if (_localManualTheme) {
        STATE.theme = _localManualTheme;
        STATE.themeManual = true;
      } else if (_prefs.settings.themeAuto) {
        STATE.theme = 'dark';
        STATE.themeManual = false;
      } else if (_prefs.settings.theme) {
        STATE.theme = _prefs.settings.theme;
        STATE.themeManual = true;
      }
      applyTheme();
      // Apply language preference from server immediately after load
      if (_prefs.settings.language) {
        try { document.documentElement.lang = String(_prefs.settings.language).split('-')[0]; } catch(_) {}
      }
    }
  }

  // Compute streak from activity events when server prefs don't provide one.
  // If today has no events yet (partial day), skip d=0 and start from yesterday
  // so a user with a perfect chain through yesterday still sees a non-zero streak.
  if (!STATE.streak && STATE.activityEvents.length > 0) {
    const activeDays = new Set(STATE.activityEvents.map(e => String(e.createdAt || e.created_at || '').slice(0, 10)));
    const _todayStr = new Date(Date.now()).toISOString().slice(0, 10);
    const _startOffset = activeDays.has(_todayStr) ? 0 : 1; // skip today if no events yet
    let _s = 0;
    for (let _d = _startOffset; _d < 365; _d++) {
      if (activeDays.has(new Date(Date.now() - _d * 86400000).toISOString().slice(0, 10))) { _s++; } else { break; }
    }
    if (_s > 0) {
      STATE.streak = _s;
      localStorage.setItem('fp:streak', String(_s));
      // Persist computed streak to the server so it survives fresh browser sessions
      apiAction('PATCH', '/api/me/prefs', { streak: _s }).catch(function() {});
    }
  }

  // ── Phase 5: API module data — all parallel ───────────────────────────────────
  await Promise.allSettled([
    window.FP_MISSIONS_API
      ? window.FP_MISSIONS_API.load().then(r => { STATE.missions = r ?? (PREVIEW_MODE ? MOCK_MISSIONS : []); })
      : Promise.resolve().then(() => { STATE.missions = PREVIEW_MODE ? MOCK_MISSIONS : []; }),
    window.FP_KEYWORDS_API
      ? window.FP_KEYWORDS_API.load().then(r => { if (r) STATE.keywords = r; })
      : Promise.resolve(),
    window.FP_COMPETITORS_API
      ? window.FP_COMPETITORS_API.load().then(r => { if (r) STATE.competitors = r; })
      : Promise.resolve(),
    window.FP_CONNECTORS_API
      ? window.FP_CONNECTORS_API.load().then(r => { if (r) STATE.connectors = r; })
      : Promise.resolve(),
    // ── Google integrations status (GA4 / GSC / GBP / OAuth) ────────────────
    apiFetch('/api/ga4/status').then(r => {
      if (r && typeof r === 'object') {
        if (!window.FP_DATA || typeof window.FP_DATA !== 'object') window.FP_DATA = {};
        window.FP_DATA.ga4 = r;
        STATE.ga4Status = r;
      }
    }).catch(() => {}),
    apiFetch('/api/gsc/status').then(r => {
      if (r && typeof r === 'object') STATE.gsc = { ...(STATE.gsc || {}), ...r };
    }).catch(() => {}),
    apiFetch('/api/google/status').then(r => {
      if (r && typeof r === 'object') STATE.googleConnected = r;
    }).catch(() => {}),
    window.FP_GBP_API ? window.FP_GBP_API.load().catch(() => {}) : Promise.resolve(),
    // ── Billing subscription + plans ────────────────────────────────────────────
    apiFetch('/api/billing/subscription').then(r => {
      if (r && typeof r === 'object') {
        const _rawDate = r.currentPeriodEnd || r.trialEndsAt || null;
        const _nextDate = _rawDate ? new Date(_rawDate).toLocaleDateString('fr-FR', {day:'2-digit',month:'2-digit',year:'numeric'}) : null;
        const _planAmtMap = { standard:29, pro:79, ultra:149, agency:149 };
        const _nextAmount = r.nextAmount ?? _planAmtMap[(r.plan||'').toLowerCase()] ?? null;
        STATE.billing = { ...(STATE.billing || {}), ...r, nextDate: _nextDate, nextAmount: _nextAmount };
      }
    }).catch(() => {}),
    apiFetch('/api/billing/plans').then(r => {
      if (Array.isArray(r)) STATE.billingPlans = r;
      else if (r && Array.isArray(r.plans)) STATE.billingPlans = r.plans;
    }).catch(() => {}),
    apiFetch('/api/billing/invoices').then(r => {
      if (r && Array.isArray(r.invoices)) STATE.billing = { ...(STATE.billing || {}), invoices: r.invoices };
    }).catch(() => {}),
    apiFetch('/api/billing/payment-methods').then(r => {
      if (r && Array.isArray(r.paymentMethods)) STATE.billing = { ...(STATE.billing || {}), paymentMethods: r.paymentMethods };
    }).catch(() => {}),
    apiFetch('/api/cro').then(r => {
      if (r && typeof r === 'object' && !window.FP_DATA?.cro?._fromRealData) {
        if (!window.FP_DATA) window.FP_DATA = {};
        window.FP_DATA.croApi = r;
      }
    }).catch(() => {}),
    apiFetch('/api/revenue-leak').then(r => {
      if (r && typeof r === 'object') { if (!window.FP_DATA) window.FP_DATA = {}; window.FP_DATA.revenueLeak = r; }
    }).catch(() => {}),
    apiFetch('/api/review-intelligence').then(r => {
      if (r && typeof r === 'object') { if (!window.FP_DATA) window.FP_DATA = {}; window.FP_DATA.reviewIntelligence = r; }
    }).catch(() => {}),
    apiFetch('/api/market-intelligence').then(r => {
      if (r && typeof r === 'object') { if (!window.FP_DATA) window.FP_DATA = {}; window.FP_DATA.marketIntelligence = r; }
    }).catch(() => {}),
    apiFetch('/api/team/files').then(r => {
      if (Array.isArray(r)) STATE.teamFiles = r;
      else if (r && Array.isArray(r.files)) STATE.teamFiles = r.files;
    }).catch(() => {}),
    // Login history — real data from user_sessions (replaces empty sso_login_audits)
    apiFetch('/api/sessions').then(function(r) {
      if (r && Array.isArray(r.sessions) && r.sessions.length > 0) {
        STATE.loginHistory = r.sessions;
      }
    }).catch(function() {}),
  ]);

  STATE.growthObjectives = await apiFetch('/api/growth/objectives').then(r => Array.isArray(r) ? r : []).catch(() => []);

  // Apply pinned state
  STATE.audits   = STATE.audits.map(a => ({ ...a, pinned: !!(STATE.pinned['audit_'+a.id]) }));
  STATE.monitors = STATE.monitors.map(m => ({ ...m, pinned: !!(STATE.pinned['monitor_'+m.id]) }));

  // ── Compute derived metrics from real API data ─────────────────────────────
  const _audAvg = STATE.audits.length ? Math.round(STATE.audits.reduce((s,a)=>s+(a.score||0),0)/STATE.audits.length) : 0;
  const _monUp  = STATE.monitors.length ? Math.round(STATE.monitors.filter(m=>m.status==='up').length/STATE.monitors.length*100) : 100;
  const _missDone = (STATE.missions||[]).filter(m=>m.status==='done'||m.done).length;
  const _engScore = Math.min(5, Math.floor(_missDone / 3)) * 10;
  STATE.userScore = STATE.overview?.userScore ?? Math.round((_audAvg * 0.5 + _monUp * 0.3 + Math.min(100, 50 + _engScore) * 0.2));

  // ── Mandatory final render — all data now in STATE ───────────────────────────
  // ── Persist STATE to sessionStorage cache (stale-while-revalidate) ─────────
  try {
    sessionStorage.setItem('fp-state-cache', JSON.stringify({
      _ts: Date.now(), me: STATE.me, overview: STATE.overview,
      audits: STATE.audits.slice(0,50), monitors: STATE.monitors.slice(0,50),
      reports: STATE.reports.slice(0,20), team: STATE.team,
      alertRules: STATE.alertRules, notifications: STATE.notifications.slice(0,20),
      ga4Status: STATE.ga4Status, gsc: STATE.gsc, googleConnected: STATE.googleConnected,
    }));
  } catch(_) { /* sessionStorage full or unavailable */ }

  console.debug('[FP] loadData complete — audits:', STATE.audits.length,
    'monitors:', STATE.monitors.length, 'missions:', (STATE.missions||[]).length,
    'keywords:', (STATE.keywords||[]).length, 'competitors:', (STATE.competitors||[]).length,
    'reports:', STATE.reports.length, 'activityEvents:', (STATE.activityEvents||[]).length);
  render();

  // ── Intelligence Engine: compute real insights from STATE data ───────────────
  if (typeof window.FP_DATA !== 'object' || window.FP_DATA === null) window.FP_DATA = {};
  // ── Restore persisted PSI results from localStorage (survive page reload) ──
  try {
    if (!window.FP_DATA.pagespeed) {
      var _psiSaved = localStorage.getItem('fp-psi-last');
      if (_psiSaved) {
        var _psiParsed = JSON.parse(_psiSaved);
        // Accept cached PSI up to 7 days old
        if (_psiParsed && _psiParsed.data && (Date.now() - (_psiParsed._ts || 0)) < 7 * 24 * 3600 * 1000) {
          window.FP_DATA.pagespeed = _psiParsed.data;
        }
      }
    }
  } catch(_psiErr) {}
  // CRO Intelligence — populated from audits + monitors when no CRO API is connected
  if (!window.FP_DATA.cro || !window.FP_DATA.cro._fromRealData) {
    const _iAudAvg = STATE.audits.length ? Math.round(STATE.audits.reduce((s,a)=>s+(a.score||0),0)/STATE.audits.length) : 65;
    const _iSpdAvg = STATE.audits.filter(a=>a.speed!=null).length
      ? Math.round(STATE.audits.filter(a=>a.speed!=null).reduce((s,a)=>s+(a.speed||0),0)/STATE.audits.filter(a=>a.speed!=null).length) : 60;
    const _iUpPct  = STATE.monitors.length
      ? Math.round(STATE.monitors.filter(m=>m.status==='up').length/STATE.monitors.length*100) : 100;
    const _ib = (v,lo,hi) => Math.min(hi, Math.max(lo, v));
    const _iRecs = [];
    STATE.monitors.filter(m=>m.status==='down').forEach(m =>
      _iRecs.push({ priority:'critical', title:`Remettre en ligne : ${m.name}`, detail:`Ce monitor est DOWN — chaque minute de downtime coûte des conversions directes.`, effort:'Immédiat', gain:'Arrêt des pertes', week:1 }));
    if (_iSpdAvg < 70)
      _iRecs.push({ priority:'high', title:'Optimiser la vitesse de chargement', detail:`Score vitesse moyen ${_iSpdAvg}/100. Chaque seconde supplémentaire réduit le taux de conversion de 7%. Objectif : passer au-dessus de 80.`, effort:'1 semaine', gain:'+15-25% conv.', week:1 });
    if (_iAudAvg < 70)
      _iRecs.push({ priority:'high', title:'Corriger les problèmes SEO critiques', detail:`Score SEO moyen ${_iAudAvg}/100 — moins de trafic qualifié = moins de conversions potentielles.`, effort:'2 semaines', gain:'+10-20% trafic', week:1 });
    STATE.audits.filter(a=>a.issues>5).slice(0,3).forEach(a => {
      const _d = (()=>{try{return new URL(a.url).hostname;}catch(_){return a.url||'';}})();
      _iRecs.push({ priority:'medium', title:`Corriger ${a.issues} problèmes sur ${_d}`, detail:'Problèmes techniques détectés au dernier audit — peuvent bloquer les robots et freiner les conversions.', effort:'1-2 jours', gain:'+5-10% conv.', week:2 });
    });
    _iRecs.push({ priority:'medium', title:'Simplifier les formulaires de contact', detail:'Réduire le nombre de champs à 3 maximum augmente les conversions de 25% en moyenne.', effort:'1 jour', gain:'+25% leads', week:2 });
    _iRecs.push({ priority:'medium', title:'Ajouter preuves sociales (avis, témoignages)', detail:'Les sites avec avis visibles en above-the-fold convertissent 2× mieux.', effort:'2-3 jours', gain:'×2 confiance', week:3 });
    _iRecs.push({ priority:'low', title:'Mettre en place le suivi des micro-conversions', detail:'Connectez GA4 ou Matomo pour tracker les clics CTA, scrolls et formulaires en temps réel.', effort:'1/2 jour', gain:'Pilotage data', week:4 });
    window.FP_DATA.cro = {
      _fromRealData: true,
      scores: [{ overallScore:_ib(_iAudAvg-8,20,99), copyScore:_ib(_iAudAvg-18,20,99), frictionScore:_ib(_iSpdAvg-5,20,99), mobileScore:_ib(_iSpdAvg-16,20,99), ctaScore:_ib(_iAudAvg-12,20,99), formScore:_ib(_iUpPct-10,20,99), retentionScore:_ib(_iAudAvg-6,20,99) }],
      recommendations: _iRecs,
    };
  }
  // Revenue Leak Intelligence — computed from audits + monitors
  if (!window.FP_DATA.revenueLeak || !window.FP_DATA.revenueLeak._fromRealData) {
    const _rlLeaks = [];
    STATE.monitors.filter(m=>m.status==='down').forEach(m => {
      const _uptime = (m.uptime != null) ? m.uptime : 99;
      _rlLeaks.push({ id:'rl_mon_'+m.id, type:'availability', title:`Site DOWN : ${m.name}`, monthly:'Pertes directes en cours', severity:'critical', fix:"Résoudre l'incident immédiatement", url:m.url||'' });
    });
    STATE.audits.filter(a=>a.speed!=null&&a.speed<50).slice(0,5).forEach(a => {
      const _d = (()=>{try{return new URL(a.url).hostname;}catch(_){return a.url||'';}})();
      _rlLeaks.push({ id:'rl_spd_'+a.id, type:'performance', title:`Vitesse critique : ${_d}`, monthly:`~${Math.round((100-a.speed)*15)}€/mois estimés perdus`, severity:'high', fix:'Optimiser images (WebP), activer le cache navigateur, passer à HTTP/2', url:a.url||'' });
    });
    STATE.audits.filter(a=>a.score<50).slice(0,5).forEach(a => {
      const _d = (()=>{try{return new URL(a.url).hostname;}catch(_){return a.url||'';}})();
      _rlLeaks.push({ id:'rl_seo_'+a.id, type:'seo', title:`Score SEO critique : ${_d}`, monthly:'Trafic organique manqué', severity:'high', fix:'Corriger balises title/meta, liens cassés, contenu dupliqué', url:a.url||'' });
    });
    window.FP_DATA.revenueLeak = {
      _fromRealData: true,
      leaks: _rlLeaks,
      summary: _rlLeaks.length > 0
        ? { totalMonthly:`${_rlLeaks.length} fuite${_rlLeaks.length>1?'s':''} détectée${_rlLeaks.length>1?'s':''}`, topIssue: _rlLeaks[0]?.type||'performance' }
        : null,
    };
  }

  // ── Save to sessionStorage for next load (stale-while-revalidate) ─────────────
  try {
    sessionStorage.setItem('fp-state-cache', JSON.stringify({
      _ts: Date.now(),
      me: STATE.me, overview: STATE.overview,
      audits: STATE.audits, monitors: STATE.monitors,
      reports: STATE.reports, team: STATE.team,
      alertRules: STATE.alertRules, notifications: STATE.notifications,
      ga4Status: STATE.ga4Status, gsc: STATE.gsc,
      googleConnected: STATE.googleConnected,
    }));
  } catch(_) {}

  // AI credits — best-effort, non-blocking (re-renders when resolved)
  loadAICredits().then(() => render()).catch(() => {});

  // Fetch 30-day checks summary for each monitor (best-effort, non-blocking)
  // Re-renders the monitors view when each summary resolves so sparklines appear immediately
  if (STATE.monitors.length > 0) {
    let pendingRender = false;
    const scheduleRender = () => {
      if (pendingRender) return;
      pendingRender = true;
      requestAnimationFrame(() => {
        pendingRender = false;
        if (STATE.route === 'monitors') render();
      });
    };
    Promise.allSettled(
      STATE.monitors.map(m =>
        apiFetch(`/api/monitors/${m.id}/checks-summary`)
          .then(data => { if (Array.isArray(data)) { STATE.monitorsSummary[m.id] = data; scheduleRender(); } })
          .catch(() => {})
      )
    ).catch(() => {});
  }
}

