function openEmojiPicker(targetInputId, anchorEl) {
  // Remove any existing picker and its stale listener
  document.getElementById('fp-emoji-picker')?.remove();
  if (window._fpEmojiOutsideClose) {
    document.removeEventListener('click', window._fpEmojiOutsideClose);
    window._fpEmojiOutsideClose = null;
  }

  const pickerState = { cat: Object.keys(EMOJI_CATEGORIES)[0], q: '' };

  const picker = document.createElement('div');
  picker.id = 'fp-emoji-picker';

  const rect = anchorEl ? anchorEl.getBoundingClientRect() : { bottom: 200, left: 100, top: 180 };
  const vw = window.innerWidth;
  const vh = window.innerHeight;
  const pickerW = Math.min(330, vw - 16);
  const left = Math.max(8, Math.min(rect.left, vw - pickerW - 8));
  const spaceBelow = vh - rect.bottom - 10;
  const top = spaceBelow >= 360 ? rect.bottom + 6 : Math.max(8, rect.top - 366);
  picker.style.cssText = `position:fixed;z-index:99999;top:${top}px;left:${left}px;width:${pickerW}px`;

  function closePicker() {
    picker.remove();
    if (window._fpEmojiOutsideClose) {
      document.removeEventListener('click', window._fpEmojiOutsideClose);
      window._fpEmojiOutsideClose = null;
    }
  }

  function renderPicker() {
    const cats = Object.keys(EMOJI_CATEGORIES);
    const emojis = pickerState.q
      ? Object.values(EMOJI_CATEGORIES).flat().filter(e => e.includes(pickerState.q))
      : EMOJI_CATEGORIES[pickerState.cat] || [];
    picker.innerHTML = `
      <input id="fp-emoji-search" placeholder="Rechercher…" value="${pickerState.q}" autocomplete="off"/>
      <div class="fp-emoji-cats">
        ${cats.map(k => `<button class="fp-emoji-cat-btn${k===pickerState.cat&&!pickerState.q?' active':''}" data-cat="${k}">${k}</button>`).join('')}
      </div>
      <div class="fp-emoji-grid">
        ${emojis.map(e => `<div class="fp-emoji-item" data-e="${e}">${e}</div>`).join('')}
      </div>
    `;
    picker.querySelector('#fp-emoji-search').addEventListener('input', function() {
      pickerState.q = this.value;
      renderPicker();
      picker.querySelector('#fp-emoji-search').focus();
    });
    picker.querySelectorAll('.fp-emoji-cat-btn').forEach(btn => btn.addEventListener('click', e => {
      e.stopPropagation();
      pickerState.cat = btn.dataset.cat; pickerState.q = ''; renderPicker();
    }));
    picker.querySelectorAll('.fp-emoji-item').forEach(item => item.addEventListener('click', e => {
      e.stopPropagation();
      const inp = targetInputId ? document.getElementById(targetInputId) : null;
      if (inp) {
        const pos = (inp.selectionStart != null ? inp.selectionStart : inp.value.length);
        inp.value = inp.value.slice(0, pos) + item.dataset.e + inp.value.slice(pos);
        inp.focus();
        try { inp.setSelectionRange(pos + item.dataset.e.length, pos + item.dataset.e.length); } catch(_) {}
      }
      closePicker();
    }));
  }
  renderPicker();
  document.body.appendChild(picker);
  setTimeout(() => {
    window._fpEmojiOutsideClose = function outsideClose(e) {
      if (!picker.contains(e.target) && !e.target.closest('[id^="fp-emoji-trigger"]')) {
        closePicker();
      }
    };
    document.addEventListener('click', window._fpEmojiOutsideClose);
  }, 20);
}

