// ══════════════════════════════════════════════════════════════════════
// GA4 ANALYTICS — VUE D\'ENSEMBLE
// ══════════════════════════════════════════════════════════════════════
function renderGA4Analytics() {
  const _anaS = window._fpAnalyticsState || {};
  if (!_anaS.loaded && !_anaS.loading) setTimeout(() => window._fpAnalyticsAPI.loadAll(), 60);
  if (_anaS.loading && !(_anaS.data?.overview) && !(window.FP_DATA?.ga4?.overview)) return _fpAnaLoadingSkeleton();
  if (_anaS.error  && !(_anaS.data?.overview) && !(window.FP_DATA?.ga4?.overview)) return _fpAnaErrorSkeleton(_anaS.error);
  const ga4    = _anaS.data || window.FP_DATA?.ga4 || {};
  const ov     = ga4.overview;
  const rows   = ov?.rows || [];
  const totals = ov?.totals?.[0]?.metricValues || [];

  const sessions   = totals[0] ? parseFloat(totals[0].value) : 0;
  const users      = totals[1] ? parseFloat(totals[1].value) : 0;
  const newUsers   = totals[2] ? parseFloat(totals[2].value) : 0;
  const bounce     = totals[3] ? parseFloat(totals[3].value) * 100 : 0;
  const engage     = totals[4] ? parseFloat(totals[4].value) * 100 : 0;
  const avgDur     = totals[5] ? parseFloat(totals[5].value) : 0;
  const pageviews  = totals[6] ? parseFloat(totals[6].value) : 0;
  const conversions= totals[7] ? parseFloat(totals[7].value) : 0;

  const prevTotals = ov?.totals?.[1]?.metricValues || [];
  const prevSess     = prevTotals[0] ? parseFloat(prevTotals[0].value) : 0;
  const prevUsers    = prevTotals[1] ? parseFloat(prevTotals[1].value) : 0;
  const prevNewUsers = prevTotals[2] ? parseFloat(prevTotals[2].value) : 0;
  const prevConv     = prevTotals[7] ? parseFloat(prevTotals[7].value) : 0;

  const sessArr = rows.map(r => parseFloat(r.metricValues?.[0]?.value || 0));
  const daysLabels = rows.map(r => {
    const d = r.dimensionValues?.[0]?.value || '';
    return d.length === 8 ? `${d.slice(6,8)}/${d.slice(4,6)}` : d;
  });

  const fmtNum = n => n >= 1000000 ? (n/1000000).toFixed(1)+'M' : n >= 1000 ? (n/1000).toFixed(1)+'k' : Math.round(n).toLocaleString('fr-FR');
  const fmtDur = s => { const m = Math.floor(s/60); const sec = Math.round(s%60); return `${m}m${sec.toString().padStart(2,'0')}s`; };

  const sub    = STATE.subRoute || ga4.sub || 'overview';
  if (sub === 'connect') return _renderGA4Connect();
  if (sub === 'realtime') return _renderGA4Realtime();
  if (sub === 'pages') return _renderGA4Pages();
  if (sub === 'conversions') return _renderGA4Conversions();

  return `
    <div class="fp-section-header">
      <div>
        <h1 style="display:flex;align-items:center;gap:10px">
          📊 Analytics GA4
          ${_ga4Connected() ? `<span style="font-size:11px;font-weight:600;padding:3px 10px;background:rgba(34,197,94,0.15);border:1px solid rgba(34,197,94,0.3);border-radius:20px;color:#22c55e">● Connecté</span>` : `<span style="font-size:11px;font-weight:600;padding:3px 10px;background:rgba(239,68,68,0.12);border:1px solid rgba(239,68,68,0.3);border-radius:20px;color:#ef4444">Non connecté</span>`}
        </h1>
        <div class="fp-section-sub">${_ga4Connected() ? `Propriété : ${escHtml(_ga4Property())} · Dernières 30 jours` : 'Connectez Google Analytics 4 pour voir vos données réelles'}</div>
      </div>
      <div class="fp-section-actions">
        <select id="fp-ga4-period" onchange="if(!_ga4Connected()){navigateSub('connect');return;}window.FP_GA4_API&&window.FP_GA4_API.reload(parseInt(this.value))"
          style="background:var(--fp-track);border:1px solid var(--fp-border);border-radius:6px;color:var(--fp-text);font-size:12px;padding:5px 8px">
          <option value="7">7 jours</option>
          <option value="30" selected>30 jours</option>
          <option value="90">90 jours</option>
          <option value="180">6 mois</option>
        </select>
        <button class="fp-btn fp-btn-ghost fp-btn-sm" onclick="if(!_ga4Connected()){navigateSub('connect');showToast('info','Connectez GA4 pour exporter vos données');return;}window.FP_GA4_API&&window.FP_GA4_API.export()">📥 Export</button>
        <button class="fp-btn fp-btn-ghost fp-btn-sm" onclick="if(!_ga4Connected()){navigateSub('connect');return;}window.FP_GA4_API&&window.FP_GA4_API.reload()">🔄 Actualiser</button>
        <button class="fp-btn fp-btn-primary fp-btn-sm" onclick="navigate('live')">🔴 Live</button>
      </div>
    </div>

    ${_ga4NotConnectedBanner()}

    ${aiBlock(_ga4Connected()
      ? (()=>{
          const _sess=sessions?fmtNum(sessions)+' sessions':null;
          const _conv=conversions?fmtNum(conversions)+' conversion(s)':null;
          const _delta=prevSess>0?Math.round((sessions-prevSess)/prevSess*100):null;
          return 'GA4 connecté — '+(_sess||'données en cours de chargement')+(conversions?' · <strong>'+_conv+'</strong>':'')+((_delta!=null)?(_delta>=0?' · <strong style="color:#22c55e">+'+_delta+'%</strong> sessions vs période précédente':' · <strong style="color:#ef4444">'+_delta+'%</strong> sessions vs période précédente'):'')+'.'
        })()
      : 'Google Analytics 4 n\'est pas encore connecté. Connectez votre propriété GA4 pour accéder aux données de trafic, sessions et conversions en temps réel.',
      _ga4Connected()
        ? ['Voir les pages', 'Analyser conversions', 'Rapport trafic']
        : ['Connecter GA4', 'Voir la démo']
    )}

    ${aiBlock(
      _ga4Connected()
        ? sessions > 0
          ? `<strong>${fmtNum(sessions)}</strong> sessions · <strong>${fmtNum(users)}</strong> utilisateurs sur 30 jours. Taux de conversion : <strong>${sessions ? ((conversions||0)/sessions*100).toFixed(2) : '0.00'}%</strong>. ${conversions > 0 ? 'Bonne performance de conversion. Analysez les sources les plus rentables.' : 'Aucune conversion trackée — configurez les événements GA4.'}`
          : "Données GA4 chargées. Sélectionnez une période ou actualisez pour voir vos métriques."
        : "Connectez Google Analytics 4 pour accéder à l'analyse complète de votre trafic, conversions et audience.",
      _ga4Connected() ? ['Voir le trafic','Analyser l\'audience','Rapport analytics'] : ['Connecter GA4','Voir la démo','En savoir plus']
    )}

    <!-- KPI CARDS -->
    <div class="fp-stat-row fp-mb-20">
      ${_ga4KPICard('📈', 'Sessions', sessions>0?fmtNum(sessions):(_ga4Connected()?'0':'—'), _ga4Connected()&&sessions>0&&prevSess>0?_ga4PctChange(sessions, prevSess):null, 'vs période préc.')}
      ${_ga4KPICard('👥', 'Utilisateurs', users>0?fmtNum(users):(_ga4Connected()?'0':'—'), _ga4Connected()&&users>0&&prevUsers>0?_ga4PctChange(users, prevUsers):null, users>0?`dont ${Math.round((newUsers||0)/Math.max(users,1)*100)}% nouveaux`:'—')}
      ${_ga4KPICard('📄', 'Pages vues', pageviews>0?fmtNum(pageviews):(_ga4Connected()?'0':'—'), null, sessions&&pageviews?`${(pageviews/sessions).toFixed(1)} pages/session`:'—')}
      ${_ga4KPICard('⚡', 'Conversions', conversions>0?fmtNum(conversions):(_ga4Connected()?'0':'—'), _ga4Connected()&&conversions>0&&prevConv>0?_ga4PctChange(conversions, prevConv):null, sessions&&conversions?`taux : ${(conversions/sessions*100).toFixed(2)}%`:'—')}
      ${_ga4KPICard('⏱️', 'Durée moy.', avgDur>0?fmtDur(avgDur):(_ga4Connected()?'0m00s':'—'), null, 'par session')}
      ${_ga4KPICard('💡', 'Engagement', engage>0?`${engage.toFixed(1)}%`:(_ga4Connected()?'0%':'—'), null, `Bounce : ${bounce>0?bounce.toFixed(1)+'%':'—'}`)}
      ${_ga4KPICard('🆕', 'Nouveaux utilisateurs', newUsers>0?fmtNum(newUsers):(_ga4Connected()?'0':'—'), _ga4Connected()&&newUsers>0&&prevNewUsers>0?_ga4PctChange(newUsers, prevNewUsers):null, newUsers&&users?`${Math.round(newUsers/Math.max(users,1)*100)}% du total`:'—')}
      ${_ga4KPICard('↩️', 'Taux de rebond', bounce>0?`${bounce.toFixed(1)}%`:(_ga4Connected()?'0%':'—'), null, 'moy. secteur : 42%')}
    </div>

    <!-- SESSIONS CHART + CHANNEL BREAKDOWN -->
    <div class="fp-grid-2 fp-mb-20">
      <div class="fp-card">
        <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:14px">
          <div class="fp-card-title" style="margin-bottom:0">Sessions — ${daysLabels.length ? daysLabels[0]+' → '+daysLabels[daysLabels.length-1] : '30 derniers jours'}</div>
          <span style="font-size:11px;color:var(--fp-text-faint)">${rows.length} jours</span>
        </div>
        ${sessArr.length >= 2 ? `
          <div style="position:relative;height:80px;overflow:hidden">
            <svg viewBox="0 0 600 80" preserveAspectRatio="none" style="width:100%;height:80px">
              <defs>
                <linearGradient id="ga4grad" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="0%" stop-color="#2563EB" stop-opacity="0.3"/>
                  <stop offset="100%" stop-color="#2563EB" stop-opacity="0.01"/>
                </linearGradient>
              </defs>
              ${(() => {
                const max = Math.max(...sessArr, 1);
                const pts = sessArr.map((v,i) => `${(i/(sessArr.length-1))*600},${80-(v/max)*70}`);
                const fill = [...pts, `600,80`, `0,80`];
                return `<polygon points="${fill.join(' ')}" fill="url(#ga4grad)"/>
                  <polyline points="${pts.join(' ')}" fill="none" stroke="#2563EB" stroke-width="2" stroke-linejoin="round"/>`;
              })()}
            </svg>
            <div style="display:flex;justify-content:space-between;margin-top:4px">
              ${daysLabels.filter((_,i) => i % Math.ceil(daysLabels.length/6) === 0).map(l => `<span style="font-size:9px;color:var(--fp-text-faint)">${l}</span>`).join('')}
            </div>
          </div>
        ` : `<div style="height:80px;display:flex;align-items:center;justify-content:center;color:var(--fp-text-muted);font-size:12px">Chargement des données…</div>`}
      </div>

      <div class="fp-card">
        <div class="fp-card-title" style="margin-bottom:14px">📡 Canaux d\'acquisition</div>
        ${(() => {
          const srcRows = ga4.sources?.rows || [];
          const chMap = {};
          srcRows.forEach(r => {
            const ch = r.dimensionValues?.[0]?.value || 'Direct';
            const s  = parseFloat(r.metricValues?.[0]?.value || 0);
            chMap[ch] = (chMap[ch] || 0) + s;
          });
          const total = Object.values(chMap).reduce((a,b) => a+(b), 0);
          if (!Object.keys(chMap).length) return `<div style="padding:20px;text-align:center;color:var(--fp-text-muted);font-size:12px">${_ga4Connected() ? '⏳ Actualisez vos données GA4 pour voir vos canaux d\'acquisition.<br><button class="fp-btn fp-btn-ghost fp-btn-sm" style="margin-top:8px" onclick="window.FP_GA4_API&&window.FP_GA4_API.reload()">🔄 Actualiser</button>' : '🔌 Connectez Google Analytics 4 pour voir vos canaux d\'acquisition.<br><button class="fp-btn fp-btn-primary fp-btn-sm" style="margin-top:10px" onclick="window.FP_GA4_API&&window.FP_GA4_API.connectGoogle()">Connecter GA4</button>'}</div>`;
          const sorted = Object.entries(chMap).sort((a,b) => (b[1])-(a[1])).slice(0,6);
          return sorted.map(([ch, s]) => {
            const color = GA4_CHANNEL_COLORS[ch] || '#64748b';
            return _ga4ChannelRow(ch, s, Math.round((s)/Math.max(total,1)*100), color);
          }).join('');
        })()}
      </div>
    </div>

    <!-- AI INSIGHTS + NEW vs RETURNING -->
    <div class="fp-grid-2 fp-mb-20">
      <div class="fp-card">
        <div class="fp-card-title" style="margin-bottom:14px">🧠 Insights IA — Résumé</div>
        ${(() => {
          if (!_ga4Connected()) return `<div style="padding:16px;text-align:center"><div style="font-size:13px;color:var(--fp-text-muted);margin-bottom:10px">🔌 Connectez GA4 pour des insights basés sur vos vraies données.</div><div style="font-size:11px;color:var(--fp-text-faint);margin-bottom:12px">L'IA analysera : sessions, conversions, rebond, sources de trafic.</div><button class="fp-btn fp-btn-primary fp-btn-sm" onclick="window.FP_GA4_API&&window.FP_GA4_API.connectGoogle()">Connecter GA4</button></div>`;
          const _ins = [];
          if (sessions > 0 && prevSess > 0) { const d=Math.round((sessions-prevSess)/prevSess*100); _ins.push({icon:d>=0?'📈':'📉',color:d>=0?'#22c55e':'#ef4444',title:`Sessions ${d>=0?'en hausse':'en baisse'} (${d>=0?'+':''}${d}%)`,desc:`${sessions.toLocaleString('fr-FR')} sessions vs ${prevSess.toLocaleString('fr-FR')} période précédente.`}); }
          if (bounce > 0) _ins.push({icon:bounce>50?'⚠️':'✅',color:bounce>50?'#f59e0b':'#22c55e',title:`Taux de rebond : ${bounce.toFixed(1)}%`,desc:bounce>50?'Taux élevé — optimisez le contenu et la vitesse de chargement.':'Bon engagement — les visiteurs explorent votre site.'});
          const _sr2=ga4.sources?.rows||[];if(_sr2.length){const _cm2={};_sr2.forEach(r=>{const ch=r.dimensionValues?.[0]?.value||'Other';const s2=parseFloat(r.metricValues?.[0]?.value||0);_cm2[ch]=(_cm2[ch]||0)+s2;});const _top=Object.entries(_cm2).sort((a,b)=>b[1]-a[1])[0];const _tot2=Object.values(_cm2).reduce((a,b)=>a+b,0)||1;if(_top)_ins.push({icon:'🎯',color:'#2563EB',title:`Canal principal : ${_top[0]}`,desc:`${Math.round(_top[1]/_tot2*100)}% de votre trafic. Diversifiez vos sources pour réduire la dépendance.`});}
          if (conversions > 0 && sessions > 0) { const cr=(conversions/sessions*100).toFixed(2); _ins.push({icon:'⚡',color:'#8b5cf6',title:`Taux de conversion : ${cr}%`,desc:parseFloat(cr)<2?'Sous la moyenne (2%). Analysez le parcours et les points de friction.':'Bonne performance de conversion.'}); }
          if(!_ins.length) return `<div style="padding:16px;text-align:center;font-size:12px;color:var(--fp-text-muted)">Actualisez vos données GA4 pour générer des insights.<br><button class="fp-btn fp-btn-ghost fp-btn-sm" style="margin-top:8px" onclick="window.FP_GA4_API&&window.FP_GA4_API.reload()">🔄 Actualiser</button></div>`;
          return _ins.map(x=>`<div style="display:flex;align-items:flex-start;gap:10px;padding:8px 10px;border-radius:8px;background:${x.color}08;border-left:3px solid ${x.color};margin-bottom:6px"><span style="font-size:16px;flex-shrink:0">${x.icon}</span><div><div style="font-size:12px;font-weight:700;color:var(--fp-text);margin-bottom:2px">${x.title}</div><div style="font-size:11px;color:var(--fp-text-muted)">${x.desc}</div></div></div>`).join('');
        })()}
      </div>

      <div class="fp-card">
        <div class="fp-card-title" style="margin-bottom:14px">🔄 Nouveaux vs Récurrents</div>
        ${(() => {
          const nvr = ga4.audience?.newVsReturn?.rows || [];
          let newU = newUsers || 0, retU = Math.max(0, (users || 0) - newU);
          nvr.forEach(r => {
            if (r.dimensionValues?.[0]?.value === 'new') newU = parseFloat(r.metricValues?.[0]?.value || newU);
            else retU = parseFloat(r.metricValues?.[0]?.value || retU);
          });
          if (!newU && !retU) return `<div style="padding:24px;text-align:center;font-size:12px;color:var(--fp-text-muted)">${_ga4Connected() ? '⏳ Actualisez vos données GA4 pour voir la répartition nouveaux/récurrents.' : '🔌 Connectez GA4 pour voir la répartition de votre audience.'}</div>`;
          const total = newU + retU || 1;
          const newPct = Math.round(newU/total*100);
          const retPct = 100-newPct;
          return `
            <div style="display:flex;height:12px;border-radius:6px;overflow:hidden;margin-bottom:16px">
              <div style="width:${newPct}%;background:#2563EB"></div>
              <div style="width:${retPct}%;background:#22c55e"></div>
            </div>
            <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px">
              ${[{l:'Nouveaux',v:fmtNum(newU),p:newPct,c:'#2563EB'},{l:'Récurrents',v:fmtNum(retU),p:retPct,c:'#22c55e'}].map(x=>`
                <div style="padding:12px;background:${x.c}08;border:1px solid ${x.c}20;border-radius:10px;text-align:center">
                  <div style="font-size:22px;font-weight:900;color:${x.c};font-family:var(--fp-font-head)">${x.v}</div>
                  <div style="font-size:11px;color:var(--fp-text-muted);margin-top:2px">${x.l} (${x.p}%)</div>
                </div>
              `).join('')}
            </div>
            <div style="margin-top:14px;font-size:11px;color:var(--fp-text-muted)">
              🎯 <strong style="color:#2563EB">${newPct}%</strong> nouveaux visiteurs — objectif : retargeting pour augmenter la récurrence
            </div>`;
        })()}
      </div>
    </div>

    <!-- TOP PAGES PREVIEW -->
    <div class="fp-card">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:14px">
        <div class="fp-card-title" style="margin-bottom:0">📄 Top Pages d\'atterrissage</div>
        <button class="fp-btn fp-btn-ghost fp-btn-sm" onclick="navigateSub('pages')">Tout voir →</button>
      </div>
      <table style="width:100%;border-collapse:collapse;font-size:12px">
        <thead><tr style="border-bottom:1px solid var(--fp-border)">
          ${['Page','Vues','Utilisateurs','Rebond','Durée moy.'].map(h=>`<th style="padding:6px 10px;text-align:left;font-size:10px;color:var(--fp-text-faint);font-weight:600">${h}</th>`).join('')}
        </tr></thead>
        <tbody>
          ${(ga4.pages?.rows || []).slice(0,8).map(r => {
            const path = r.dimensionValues?.[0]?.value || '/';
            const title = r.dimensionValues?.[1]?.value || path;
            const views = parseFloat(r.metricValues?.[0]?.value || 0);
            const users_ = parseFloat(r.metricValues?.[1]?.value || 0);
            const dur   = parseFloat(r.metricValues?.[2]?.value || 0);
            const bnc   = parseFloat(r.metricValues?.[3]?.value || 0)*100;
            return `<tr style="border-bottom:1px solid rgba(255,255,255,0.03)">
              <td style="padding:8px 10px"><div style="font-weight:600;color:var(--fp-text);max-width:220px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${escHtml(path)}">${escHtml(title.slice(0,40))}</div><div style="font-size:10px;color:var(--fp-text-faint)">${escHtml(path.slice(0,40))}</div></td>
              <td style="padding:8px 10px;font-weight:700">${views.toLocaleString('fr-FR')}</td>
              <td style="padding:8px 10px">${users_.toLocaleString('fr-FR')}</td>
              <td style="padding:8px 10px"><span style="color:${bnc>50?'#ef4444':bnc>35?'#f59e0b':'#22c55e'}">${bnc.toFixed(1)}%</span></td>
              <td style="padding:8px 10px;font-size:11px">${fmtDur(dur)}</td>
            </tr>`;
          }).join('') || `<tr><td colspan="5" style="padding:20px;text-align:center;color:var(--fp-text-muted)">
            ${_ga4Connected() ? 'Chargement des pages…' : 'Connectez GA4 pour voir vos top pages'}
            ${_ga4Connected() ? `<br><button class="fp-btn fp-btn-ghost fp-btn-sm" style="margin-top:8px" onclick="window.FP_GA4_API&&window.FP_GA4_API.reload()">🔄 Charger</button>` : ''}
          </td></tr>`}
        </tbody>
      </table>
    </div>
  `;
}

// ── GA4 Sub-pages ─────────────────────────────────────────────────────────────
function _renderGA4Connect() {
  const ga4 = window.FP_DATA?.ga4 || {};
  const props = ga4.properties || [];
  return `
    <div class="fp-section-header"><div><h1>⚙ Configuration GA4</h1><div class="fp-section-sub">Connectez et configurez votre propriété Google Analytics 4</div></div></div>

    <!-- STEP 1: OAuth -->
    <div class="fp-card fp-mb-20">
      <div style="display:flex;align-items:center;gap:12px;margin-bottom:16px">
        <div style="width:32px;height:32px;border-radius:50%;background:${ga4.connected?'#22c55e':'rgba(37,99,235,0.2)'};display:flex;align-items:center;justify-content:center;color:${ga4.connected?'#fff':'#2563EB'};font-weight:800;flex-shrink:0">${ga4.connected?'✓':'1'}</div>
        <div><div style="font-size:14px;font-weight:700;color:var(--fp-text)">Connexion Google</div><div style="font-size:11px;color:var(--fp-text-muted)">Autorisez FlowPoint à lire vos données Analytics</div></div>
        ${ga4.connected ? `<span style="margin-left:auto;font-size:11px;color:#22c55e;font-weight:700">✓ Connecté</span>` : `<button class="fp-btn fp-btn-primary" style="margin-left:auto" onclick="window.FP_GA4_API&&window.FP_GA4_API.connectGoogle()">Connecter Google</button>`}
      </div>
    </div>

    <!-- STEP 2: Property selection -->
    <div class="fp-card fp-mb-20" style="opacity:${ga4.connected?'1':'0.5'}">
      <div style="display:flex;align-items:center;gap:12px;margin-bottom:16px">
        <div style="width:32px;height:32px;border-radius:50%;background:${ga4.propertyId?'#22c55e':'rgba(255,255,255,0.06)'};display:flex;align-items:center;justify-content:center;color:${ga4.propertyId?'#fff':'var(--fp-text-muted)'};font-weight:800;flex-shrink:0">${ga4.propertyId?'✓':'2'}</div>
        <div><div style="font-size:14px;font-weight:700;color:var(--fp-text)">Sélectionner la propriété</div><div style="font-size:11px;color:var(--fp-text-muted)">Choisissez la propriété GA4 à analyser dans FlowPoint</div></div>
      </div>
      ${props.length ? `
        <div style="display:grid;gap:8px">
          ${props.slice(0,10).map(p => `
            <div style="padding:12px 14px;border:1px solid ${ga4.propertyId===p.name?'#2563EB':'var(--fp-border)'};border-radius:8px;cursor:pointer;background:${ga4.propertyId===p.name?'rgba(37,99,235,0.08)':'transparent'};display:flex;align-items:center;justify-content:space-between"
              onclick="window.FP_GA4_API&&window.FP_GA4_API.selectProperty('${escHtml(p.name)}','${escHtml(p.displayName||p.name)}')">
              <div>
                <div style="font-size:12px;font-weight:700;color:var(--fp-text)">${escHtml(p.displayName||p.name)}</div>
                <div style="font-size:10px;color:var(--fp-text-faint)">${escHtml(p.name)}</div>
              </div>
              ${ga4.propertyId===p.name?`<span style="color:#22c55e;font-weight:700">✓</span>`:''}
            </div>
          `).join('')}
        </div>
      ` : ga4.connected ? `
        <button class="fp-btn fp-btn-ghost fp-btn-sm" onclick="window.FP_GA4_API&&window.FP_GA4_API.loadProperties()">🔄 Charger les propriétés</button>
      ` : `<div style="font-size:11px;color:var(--fp-text-muted)">Connectez d\'abord votre compte Google pour voir les propriétés disponibles.</div>`}

      <!-- Manual entry -->
      <div style="margin-top:12px;padding:12px;background:var(--fp-inner-card);border-radius:8px">
        <div style="font-size:11px;color:var(--fp-text-muted);margin-bottom:8px">Ou entrez l\'ID de propriété manuellement (ex: 123456789)</div>
        <div style="display:flex;gap:8px;flex-wrap:wrap">
          <input id="fp-ga4-pid" type="text" placeholder="123456789" style="flex:1;min-width:100px;background:var(--fp-inner-card);border:1px solid var(--fp-border);border-radius:6px;color:var(--fp-text);font-size:12px;padding:6px 10px">
          <input id="fp-ga4-pname" type="text" placeholder="Nom de la propriété" style="flex:2;min-width:140px;background:var(--fp-inner-card);border:1px solid var(--fp-border);border-radius:6px;color:var(--fp-text);font-size:12px;padding:6px 10px">
          <button class="fp-btn fp-btn-primary fp-btn-sm" onclick="window.FP_GA4_API&&window.FP_GA4_API.selectProperty(document.getElementById('fp-ga4-pid').value,'',true)">Valider</button>
        </div>
      </div>
    </div>

    ${ga4.propertyId ? `
      <div class="fp-card" style="border-color:rgba(34,197,94,0.3);background:rgba(34,197,94,0.04)">
        <div style="text-align:center;padding:16px">
          <div style="font-size:36px;margin-bottom:8px">✅</div>
          <div style="font-size:14px;font-weight:700;color:#22c55e;margin-bottom:4px">GA4 configuré — ${escHtml(ga4.propertyName || ga4.propertyId)}</div>
          <div style="font-size:11px;color:var(--fp-text-muted);margin-bottom:12px">Les données Analytics sont maintenant disponibles dans toutes les sections.</div>
          <button class="fp-btn fp-btn-primary" onclick="navigate('analytics')">📊 Voir les Analytics →</button>
        </div>
      </div>
    ` : ''}
  `;
}

function _renderGA4Realtime() {
  const rt = window.FP_DATA?.ga4?.realtime || {};
  const active = rt.activeUsers || 0;
  const rows   = rt.rows || [];
  const pages  = {};
  const cities = {};
  const devices = {};
  rows.forEach(r => {
    const city   = r.dimensionValues?.[1]?.value || 'Inconnu';
    const page   = r.dimensionValues?.[2]?.value || '/';
    const device = r.dimensionValues?.[3]?.value || 'desktop';
    const users_ = parseInt(r.metricValues?.[0]?.value || 1);
    pages[page]    = (pages[page]   || 0) + users_;
    cities[city]   = (cities[city]  || 0) + users_;
    devices[device]= (devices[device]||0) + users_;
  });
  return `
    <div class="fp-section-header">
      <div><h1>Live Analytics — Temps réel</h1><div class="fp-section-sub">Données actualisées toutes les 30 secondes</div></div>
      <div class="fp-section-actions">
        <button class="fp-btn fp-btn-primary fp-btn-sm" onclick="window.FP_GA4_API&&window.FP_GA4_API.refreshRealtime()">🔄 Actualiser</button>
      </div>
    </div>
    <div style="text-align:center;padding:32px;margin-bottom:20px">
      <div style="font-size:88px;font-weight:900;color:#ef4444;font-family:var(--fp-font-head);line-height:1;margin-bottom:8px;animation:pulse 2s infinite">${_ga4Connected() ? active : '—'}</div>
      <div style="font-size:16px;color:var(--fp-text-muted);font-weight:600">utilisateurs actifs en ce moment</div>
    </div>
    <div class="fp-grid-2 fp-mb-20">
      <div class="fp-card">
        <div class="fp-card-title" style="margin-bottom:12px">📄 Pages actives</div>
        ${Object.entries(pages).sort((a,b)=>(b[1])-(a[1])).slice(0,8).map(([p,u])=>`
          <div style="display:flex;align-items:center;gap:8px;padding:5px 0;border-bottom:1px solid rgba(255,255,255,0.04)">
            <div style="flex:1;font-size:11px;color:var(--fp-text);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${escHtml(p)}</div>
            <span style="font-size:11px;font-weight:700;color:#ef4444">${u} actifs</span>
          </div>`).join('') || `<div style="font-size:11px;color:var(--fp-text-muted);text-align:center;padding:16px">${_ga4Connected()?'Chargement…':'Connectez GA4'}</div>`}
      </div>
      <div class="fp-card">
        <div class="fp-card-title" style="margin-bottom:12px">🌍 Localisation live</div>
        ${Object.entries(cities).sort((a,b)=>(b[1])-(a[1])).slice(0,8).map(([c,u])=>`
          <div style="display:flex;align-items:center;gap:8px;padding:5px 0;border-bottom:1px solid rgba(255,255,255,0.04)">
            <div style="flex:1;font-size:11px;color:var(--fp-text)">${escHtml(c)}</div>
            <div class="fp-progress-track" style="width:60px;height:4px"><div class="fp-progress-fill" style="width:${Math.min((u)/Math.max(...Object.values(cities))*100,100)}%"></div></div>
            <span style="font-size:11px;font-weight:700;color:var(--fp-text)">${u}</span>
          </div>`).join('') || `<div style="font-size:11px;color:var(--fp-text-muted);text-align:center;padding:16px">${_ga4Connected()?'Chargement…':'Connectez GA4'}</div>`}
      </div>
    </div>
  `;
}

function _renderGA4Pages() {
  const rows = window.FP_DATA?.ga4?.pages?.rows || [];
  const fmtDur = s => { const m=Math.floor(s/60); return `${m}m${Math.round(s%60).toString().padStart(2,'0')}s`; };
  return `
    <div class="fp-section-header"><div><h1>📄 Top Pages</h1><div class="fp-section-sub">Performance des pages d\'atterrissage et de contenu</div></div>
      <div class="fp-section-actions"><button class="fp-btn fp-btn-ghost fp-btn-sm" onclick="window.FP_GA4_API&&window.FP_GA4_API.reload()">🔄 Actualiser</button></div>
    </div>
    <div class="fp-card">
      <div style="overflow-x:auto;-webkit-overflow-scrolling:touch">
      <table style="width:100%;min-width:600px;border-collapse:collapse;font-size:12px">
        <thead><tr style="border-bottom:1px solid var(--fp-border)">
          ${['Page','Titre','Vues','Utilisateurs','Durée moy.','Rebond','Entrées','Sorties'].map(h=>`<th style="padding:6px 10px;text-align:left;font-size:10px;color:var(--fp-text-faint);font-weight:600;white-space:nowrap">${h}</th>`).join('')}
        </tr></thead>
        <tbody>${rows.slice(0,50).map((r,i) => {
          const path  = r.dimensionValues?.[0]?.value||'/';
          const title = r.dimensionValues?.[1]?.value||path;
          const views = parseFloat(r.metricValues?.[0]?.value||0);
          const usrs  = parseFloat(r.metricValues?.[1]?.value||0);
          const dur   = parseFloat(r.metricValues?.[2]?.value||0);
          const bnc   = parseFloat(r.metricValues?.[3]?.value||0)*100;
          const entr  = parseFloat(r.metricValues?.[4]?.value||0);
          const exits = parseFloat(r.metricValues?.[5]?.value||0);
          return `<tr style="border-bottom:1px solid rgba(255,255,255,0.03)">
            <td style="padding:7px 10px"><div style="font-size:11px;font-family:var(--fp-font-mono);color:var(--fp-text-muted);max-width:180px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${escHtml(path)}</div></td>
            <td style="padding:7px 10px"><div style="font-size:11px;color:var(--fp-text);max-width:200px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${escHtml(title.slice(0,50))}</div></td>
            <td style="padding:7px 10px;font-weight:700">${views.toLocaleString('fr-FR')}</td>
            <td style="padding:7px 10px">${usrs.toLocaleString('fr-FR')}</td>
            <td style="padding:7px 10px;font-size:11px">${fmtDur(dur)}</td>
            <td style="padding:7px 10px"><span style="color:${bnc>50?'#ef4444':bnc>35?'#f59e0b':'#22c55e'};font-weight:700">${bnc.toFixed(1)}%</span></td>
            <td style="padding:7px 10px;font-size:11px">${entr.toLocaleString('fr-FR')}</td>
            <td style="padding:7px 10px;font-size:11px">${exits.toLocaleString('fr-FR')}</td>
          </tr>`;
        }).join('')||`<tr><td colspan="8" style="padding:24px;text-align:center;color:var(--fp-text-muted)">${_ga4Connected()?'Chargement…<br><button class="fp-btn fp-btn-ghost fp-btn-sm" style="margin-top:8px" onclick="window.FP_GA4_API&&window.FP_GA4_API.reload()">🔄 Charger</button>':'Connectez GA4'}</td></tr>`}</tbody>
      </table>
      </div>
    </div>
  `;
}

function _renderGA4Conversions() {
  const rows = window.FP_DATA?.ga4?.conversions?.rows || [];
  return `
    <div class="fp-section-header"><div><h1>⚡ Conversions & Objectifs</h1><div class="fp-section-sub">Événements de conversion trackés dans GA4</div></div>
      <div class="fp-section-actions"><button class="fp-btn fp-btn-ghost fp-btn-sm" onclick="window.FP_GA4_API&&window.FP_GA4_API.reload()">🔄 Actualiser</button></div>
    </div>
    <div class="fp-card">
      <div style="overflow-x:auto;-webkit-overflow-scrolling:touch">
      <table style="width:100%;min-width:440px;border-collapse:collapse;font-size:12px">
        <thead><tr style="border-bottom:1px solid var(--fp-border)">
          ${['Événement','Canal','Conversions','Utilisateurs','Sessions'].map(h=>`<th style="padding:6px 10px;text-align:left;font-size:10px;color:var(--fp-text-faint);font-weight:600;white-space:nowrap">${h}</th>`).join('')}
        </tr></thead>
        <tbody>${rows.slice(0,30).map(r => {
          const ev   = r.dimensionValues?.[0]?.value||'unknown';
          const ch   = r.dimensionValues?.[1]?.value||'—';
          const conv = parseFloat(r.metricValues?.[0]?.value||0);
          const usrs = parseFloat(r.metricValues?.[1]?.value||0);
          const sess = parseFloat(r.metricValues?.[2]?.value||0);
          return `<tr style="border-bottom:1px solid rgba(255,255,255,0.03)">
            <td style="padding:7px 10px;font-weight:700;color:var(--fp-text)">${escHtml(ev)}</td>
            <td style="padding:7px 10px"><span style="font-size:10px;padding:2px 7px;border-radius:6px;background:${(GA4_CHANNEL_COLORS[ch]||'#64748b')}18;color:${GA4_CHANNEL_COLORS[ch]||'#94a3b8'};font-weight:600">${escHtml(ch)}</span></td>
            <td style="padding:7px 10px;font-weight:800;color:#22c55e;font-size:13px">${conv.toLocaleString('fr-FR')}</td>
            <td style="padding:7px 10px">${usrs.toLocaleString('fr-FR')}</td>
            <td style="padding:7px 10px">${sess.toLocaleString('fr-FR')}</td>
          </tr>`;
        }).join('')||`<tr><td colspan="5" style="padding:24px;text-align:center;color:var(--fp-text-muted)">${_ga4Connected()?'Chargement des conversions…':'Connectez GA4'}</td></tr>`}</tbody>
      </table>
      </div>
    </div>
  `;
}

// ══════════════════════════════════════════════════════════════════════
// GA4 TRAFFIC — SOURCES & CANAUX
// ══════════════════════════════════════════════════════════════════════
// ══════════════════════════════════════════════════════════════════════
// GA4 CONVERSION — Real data from /api/conversion/* endpoints
// No Math.random, no PREVIEW_MODE fallbacks, no hardcoded metrics.
// Conversion rates: conversions / sessions × 100  (null when sessions = 0)
// Revenue per conversion: totalRevenue / conversions (null when 0 conversions)
// ══════════════════════════════════════════════════════════════════════
function renderGA4Conversion() {
  const sub = STATE.subRoute;
  if (sub && ['funnel','ux-lab','cta','revenue-leak','cro'].includes(sub)) {
    return renderConversion();
  }

  const cvS = window._fpConversionState || {};
  if (!cvS.loaded && !cvS.loading) setTimeout(() => window._fpConversionAPI.loadAll(), 60);
  if (cvS.loading && !cvS.data) return _fpConvLoadingSkeleton();
  if (cvS.error  && !cvS.data) return _fpConvErrorSkeleton(cvS.error);

  const days    = cvS.days || 30;
  const data    = cvS.data || {};
  const connected = data.connected;

  const periodSel = `
    <select onchange="window._fpConversionAPI.loadAll(parseInt(this.value))"
      style="background:var(--fp-track);border:1px solid var(--fp-border);border-radius:6px;color:var(--fp-text);font-size:12px;padding:5px 8px">
      <option value="7"  ${days===7?'selected':''}>7 jours</option>
      <option value="30" ${days===30?'selected':''}>30 jours</option>
      <option value="90" ${days===90?'selected':''}>90 jours</option>
    </select>
    <button class="fp-btn fp-btn-ghost fp-btn-sm" onclick="window._fpConversionAPI.refresh()">🔄 Actualiser</button>`;

  const header = `
    <div class="fp-section-header">
      <div><h1>🎯 Conversion GA4</h1><div class="fp-section-sub">Événements de conversion, revenus et landing pages — ${days} derniers jours</div></div>
      <div class="fp-section-actions">${periodSel}</div>
    </div>`;

  // ── DISCONNECTED STATE ─────────────────────────────────────────────
  if (!connected) {
    return header + `
      <div style="text-align:center;padding:56px 24px;background:var(--fp-inner-card);border:1px dashed var(--fp-border);border-radius:14px;margin-bottom:20px">
        <div style="font-size:40px;margin-bottom:14px">🔌</div>
        <div style="font-size:16px;font-weight:700;color:var(--fp-text);margin-bottom:8px">Google Analytics 4 non connecté</div>
        <div style="font-size:13px;color:var(--fp-text-muted);max-width:480px;margin:0 auto 20px">
          Connectez GA4 pour afficher vos conversions réelles, revenus, landing pages et analyses par source.
        </div>
        <button class="fp-btn fp-btn-primary" onclick="navigate('integrations')">Connecter GA4</button>
      </div>`;
  }

  const ov      = data.overview   || {};
  const events  = data.events     || [];
  const pages   = data.pages      || [];
  const sources = data.sources    || [];
  const devices = data.devices    || [];
  const geo     = data.geo        || [];

  const fmt    = n => (n != null && n !== '') ? Number(n).toLocaleString('fr-FR', {maximumFractionDigits:0}) : '—';
  const fmtPct = n => n != null ? Number(n).toFixed(2) + '%' : '—';
  const fmtRev = n => (n != null && n > 0) ? Number(n).toFixed(2) + '\u202f€' : '—';

  const totalConv  = data.totalConversions || ov.conversions || 0;
  const totalRev   = data.totalRevenue     || 0;
  const convRate   = ov.conversionRate;
  const sessions   = ov.sessions;
  const users      = ov.users;
  const avgRevConv = data.avgRevenuePerConversion;
  const convDiff   = ov.conversionRateDiff;

  // ── EMPTY STATE ────────────────────────────────────────────────────
  if (totalConv === 0 && events.length === 0) {
    return header + `
      <div style="text-align:center;padding:48px 24px;background:var(--fp-inner-card);border:1px dashed var(--fp-border);border-radius:14px;margin-bottom:20px">
        <div style="font-size:36px;margin-bottom:12px">🎯</div>
        <div style="font-size:15px;font-weight:700;color:var(--fp-text);margin-bottom:8px">Aucune conversion GA4 sur la période</div>
        <div style="font-size:13px;color:var(--fp-text-muted);max-width:480px;margin:0 auto 16px">
          Aucun événement de conversion configuré ou aucune conversion enregistrée sur les ${days} derniers jours.<br>
          Configurez des <strong>Key Events</strong> dans GA4 pour commencer le suivi.
        </div>
        <button class="fp-btn fp-btn-ghost fp-btn-sm" onclick="window._fpConversionAPI.refresh()">🔄 Actualiser</button>
      </div>`;
  }

  // ── KPI CARDS ─────────────────────────────────────────────────────
  const kpiRow = `
    <div class="fp-stat-row fp-mb-20">
      <div class="fp-stat-card">
        <div class="fp-stat-label">Conversions totales</div>
        <div class="fp-stat-value">${fmt(totalConv)}</div>
        ${convDiff != null ? `<div class="fp-stat-sub" style="color:${convDiff>=0?'#22c55e':'#ef4444'}">${convDiff>=0?'+':''}${convDiff}% taux vs période préc.</div>` : '<div class="fp-stat-sub">—</div>'}
      </div>
      <div class="fp-stat-card">
        <div class="fp-stat-label">Taux de conversion</div>
        <div class="fp-stat-value">${fmtPct(convRate)}</div>
        <div class="fp-stat-sub">${sessions ? fmt(sessions) + ' sessions' : '—'}</div>
      </div>
      <div class="fp-stat-card">
        <div class="fp-stat-label">Revenus GA4</div>
        <div class="fp-stat-value">${fmtRev(totalRev)}</div>
        <div class="fp-stat-sub">${avgRevConv != null ? 'Moy./conv. ' + fmtRev(avgRevConv) : 'Revenus non configurés'}</div>
      </div>
      <div class="fp-stat-card">
        <div class="fp-stat-label">Utilisateurs</div>
        <div class="fp-stat-value">${fmt(users)}</div>
        <div class="fp-stat-sub">${events.length ? events.length + ' type(s) d\'événement' : '—'}</div>
      </div>
    </div>`;

  // ── CONVERSION EVENTS ─────────────────────────────────────────────
  const eventsBlock = events.length > 0 ? `
    <div class="fp-card fp-mb-20">
      <div class="fp-card-title" style="margin-bottom:14px">⚡ Événements de conversion</div>
      <div style="overflow-x:auto">
        <table style="width:100%;min-width:440px;border-collapse:collapse;font-size:12px">
          <thead><tr style="border-bottom:1px solid var(--fp-border)">
            ${['Événement','Conversions','Revenu','Revenu moy./conv.'].map(h=>`<th style="padding:6px 10px;text-align:left;font-size:10px;color:var(--fp-text-faint);font-weight:600">${h}</th>`).join('')}
          </tr></thead>
          <tbody>
            ${events.slice(0,20).map(ev => `
              <tr style="border-bottom:1px solid rgba(255,255,255,0.03)">
                <td style="padding:8px 10px;font-weight:700;color:var(--fp-text)">${escHtml(ev.name)}</td>
                <td style="padding:8px 10px;font-weight:800;color:#22c55e;font-size:13px">${fmt(ev.count)}</td>
                <td style="padding:8px 10px;color:var(--fp-text-muted)">${fmtRev(ev.revenue)}</td>
                <td style="padding:8px 10px;font-size:11px;color:var(--fp-text-muted)">${fmtRev(ev.avgRevenuePerConversion)}</td>
              </tr>`).join('')}
          </tbody>
        </table>
      </div>
    </div>` : `
    <div class="fp-card fp-mb-20" style="text-align:center;padding:28px">
      <div style="font-size:13px;color:var(--fp-text-muted)">Aucun événement de conversion trouvé.<br>Configurez des <strong>Key Events</strong> dans votre propriété GA4.</div>
    </div>`;

  // ── LANDING PAGES ─────────────────────────────────────────────────
  const pagesBlock = pages.length > 0 ? `
    <div class="fp-card fp-mb-20">
      <div class="fp-card-title" style="margin-bottom:14px">📄 Landing pages — conversions</div>
      <div style="overflow-x:auto">
        <table style="width:100%;min-width:500px;border-collapse:collapse;font-size:12px">
          <thead><tr style="border-bottom:1px solid var(--fp-border)">
            ${['Page','Sessions','Utilisateurs','Conversions','Taux','Revenu'].map(h=>`<th style="padding:6px 10px;text-align:left;font-size:10px;color:var(--fp-text-faint);font-weight:600">${h}</th>`).join('')}
          </tr></thead>
          <tbody>
            ${pages.slice(0,15).map(p => `
              <tr style="border-bottom:1px solid rgba(255,255,255,0.03)">
                <td style="padding:7px 10px;font-family:var(--fp-font-mono);font-size:11px;color:var(--fp-text-muted);max-width:220px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${escHtml(p.path)}">${escHtml(p.path)}</td>
                <td style="padding:7px 10px">${fmt(p.sessions)}</td>
                <td style="padding:7px 10px">${fmt(p.users)}</td>
                <td style="padding:7px 10px;font-weight:700;color:#22c55e">${fmt(p.conversions)}</td>
                <td style="padding:7px 10px;font-weight:700;color:${p.conversionRate>2?'#22c55e':p.conversionRate>0.5?'#f59e0b':'var(--fp-text-muted)'}">${fmtPct(p.conversionRate)}</td>
                <td style="padding:7px 10px">${fmtRev(p.revenue)}</td>
              </tr>`).join('')}
          </tbody>
        </table>
      </div>
    </div>` : '';

  // ── SOURCES + DEVICES + GEO ───────────────────────────────────────
  const sourcesBlock = sources.length > 0 ? `
    <div class="fp-card fp-mb-20">
      <div class="fp-card-title" style="margin-bottom:14px">🚦 Sources — conversions</div>
      <div style="overflow-x:auto">
        <table style="width:100%;min-width:480px;border-collapse:collapse;font-size:12px">
          <thead><tr style="border-bottom:1px solid var(--fp-border)">
            ${['Canal','Source / Medium','Sessions','Conversions','Taux'].map(h=>`<th style="padding:6px 10px;text-align:left;font-size:10px;color:var(--fp-text-faint);font-weight:600">${h}</th>`).join('')}
          </tr></thead>
          <tbody>
            ${sources.slice(0,15).map(s => {
              const color = GA4_CHANNEL_COLORS[s.channel] || '#64748b';
              return `<tr style="border-bottom:1px solid rgba(255,255,255,0.03)">
                <td style="padding:7px 10px"><span style="font-size:10px;padding:2px 7px;border-radius:6px;background:${color}18;color:${color};font-weight:600">${escHtml(s.channel)}</span></td>
                <td style="padding:7px 10px;font-size:11px;font-family:var(--fp-font-mono);color:var(--fp-text-muted)">${escHtml(s.sourceMedium)}</td>
                <td style="padding:7px 10px">${fmt(s.sessions)}</td>
                <td style="padding:7px 10px;font-weight:700;color:#22c55e">${fmt(s.conversions)}</td>
                <td style="padding:7px 10px;font-weight:700">${fmtPct(s.conversionRate)}</td>
              </tr>`;
            }).join('')}
          </tbody>
        </table>
      </div>
    </div>` : '';

  const devicesBlock = devices.length > 0 ? `
    <div class="fp-card fp-mb-20">
      <div class="fp-card-title" style="margin-bottom:14px">📱 Appareils — conversions</div>
      <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:12px">
        ${devices.map(d => `
          <div class="fp-card" style="padding:14px 16px">
            <div style="font-size:12px;font-weight:700;color:var(--fp-text);margin-bottom:6px;text-transform:capitalize">${escHtml(d.device)}</div>
            <div style="font-size:22px;font-weight:900;color:#2563EB;font-family:var(--fp-font-head);margin-bottom:3px">${fmt(d.conversions)}</div>
            <div style="font-size:10px;color:var(--fp-text-faint);margin-bottom:6px">conversions · ${fmt(d.sessions)} sessions</div>
            <div style="font-size:11px;font-weight:700;color:${d.conversionRate>2?'#22c55e':d.conversionRate>0.5?'#f59e0b':'var(--fp-text-muted)'}">${fmtPct(d.conversionRate)} taux</div>
            ${d.revenue > 0 ? `<div style="font-size:10px;color:var(--fp-text-faint);margin-top:3px">${fmtRev(d.revenue)}</div>` : ''}
          </div>`).join('')}
      </div>
    </div>` : '';

  const geoBlock = geo.length > 0 ? `
    <div class="fp-card fp-mb-20">
      <div class="fp-card-title" style="margin-bottom:14px">🌍 Géographie — conversions</div>
      <div style="overflow-x:auto">
        <table style="width:100%;min-width:400px;border-collapse:collapse;font-size:12px">
          <thead><tr style="border-bottom:1px solid var(--fp-border)">
            ${['Pays','Ville','Sessions','Conversions','Taux','Revenu'].map(h=>`<th style="padding:6px 10px;text-align:left;font-size:10px;color:var(--fp-text-faint);font-weight:600">${h}</th>`).join('')}
          </tr></thead>
          <tbody>
            ${geo.slice(0,15).map(g => `
              <tr style="border-bottom:1px solid rgba(255,255,255,0.03)">
                <td style="padding:7px 10px;font-weight:600">${escHtml(g.country)}</td>
                <td style="padding:7px 10px;font-size:11px;color:var(--fp-text-muted)">${escHtml(g.city)}</td>
                <td style="padding:7px 10px">${fmt(g.sessions)}</td>
                <td style="padding:7px 10px;font-weight:700;color:#22c55e">${fmt(g.conversions)}</td>
                <td style="padding:7px 10px;font-weight:700">${fmtPct(g.conversionRate)}</td>
                <td style="padding:7px 10px">${fmtRev(g.revenue)}</td>
              </tr>`).join('')}
          </tbody>
        </table>
      </div>
    </div>` : '';

  return header + kpiRow + eventsBlock + pagesBlock + sourcesBlock + devicesBlock + geoBlock;
}

function renderGA4Traffic() {
  const _trafS = window._fpTrafficState || {};
  if (!_trafS.loaded && !_trafS.loading) setTimeout(() => window._fpTrafficAPI.loadAll(), 60);
  if (_trafS.loading && !(_trafS.data?.sources) && !(window.FP_DATA?.ga4?.sources)) return _fpTrafLoadingSkeleton();
  if (_trafS.error  && !(_trafS.data?.sources) && !(window.FP_DATA?.ga4?.sources)) return _fpTrafErrorSkeleton(_trafS.error);
  const ga4   = _trafS.data || window.FP_DATA?.ga4 || {};
  const rows  = ga4.sources?.rows || [];
  const sub   = STATE.subRoute || ga4.sub || null;

  const chMap = {};
  let totalSess = 0;
  rows.forEach(r => {
    const ch = r.dimensionValues?.[0]?.value || '(Other)';
    const sm = r.dimensionValues?.[1]?.value || '';
    const s  = parseFloat(r.metricValues?.[0]?.value || 0);
    const u  = parseFloat(r.metricValues?.[1]?.value || 0);
    const b  = parseFloat(r.metricValues?.[2]?.value || 0);
    const c  = parseFloat(r.metricValues?.[3]?.value || 0);
    const e  = parseFloat(r.metricValues?.[4]?.value || 0);
    if (!chMap[ch]) chMap[ch] = { sessions:0, users:0, bounceSum:0, conversions:0, engageSum:0, count:0, sources:[] };
    chMap[ch].sessions += s; chMap[ch].users += u; chMap[ch].bounceSum += b*s;
    chMap[ch].conversions += c; chMap[ch].engageSum += e*s; chMap[ch].count++;
    chMap[ch].sources.push({ sm, s, u, b, c });
    totalSess += s;
  });

  const channels = Object.entries(chMap).sort((a,b) => (b[1]).sessions - (a[1]).sessions);
  const total = totalSess;
  const displayCh = channels;

  return `
    <div class="fp-section-header">
      <div><h1>🚦 Trafic & Sources</h1><div class="fp-section-sub">Analyse de l\'acquisition — canaux, sources, médiums</div></div>
      <div class="fp-section-actions">
        <select onchange="window._fpTrafficAPI.loadAll(parseInt(this.value))"
          style="background:var(--fp-track);border:1px solid var(--fp-border);border-radius:6px;color:var(--fp-text);font-size:12px;padding:5px 8px">
          <option value="7">7 jours</option><option value="30" selected>30 jours</option><option value="90">90 jours</option>
        </select>
        <button class="fp-btn fp-btn-ghost fp-btn-sm" onclick="window._fpTrafficAPI.loadAll()">🔄 Actualiser</button>
      </div>
    </div>

    ${_ga4NotConnectedBanner()}

    ${aiBlock(
      _ga4Connected()
        ? channels.length > 0
          ? (() => {
              const _topCh = channels[0];
              const _topName = _topCh ? _topCh[0] : 'Organic Search';
              const _topPct  = _topCh ? Math.round((_topCh[1].sessions||0)/Math.max(totalSess,1)*100) : 0;
              const _orgCh   = channels.find(([c])=>c==='Organic Search');
              return `Canal principal : <strong>${_topName} (${_topPct}%)</strong>. ${_orgCh ? 'SEO organique : '+Math.round((_orgCh[1].sessions||0)/Math.max(totalSess,1)*100)+'% du trafic.' : ''} Diversifiez vos sources pour réduire la dépendance à un seul canal.`;
            })()
          : "Données de trafic en cours de chargement. Actualisez pour voir vos sources."
        : "Connectez GA4 pour analyser vos canaux d'acquisition et sources de trafic.",
      _ga4Connected() ? ['Voir les conversions','Analyser l\'audience','Rapport trafic'] : ['Connecter GA4']
    )}

    <!-- CHANNEL CARDS -->
    <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:12px;margin-bottom:20px">
      ${displayCh.slice(0,10).map(([ch, d]) => {
        const data = d;
        const s = data.sessions || 0;
        const pct = Math.round(s/total*100);
        const color = GA4_CHANNEL_COLORS[ch] || '#64748b';
        const bounce = data.count > 0 ? (data.bounceSum/s*100).toFixed(0) : '—';
        const engage = data.count > 0 ? (data.engageSum/s*100).toFixed(0) : '—';
        return `
          <div class="fp-card" style="border-top:3px solid ${color}">
            <div style="font-size:12px;font-weight:700;color:var(--fp-text);margin-bottom:8px">${ch}</div>
            <div style="font-size:24px;font-weight:900;color:${color};font-family:var(--fp-font-head);margin-bottom:4px">${s.toLocaleString('fr-FR')}</div>
            <div style="font-size:10px;color:var(--fp-text-faint);margin-bottom:8px">sessions · ${pct}% du total</div>
            <div class="fp-progress-track" style="height:4px;margin-bottom:8px"><div class="fp-progress-fill" style="width:${pct}%;background:${color}"></div></div>
            <div style="display:flex;gap:8px;font-size:10px;color:var(--fp-text-faint)">
              <span>Rebond: ${bounce}%</span><span>·</span><span>Engage: ${engage}%</span>
            </div>
          </div>`;
      }).join('')}
    </div>

    <!-- SOURCE/MEDIUM TABLE -->
    <div class="fp-card fp-mb-20">
      <div class="fp-card-title" style="margin-bottom:14px">📋 Source / Medium détaillé</div>
      <div style="overflow-x:auto;-webkit-overflow-scrolling:touch">
      <table style="width:100%;min-width:560px;border-collapse:collapse;font-size:12px">
        <thead><tr style="border-bottom:1px solid var(--fp-border)">
          ${['Canal','Source / Medium','Sessions','Utilisateurs','Rebond','Conversions','Engagement'].map(h=>`<th style="padding:6px 10px;text-align:left;font-size:10px;color:var(--fp-text-faint);font-weight:600;white-space:nowrap">${h}</th>`).join('')}
        </tr></thead>
        <tbody>
          ${rows.slice(0,25).map(r => {
            const ch  = r.dimensionValues?.[0]?.value||'(Other)';
            const sm  = r.dimensionValues?.[1]?.value||'unknown';
            const s   = parseFloat(r.metricValues?.[0]?.value||0);
            const u   = parseFloat(r.metricValues?.[1]?.value||0);
            const b   = parseFloat(r.metricValues?.[2]?.value||0)*100;
            const c   = parseFloat(r.metricValues?.[3]?.value||0);
            const e   = parseFloat(r.metricValues?.[4]?.value||0)*100;
            const color = GA4_CHANNEL_COLORS[ch]||'#64748b';
            return `<tr style="border-bottom:1px solid rgba(255,255,255,0.03)">
              <td style="padding:7px 10px"><span style="font-size:10px;padding:2px 7px;border-radius:6px;background:${color}18;color:${color};font-weight:600">${ch}</span></td>
              <td style="padding:7px 10px;font-size:11px;font-family:var(--fp-font-mono);color:var(--fp-text-muted)">${escHtml(sm)}</td>
              <td style="padding:7px 10px;font-weight:700">${s.toLocaleString('fr-FR')}</td>
              <td style="padding:7px 10px">${u.toLocaleString('fr-FR')}</td>
              <td style="padding:7px 10px"><span style="color:${b>50?'#ef4444':b>35?'#f59e0b':'#22c55e'};font-weight:700">${b.toFixed(1)}%</span></td>
              <td style="padding:7px 10px;color:#22c55e;font-weight:700">${c.toLocaleString('fr-FR')}</td>
              <td style="padding:7px 10px;font-size:11px">${e.toFixed(1)}%</td>
            </tr>`;
          }).join('')||`<tr><td colspan="7" style="padding:20px;text-align:center;color:var(--fp-text-muted)">${_ga4Connected()?'Chargement…':'Connectez GA4 pour voir les sources de trafic'}</td></tr>`}
        </tbody>
      </table>
      </div>
    </div>

        <!-- ANOMALY DETECTION -->
    <div class="fp-card">
      <div class="fp-card-title" style="margin-bottom:14px">⚠️ Détection d\'anomalies</div>
      <div style="padding:20px;text-align:center;font-size:12px;color:var(--fp-text-muted)">${_ga4Connected() ? '✅ Aucune anomalie détectée. La détection automatique analyse votre trafic au fil du temps.' : '🔌 Connectez GA4 pour activer la détection d\'anomalies sur votre trafic.'}</div>
    </div>
    `;
}

// ══════════════════════════════════════════════════════════════════════
// ══════════════════════════════════════════════════════════════════════
// GA4 FUNNELS — Configurable Funnel Builder
// Standalone — no dependency on window.FP_DATA.ga4.overview
// All JS at module scope (window._fpFunnel*) — script tags don't execute
// inside innerHTML. Uses apiFetch() for authenticated API calls.
// ══════════════════════════════════════════════════════════════════════

window._fpFunnelState = { loading: false, funnels: null, editing: null, running: null, runResult: null, runError: null };

// Escape HTML for safe rendering of user-supplied strings
function _fpFunnelEsc(s) {
  return String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
}

// Format ISO date to readable local string
function _fpFunnelFmtDate(iso) {
  if (!iso) return '—';
  try { return new Date(iso).toLocaleString('fr-FR', { dateStyle:'short', timeStyle:'short' }); } catch { return iso; }
}

// Render the funnel list section
function _fpFunnelRenderList(funnels) {
  const root = document.getElementById('fp-funnels-list-section');
  if (!root) return;
  if (!funnels || !funnels.length) {
    root.innerHTML = `
      <div style="text-align:center;padding:48px 24px;color:var(--fp-text-muted)">
        <div style="font-size:36px;margin-bottom:12px">🔵</div>
        <div style="font-size:15px;font-weight:600;margin-bottom:6px">Aucun funnel configuré</div>
        <div style="font-size:12px;margin-bottom:20px">Créez votre premier funnel de conversion GA4.</div>
        <button class="fp-btn fp-btn-primary" onclick="window._fpFunnelShowForm()">+ Nouveau funnel</button>
      </div>`;
    return;
  }
  root.innerHTML = `
    <div style="display:flex;flex-direction:column;gap:12px">
      ${funnels.map(f => `
        <div class="fp-card" style="padding:16px 18px">
          <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:12px">
            <div style="flex:1;min-width:0">
              <div style="font-size:14px;font-weight:700;color:var(--fp-text);margin-bottom:3px">${_fpFunnelEsc(f.name)}</div>
              <div style="font-size:11px;color:var(--fp-text-muted);margin-bottom:6px">${_fpFunnelEsc(f.site_url)} · ${Array.isArray(f.steps) ? f.steps.length : 0} étapes · ${f.is_open_funnel ? 'Ouvert' : 'Fermé'} · ${f.lookback_days}j</div>
              ${f.breakdown_dimension ? `<span style="font-size:10px;background:rgba(37,99,235,0.1);color:#2563EB;border-radius:4px;padding:2px 7px">${_fpFunnelEsc(f.breakdown_dimension)}</span>` : ''}
            </div>
            <div style="display:flex;gap:8px;flex-shrink:0;align-items:center">
              <button class="fp-btn fp-btn-ghost fp-btn-sm" data-fid="${_fpFunnelEsc(f.id)}" onclick="window._fpFunnelRun(this)" title="Exécuter">▶ Exécuter</button>
              <button class="fp-btn fp-btn-ghost fp-btn-sm" data-fid="${_fpFunnelEsc(f.id)}" onclick="window._fpFunnelEdit(this)" title="Éditer">✏️</button>
              <button class="fp-btn fp-btn-ghost fp-btn-sm" style="color:#ef4444" data-fid="${_fpFunnelEsc(f.id)}" data-fname="${_fpFunnelEsc(f.name)}" onclick="window._fpFunnelDelete(this)" title="Supprimer">🗑</button>
            </div>
          </div>
        </div>`).join('')}
    </div>`;
}

// Build the step editor rows HTML
function _fpFunnelStepRow(idx, step) {
  const pos    = step ? step.position : idx + 1;
  const name   = step ? step.name : '';
  const evName = step ? (step.event_name || '') : '';
  const ppmt   = step ? (step.page_path_match_type || 'EXACT') : 'EXACT';
  const ppv    = step ? (step.page_path_value || '') : '';
  const plmt   = step ? (step.page_location_match_type || 'EXACT') : 'EXACT';
  const plv    = step ? (step.page_location_value || '') : '';
  const ctype  = evName ? 'event' : (plv ? 'pageLocation' : 'pagePath');
  const matchOpts = ['EXACT','BEGINS_WITH','ENDS_WITH','CONTAINS','REGEXP','PARTIAL_REGEXP'];
  const mtSel = (sel, cur) => matchOpts.map(m => `<option value="${m}" ${m===cur?'selected':''}>${m}</option>`).join('');

  return `<div class="fp-funnel-step-row" style="background:var(--fp-bg-secondary,#f8fafc);border:1px solid var(--fp-border);border-radius:8px;padding:12px 14px;margin-bottom:8px" data-step-idx="${idx}">
    <div style="display:flex;align-items:center;gap:10px;margin-bottom:10px">
      <span style="font-size:12px;font-weight:700;color:var(--fp-text-muted);width:22px;text-align:center">${pos}</span>
      <input class="fp-input" style="flex:1" placeholder="Nom de l'étape" value="${_fpFunnelEsc(name)}" data-field="step-name-${idx}">
      <button class="fp-btn fp-btn-ghost fp-btn-sm" style="color:#ef4444;flex-shrink:0" onclick="window._fpFunnelRemoveStep(this)" data-idx="${idx}">✕</button>
    </div>
    <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-bottom:8px">
      <select class="fp-input" style="width:auto;font-size:12px" data-field="step-ctype-${idx}" onchange="window._fpFunnelToggleCtype(this)">
        <option value="event" ${ctype==='event'?'selected':''}>Événement</option>
        <option value="pagePath" ${ctype==='pagePath'?'selected':''}>Page path</option>
        <option value="pageLocation" ${ctype==='pageLocation'?'selected':''}>Page location (URL)</option>
      </select>
    </div>
    <div data-ctype-panel="event-${idx}" style="${ctype!=='event'?'display:none':''};display:${ctype==='event'?'flex':'none'};gap:8px">
      <input class="fp-input" style="flex:1;font-size:12px" placeholder="Nom de l'événement (ex: purchase)" value="${_fpFunnelEsc(evName)}" data-field="step-eventname-${idx}">
    </div>
    <div data-ctype-panel="pagePath-${idx}" style="display:${ctype==='pagePath'?'flex':'none'};gap:8px;flex-wrap:wrap">
      <select class="fp-input" style="width:auto;font-size:12px" data-field="step-ppmt-${idx}">${mtSel('ppmt', ppmt)}</select>
      <input class="fp-input" style="flex:1;font-size:12px" placeholder="/checkout/success" value="${_fpFunnelEsc(ppv)}" data-field="step-ppv-${idx}">
    </div>
    <div data-ctype-panel="pageLocation-${idx}" style="display:${ctype==='pageLocation'?'flex':'none'};gap:8px;flex-wrap:wrap">
      <select class="fp-input" style="width:auto;font-size:12px" data-field="step-plmt-${idx}">${mtSel('plmt', plmt)}</select>
      <input class="fp-input" style="flex:1;font-size:12px" placeholder="https://example.com/checkout" value="${_fpFunnelEsc(plv)}" data-field="step-plv-${idx}">
    </div>
  </div>`;
}

// Toggle the condition type panels when the select changes
window._fpFunnelToggleCtype = function(sel) {
  const row = sel.closest('.fp-funnel-step-row');
  if (!row) return;
  const idx = row.dataset.stepIdx;
  ['event','pagePath','pageLocation'].forEach(t => {
    const panel = row.querySelector(`[data-ctype-panel="${t}-${idx}"]`);
    if (panel) panel.style.display = sel.value === t ? 'flex' : 'none';
  });
};

// Add a step row to the form
window._fpFunnelAddStep = function() {
  const container = document.getElementById('fp-funnel-steps-container');
  if (!container) return;
  const idx = container.querySelectorAll('.fp-funnel-step-row').length;
  if (idx >= 10) { showToast?.('warning','Maximum 10 étapes'); return; }
  container.insertAdjacentHTML('beforeend', _fpFunnelStepRow(idx, null));
};

// Remove a step row
window._fpFunnelRemoveStep = function(btn) {
  const row = btn.closest('.fp-funnel-step-row');
  const container = document.getElementById('fp-funnel-steps-container');
  if (!row || !container) return;
  const rows = container.querySelectorAll('.fp-funnel-step-row');
  if (rows.length <= 2) { showToast?.('warning','Minimum 2 étapes'); return; }
  row.remove();
  // Renumber
  container.querySelectorAll('.fp-funnel-step-row').forEach((r, i) => {
    r.dataset.stepIdx = i;
    const numSpan = r.querySelector('span[style*="width:22px"]');
    if (numSpan) numSpan.textContent = i + 1;
  });
};

// Build the create/edit form HTML
function _fpFunnelBuildForm(funnel) {
  const isEdit = !!funnel;
  const bd = funnel?.breakdown_dimension || '';
  const bdOpts = ['','deviceCategory','country','browser','operatingSystem','sessionDefaultChannelGrouping','sourceMedium','city','region'];
  const lookback = funnel?.lookback_days || 30;
  const lbOpts = [7,14,30,60,90,180];
  const steps = (funnel?.steps || [{position:1,name:'',event_name:'',page_path_match_type:'EXACT',page_path_value:''},{position:2,name:'',event_name:'',page_path_match_type:'EXACT',page_path_value:''}]);
  return `
    <div class="fp-card" style="padding:20px 22px">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:18px">
        <div style="font-size:15px;font-weight:700;color:var(--fp-text)">${isEdit ? '✏️ Modifier le funnel' : '➕ Nouveau funnel'}</div>
        <button class="fp-btn fp-btn-ghost fp-btn-sm" onclick="window._fpFunnelCancel()">✕ Annuler</button>
      </div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:14px">
        <div>
          <label style="font-size:11px;font-weight:600;color:var(--fp-text-muted);display:block;margin-bottom:5px">Nom *</label>
          <input id="fp-f-name" class="fp-input" placeholder="Mon funnel de conversion" value="${_fpFunnelEsc(funnel?.name||'')}">
        </div>
        <div>
          <label style="font-size:11px;font-weight:600;color:var(--fp-text-muted);display:block;margin-bottom:5px">Site URL *</label>
          <input id="fp-f-siteurl" class="fp-input" placeholder="https://example.com" value="${_fpFunnelEsc(funnel?.site_url||window.STATE?.siteUrl||'')}">
        </div>
      </div>
      <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:14px;margin-bottom:18px">
        <div>
          <label style="font-size:11px;font-weight:600;color:var(--fp-text-muted);display:block;margin-bottom:5px">Période</label>
          <select id="fp-f-lookback" class="fp-input" style="font-size:12px">
            ${lbOpts.map(d=>`<option value="${d}" ${d==lookback?'selected':''}>${d} jours</option>`).join('')}
          </select>
        </div>
        <div>
          <label style="font-size:11px;font-weight:600;color:var(--fp-text-muted);display:block;margin-bottom:5px">Breakdown</label>
          <select id="fp-f-breakdown" class="fp-input" style="font-size:12px">
            ${bdOpts.map(d=>`<option value="${d}" ${d===bd?'selected':''}>${d||'Aucun'}</option>`).join('')}
          </select>
        </div>
        <div>
          <label style="font-size:11px;font-weight:600;color:var(--fp-text-muted);display:block;margin-bottom:5px">Type de funnel</label>
          <select id="fp-f-opentype" class="fp-input" style="font-size:12px">
            <option value="closed" ${!funnel?.is_open_funnel?'selected':''}>Fermé (Closed)</option>
            <option value="open" ${funnel?.is_open_funnel?'selected':''}>Ouvert (Open)</option>
          </select>
        </div>
      </div>
      <div style="margin-bottom:8px">
        <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:8px">
          <label style="font-size:11px;font-weight:600;color:var(--fp-text-muted)">Étapes (2–10) *</label>
          <button class="fp-btn fp-btn-ghost fp-btn-sm" onclick="window._fpFunnelAddStep()">+ Ajouter</button>
        </div>
        <div id="fp-funnel-steps-container">
          ${steps.map((s,i) => _fpFunnelStepRow(i, s)).join('')}
        </div>
      </div>
      <div style="display:flex;justify-content:flex-end;gap:10px;margin-top:16px">
        <button class="fp-btn fp-btn-ghost" onclick="window._fpFunnelCancel()">Annuler</button>
        <button id="fp-f-save-btn" class="fp-btn fp-btn-primary" onclick="window._fpFunnelSave()">
          ${isEdit ? '💾 Enregistrer' : '✅ Créer le funnel'}
        </button>
      </div>
    </div>`;
}

// Show create or edit form
window._fpFunnelShowForm = function(funnel) {
  const listSec = document.getElementById('fp-funnels-list-section');
  const formSec = document.getElementById('fp-funnel-form-section');
  const resSec  = document.getElementById('fp-funnel-result-section');
  if (!formSec) return;
  window._fpFunnelState.editing = funnel || null;
  if (listSec) listSec.style.display = 'none';
  if (resSec)  resSec.style.display  = 'none';
  formSec.style.display = 'block';
  formSec.innerHTML = _fpFunnelBuildForm(funnel);
};

// Cancel form — go back to list
window._fpFunnelCancel = function() {
  const listSec = document.getElementById('fp-funnels-list-section');
  const formSec = document.getElementById('fp-funnel-form-section');
  const resSec  = document.getElementById('fp-funnel-result-section');
  window._fpFunnelState.editing = null;
  if (formSec) formSec.style.display = 'none';
  if (resSec)  resSec.style.display  = 'none';
  if (listSec) listSec.style.display = 'block';
};

// Read step data from DOM
function _fpFunnelReadSteps() {
  const rows = document.querySelectorAll('#fp-funnel-steps-container .fp-funnel-step-row');
  const steps = [];
  rows.forEach((row, i) => {
    const get = field => (row.querySelector(`[data-field="${field}-${i}"]`) || {}).value || '';
    const ctype = get('step-ctype') || 'pagePath';
    steps.push({
      position: i + 1,
      name:     get('step-name').trim(),
      eventName:             ctype === 'event'        ? get('step-eventname').trim() : null,
      pagePathMatchType:     ctype === 'pagePath'     ? get('step-ppmt')             : null,
      pagePathValue:         ctype === 'pagePath'     ? get('step-ppv').trim()       : null,
      pageLocationMatchType: ctype === 'pageLocation' ? get('step-plmt')             : null,
      pageLocationValue:     ctype === 'pageLocation' ? get('step-plv').trim()       : null,
    });
  });
  return steps;
}

// Save funnel (create or update)
window._fpFunnelSave = async function() {
  const saveBtn = document.getElementById('fp-f-save-btn');
  if (saveBtn) { saveBtn.disabled = true; saveBtn.textContent = '⏳ Sauvegarde…'; }

  const name      = (document.getElementById('fp-f-name')?.value || '').trim();
  const siteUrl   = (document.getElementById('fp-f-siteurl')?.value || '').trim();
  const lookback  = parseInt(document.getElementById('fp-f-lookback')?.value || '30', 10);
  const breakdown = document.getElementById('fp-f-breakdown')?.value || null;
  const openType  = document.getElementById('fp-f-opentype')?.value || 'closed';
  const steps     = _fpFunnelReadSteps();

  if (!name) { showToast?.('error','Le nom est requis'); if(saveBtn){saveBtn.disabled=false;saveBtn.textContent='✅ Créer';} return; }
  if (!siteUrl) { showToast?.('error','Le site URL est requis'); if(saveBtn){saveBtn.disabled=false;saveBtn.textContent='✅ Créer';} return; }
  if (steps.length < 2) { showToast?.('error','Minimum 2 étapes'); if(saveBtn){saveBtn.disabled=false;saveBtn.textContent='✅ Créer';} return; }

  const payload = {
    name,
    siteUrl,
    lookbackDays: lookback,
    breakdownDimension: breakdown || null,
    isOpenFunnel: openType === 'open',
    steps,
  };

  try {
    const editing = window._fpFunnelState.editing;
    let res;
    if (editing) {
      res = await apiFetch(`/api/funnels/${editing.id}`, { method: 'PATCH', body: JSON.stringify(payload) });
    } else {
      res = await apiFetch('/api/funnels', { method: 'POST', body: JSON.stringify(payload) });
    }
    if (!res?.ok) throw new Error(res?.error || 'Erreur serveur');
    showToast?.('success', editing ? 'Funnel mis à jour' : 'Funnel créé');
    window._fpFunnelState.editing = null;
    window._fpFunnelCancel();
    window._fpFunnelLoad();
  } catch (e) {
    showToast?.('error', String(e.message || e));
    if (saveBtn) { saveBtn.disabled = false; saveBtn.textContent = '✅ Créer'; }
  }
};

// Edit — fetch funnel detail then show form
window._fpFunnelEdit = async function(btn) {
  const id = btn.dataset.fid;
  if (!id) return;
  try {
    const res = await apiFetch(`/api/funnels/${id}`);
    if (!res?.ok) throw new Error(res?.error || 'Funnel introuvable');
    window._fpFunnelShowForm(res.funnel);
  } catch (e) {
    showToast?.('error', String(e.message || e));
  }
};

// Delete with confirmation
window._fpFunnelDelete = async function(btn) {
  const id    = btn.dataset.fid;
  const fname = btn.dataset.fname || 'ce funnel';
  if (!id) return;
  if (!confirm(`Supprimer "${fname}" ? Cette action est irréversible.`)) return;
  try {
    const res = await apiFetch(`/api/funnels/${id}`, { method: 'DELETE' });
    if (!res?.ok) throw new Error(res?.error || 'Erreur lors de la suppression');
    showToast?.('success', 'Funnel supprimé');
    window._fpFunnelLoad();
  } catch (e) {
    showToast?.('error', String(e.message || e));
  }
};

// Render run result
function _fpFunnelRenderResult(result, funnelName) {
  const resSec = document.getElementById('fp-funnel-result-section');
  if (!resSec) return;
  const pct = n => n === null ? '—' : `${Math.round((n||0)*100)}%`;
  const num = n => n === null ? '—' : Number(n).toLocaleString('fr-FR');
  resSec.style.display = 'block';
  resSec.innerHTML = `
    <div class="fp-card" style="padding:18px 20px;margin-top:16px">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:14px;flex-wrap:wrap;gap:8px">
        <div>
          <div style="font-size:14px;font-weight:700;color:var(--fp-text)">${_fpFunnelEsc(funnelName)}</div>
          <div style="font-size:11px;color:var(--fp-text-muted);margin-top:2px">
            <span style="background:rgba(37,99,235,0.1);color:#2563EB;border-radius:4px;padding:1px 7px;font-size:10px;font-weight:600">Google Analytics 4</span>
            &nbsp;${result.dateRange?.startDate} → ${result.dateRange?.endDate}
            &nbsp;·&nbsp;${result.isOpenFunnel ? 'Ouvert' : 'Fermé'}
          </div>
        </div>
        <div style="text-align:right;font-size:11px;color:var(--fp-text-muted)">
          ${result.cached ? `<span style="background:rgba(5,150,105,0.1);color:#059669;border-radius:4px;padding:2px 7px;font-weight:600">✓ Cached</span><br>cachedAt ${_fpFunnelFmtDate(result.cachedAt)}<br>` : ''}
          fetchedAt ${_fpFunnelFmtDate(result.fetchedAt)}
        </div>
      </div>
      <div style="margin-bottom:12px">
        <div style="font-size:13px;font-weight:700;color:var(--fp-text);margin-bottom:8px">Taux global : <span style="color:#2563EB">${pct(result.overallConversionRate)}</span></div>
        <div style="overflow-x:auto">
          <table style="width:100%;border-collapse:collapse;font-size:12px">
            <thead>
              <tr style="border-bottom:2px solid var(--fp-border)">
                <th style="text-align:left;padding:6px 10px;color:var(--fp-text-muted);font-weight:600">Étape</th>
                <th style="text-align:right;padding:6px 10px;color:var(--fp-text-muted);font-weight:600">Utilisateurs</th>
                <th style="text-align:right;padding:6px 10px;color:var(--fp-text-muted);font-weight:600">Complétion</th>
                <th style="text-align:right;padding:6px 10px;color:var(--fp-text-muted);font-weight:600">Abandon</th>
                <th style="text-align:right;padding:6px 10px;color:var(--fp-text-muted);font-weight:600">Perdus</th>
              </tr>
            </thead>
            <tbody>
              ${(result.steps||[]).map((s, i) => {
                const barPct = result.steps[0]?.activeUsers > 0 ? Math.round(s.activeUsers/result.steps[0].activeUsers*100) : 0;
                return `<tr style="border-bottom:1px solid var(--fp-border)">
                  <td style="padding:7px 10px">
                    <span style="font-weight:600;color:var(--fp-text)">${i+1}. ${_fpFunnelEsc(s.name)}</span>
                    <div style="height:4px;background:var(--fp-border);border-radius:2px;margin-top:3px;max-width:120px"><div style="height:4px;background:#2563EB;border-radius:2px;width:${barPct}%"></div></div>
                  </td>
                  <td style="text-align:right;padding:7px 10px;font-weight:700;color:var(--fp-text)">${num(s.activeUsers)}</td>
                  <td style="text-align:right;padding:7px 10px;color:${s.completionRate===null?'var(--fp-text-muted)':s.completionRate>=0.7?'#059669':s.completionRate>=0.4?'#d97706':'#ef4444'};font-weight:600">${pct(s.completionRate)}</td>
                  <td style="text-align:right;padding:7px 10px;color:${s.abandonmentRate===null?'var(--fp-text-muted)':'#ef4444'}">${pct(s.abandonmentRate)}</td>
                  <td style="text-align:right;padding:7px 10px;color:var(--fp-text-muted)">${num(s.abandonments)}</td>
                </tr>`;
              }).join('')}
            </tbody>
          </table>
        </div>
      </div>
      <div style="display:flex;justify-content:flex-end">
        <button class="fp-btn fp-btn-ghost fp-btn-sm" onclick="document.getElementById('fp-funnel-result-section').style.display='none'">✕ Fermer</button>
      </div>
    </div>`;
}

// Run a funnel
window._fpFunnelRun = async function(btn) {
  const id = btn.dataset.fid;
  if (!id) return;
  const origText = btn.textContent;
  btn.disabled = true;
  btn.textContent = '⏳…';
  // Find funnel name
  const funnel = (window._fpFunnelState.funnels || []).find(f => f.id === id);
  try {
    const res = await apiFetch(`/api/funnels/${id}/run`, { method: 'POST', body: JSON.stringify({}) });
    if (!res?.ok) throw new Error(res?.error || 'Erreur d\'exécution');
    _fpFunnelRenderResult(res.result, funnel?.name || 'Résultat');
    showToast?.('success', 'Rapport GA4 chargé');
  } catch (e) {
    const resSec = document.getElementById('fp-funnel-result-section');
    if (resSec) {
      resSec.style.display = 'block';
      resSec.innerHTML = `<div class="fp-card" style="padding:16px;color:#ef4444;font-size:13px">❌ Erreur : ${_fpFunnelEsc(String(e.message||e))}</div>`;
    }
    showToast?.('error', String(e.message || e));
  } finally {
    btn.disabled = false;
    btn.textContent = origText;
  }
};

// Load funnel list from API
window._fpFunnelLoad = async function() {
  if (window._fpFunnelState.loading) return;
  window._fpFunnelState.loading = true;
  const listSec = document.getElementById('fp-funnels-list-section');
  if (listSec) listSec.innerHTML = `<div style="text-align:center;padding:32px;color:var(--fp-text-muted);font-size:13px">⏳ Chargement des funnels…</div>`;
  try {
    const res = await apiFetch('/api/funnels');
    if (!res?.ok) throw new Error(res?.error || 'Erreur de chargement');
    window._fpFunnelState.funnels = res.funnels || [];
    _fpFunnelRenderList(window._fpFunnelState.funnels);
  } catch (e) {
    if (listSec) listSec.innerHTML = `<div style="text-align:center;padding:32px;color:#ef4444;font-size:13px">❌ ${_fpFunnelEsc(String(e.message||e))}</div>`;
  } finally {
    window._fpFunnelState.loading = false;
  }
};

function renderGA4Funnels() {
  if (!_ga4Connected()) {
    return `
      <div class="fp-section-header">
        <div><h1>🔵 Funnels de conversion</h1><div class="fp-section-sub">Configurez et analysez vos funnels GA4</div></div>
      </div>
      ${_ga4NotConnectedBanner()}`;
  }

  // Schedule data load after DOM injection
  setTimeout(() => window._fpFunnelLoad?.(), 60);

  return `
    <div class="fp-section-header">
      <div><h1>🔵 Funnels de conversion</h1><div class="fp-section-sub">Configurez vos funnels GA4 — source : Google Analytics 4</div></div>
      <div class="fp-section-actions">
        <button class="fp-btn fp-btn-ghost fp-btn-sm" onclick="window._fpFunnelLoad()">🔄 Actualiser</button>
        <button class="fp-btn fp-btn-primary fp-btn-sm" onclick="window._fpFunnelShowForm()">+ Nouveau funnel</button>
      </div>
    </div>

    <div id="fp-funnels-root">
      <div id="fp-funnels-list-section">
        <div style="text-align:center;padding:32px;color:var(--fp-text-muted);font-size:13px">⏳ Chargement…</div>
      </div>
      <div id="fp-funnel-form-section" style="display:none"></div>
      <div id="fp-funnel-result-section" style="display:none"></div>
    </div>`;
}

// ══════════════════════════════════════════════════════════════════════
// GA4 AUDIENCE
// ══════════════════════════════════════════════════════════════════════
function renderGA4Audience() {
  const _audS = window._fpAudienceState || {};
  if (!_audS.loaded && !_audS.loading) setTimeout(() => window._fpAudienceAPI?.loadAll(), 60);
  if (_audS.loading && !_audS.data && !(window.FP_DATA?.ga4?.audience)) return _fpAudLoadingSkeleton();
  if (_audS.error  && !_audS.data && !(window.FP_DATA?.ga4?.audience)) return _fpAudErrorSkeleton(_audS.error);
  const ga4 = _audS.data || window.FP_DATA?.ga4 || {};
  const devRows = ga4.audience?.devices?.rows || [];
  const geoRows = ga4.audience?.geo?.rows || [];
  const nvr     = ga4.audience?.newVsReturn?.rows || [];

  const devMap = {}; const osMap = {}; const brMap = {};
  devRows.forEach(r => {
    const dev = r.dimensionValues?.[0]?.value||'desktop';
    const os  = r.dimensionValues?.[1]?.value||'unknown';
    const br  = r.dimensionValues?.[2]?.value||'unknown';
    const s   = parseFloat(r.metricValues?.[0]?.value||0);
    devMap[dev] = (devMap[dev]||0)+s; osMap[os]=(osMap[os]||0)+s; brMap[br]=(brMap[br]||0)+s;
  });

  const totalSess = Object.values(devMap).reduce((a,b) => a+(b), 0) || 0;
  const devDisplay = Object.keys(devMap).length ? devMap : {};
  const devIcons = {'mobile':'📱','desktop':'🖥️','tablet':'📱','smart tv':'📺'};
  const devColors = {'mobile':'#8b5cf6','desktop':'#2563EB','tablet':'#f59e0b','smart tv':'#06b6d4'};

  const fmtNum = n => n>=1000000?(n/1000000).toFixed(1)+'M':n>=1000?(n/1000).toFixed(1)+'k':Math.round(n).toLocaleString('fr-FR');

  return `
    <div class="fp-section-header">
      <div><h1>👥 Audience</h1><div class="fp-section-sub">Profil des visiteurs — appareils, géographie, démographie — source : Google Analytics 4</div></div>
      <div class="fp-section-actions">
        <select onchange="window._fpAudienceAPI?.loadAll(parseInt(this.value))"
          style="background:var(--fp-track);border:1px solid var(--fp-border);border-radius:6px;color:var(--fp-text);font-size:12px;padding:5px 8px">
          <option value="7">7 jours</option><option value="30" selected>30 jours</option><option value="90">90 jours</option>
        </select>
        <button class="fp-btn fp-btn-ghost fp-btn-sm" onclick="window._fpAudienceAPI?.loadAll()">🔄 Actualiser</button>
      </div>
    </div>

    ${_ga4NotConnectedBanner()}

    ${aiBlock(
      _ga4Connected()
        ? Object.keys(devMap).length > 0
          ? (() => {
              const _topDev = Object.entries(devMap).sort((a,b)=>b[1]-a[1])[0];
              const _topPct = _topDev ? Math.round(_topDev[1]/totalSess*100) : 0;
              const _topGeo = Object.entries(Object.fromEntries(geoRows.slice(0,1).map(r=>[r.dimensionValues?.[0]?.value||'—', parseInt(r.metricValues?.[0]?.value||0)]))).map(([k,v])=>k)[0];
              return `Appareil principal : <strong>${_topDev?.[0]||'mobile'} (${_topPct}%)</strong>. ${_topGeo?'Zone principale : <strong>'+_topGeo+'</strong>. ':''} Optimisez l\'expérience sur l\'appareil dominant pour maximiser vos conversions.`;
            })()
          : "Actualisez vos données GA4 pour voir le profil d\'audience."
        : "Connectez GA4 pour analyser le profil de vos visiteurs : appareils, géographie, démographie.",
      _ga4Connected() ? ['Voir le trafic', 'Analyser les conversions', 'Rapport audience'] : ['Connecter GA4']
    )}

    <!-- DEVICE SPLIT -->
    <div class="fp-grid-2 fp-mb-20">
      <div class="fp-card">
        <div class="fp-card-title" style="margin-bottom:14px">📱 Répartition des appareils</div>
        ${!Object.keys(devDisplay).length ? `<div style="padding:24px;text-align:center;font-size:12px;color:var(--fp-text-muted)">${_ga4Connected() ? '⏳ Actualisez GA4 pour voir la répartition des appareils.' : '🔌 Connectez GA4 pour voir vos appareils.'}</div>` : `
        <div style="display:flex;height:16px;border-radius:8px;overflow:hidden;margin-bottom:16px">
          ${Object.entries(devDisplay).map(([dev, s]) => {
            const pct = Math.round((s)/Math.max(totalSess,1)*100);
            const color = devColors[dev.toLowerCase()]||'#475569';
            return `<div style="width:${pct}%;background:${color}" title="${dev}: ${pct}%"></div>`;
          }).join('')}
        </div>`}
        ${Object.entries(devDisplay).sort((a,b)=>(b[1])-(a[1])).map(([dev, s]) => {
          const pct = Math.round((s)/totalSess*100);
          const color = devColors[dev.toLowerCase()]||'#475569';
          const icon = devIcons[dev.toLowerCase()]||'💻';
          return `<div style="display:flex;align-items:center;gap:10px;margin-bottom:10px">
            <span style="font-size:16px">${icon}</span>
            <div style="flex:1">
              <div style="display:flex;justify-content:space-between;margin-bottom:3px">
                <span style="font-size:12px;font-weight:600;color:var(--fp-text);text-transform:capitalize">${dev}</span>
                <span style="font-size:12px;font-weight:700;color:${color}">${pct}%</span>
              </div>
              <div class="fp-progress-track" style="height:6px"><div class="fp-progress-fill" style="width:${pct}%;background:${color}"></div></div>
            </div>
            <span style="font-size:11px;color:var(--fp-text-muted);width:50px;text-align:right">${fmtNum(s)}</span>
          </div>`;
        }).join('')}
      </div>

      <div class="fp-card">
        <div class="fp-card-title" style="margin-bottom:14px">🌐 Navigateurs & OS</div>
        <div style="margin-bottom:14px">
          <div style="font-size:11px;color:var(--fp-text-muted);font-weight:600;margin-bottom:8px;text-transform:uppercase;letter-spacing:0.5px">Navigateurs</div>
          ${Object.entries(brMap).sort((a,b)=>(b[1])-(a[1])).slice(0,5).map(([br,s]) => {
            const pct = Math.round((s)/totalSess*100);
            const brColors = {Chrome:'#22c55e',Safari:'#2563EB',Firefox:'#f97316','Edge':'#06b6d4','Samsung Internet':'#f59e0b'};
            const c = brColors[br]||'#64748b';
            return `<div style="display:flex;align-items:center;gap:8px;margin-bottom:5px">
              <div style="font-size:11px;color:var(--fp-text);width:80px;flex-shrink:0">${escHtml(br)}</div>
              <div class="fp-progress-track" style="flex:1;height:5px"><div class="fp-progress-fill" style="width:${pct}%;background:${c}"></div></div>
              <span style="font-size:11px;font-weight:700;color:${c};width:32px;text-align:right">${pct}%</span>
            </div>`;
          }).join('')||`<div style="font-size:11px;color:var(--fp-text-muted)">${_ga4Connected()?'Chargement…':'Connectez GA4'}</div>`}
        </div>
        <div>
          <div style="font-size:11px;color:var(--fp-text-muted);font-weight:600;margin-bottom:8px;text-transform:uppercase;letter-spacing:0.5px">Systèmes</div>
          ${Object.entries(osMap).sort((a,b)=>(b[1])-(a[1])).slice(0,5).map(([os,s]) => {
            const pct = Math.round((s)/totalSess*100);
            return `<div style="display:flex;align-items:center;gap:8px;margin-bottom:5px">
              <div style="font-size:11px;color:var(--fp-text);width:80px;flex-shrink:0">${escHtml(os)}</div>
              <div class="fp-progress-track" style="flex:1;height:5px"><div class="fp-progress-fill" style="width:${pct}%;background:#8b5cf6"></div></div>
              <span style="font-size:11px;font-weight:700;color:var(--fp-text);width:32px;text-align:right">${pct}%</span>
            </div>`;
          }).join('')||`<div style="font-size:11px;color:var(--fp-text-muted)">${_ga4Connected()?'Chargement…':'Connectez GA4'}</div>`}
        </div>
      </div>
    </div>

    <!-- GEO TABLE -->
    <div class="fp-card fp-mb-20">
      <div class="fp-card-title" style="margin-bottom:14px">🌍 Géographie — Top pays & villes</div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:20px">
        <div>
          <div style="font-size:11px;font-weight:600;color:var(--fp-text-muted);margin-bottom:8px">PAYS</div>
          ${(() => {
            const countryMap = {};
            geoRows.forEach(r => {
              const country = r.dimensionValues?.[0]?.value||'Unknown';
              const s = parseFloat(r.metricValues?.[0]?.value||0);
              countryMap[country] = (countryMap[country]||0)+s;
            });
            const countries = Object.entries(countryMap).sort((a,b)=>(b[1])-(a[1])).slice(0,8);
            if (!countries.length) return `<div style="padding:16px;text-align:center;font-size:12px;color:var(--fp-text-muted)">${_ga4Connected() ? '⏳ Actualisez GA4 pour voir vos pays.' : '🔌 Connectez GA4 pour voir vos pays.'}</div>`;
            const maxS = countries[0]?.[1] || 1;
            return countries.map(([c,s]) => `<div style="display:grid;grid-template-columns:22px 1fr 60px 40px;gap:0 8px;align-items:center;margin-bottom:8px">
              <span style="font-size:14px;line-height:1">${fpFlag(c)}</span>
              <div style="font-size:11px;color:var(--fp-text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${escHtml(c)}</div>
              <div class="fp-progress-track" style="height:4px"><div class="fp-progress-fill" style="width:${Math.round((s)/maxS*100)}%"></div></div>
              <span style="font-size:11px;font-weight:700;color:var(--fp-text);text-align:right">${fmtNum(s)}</span>
            </div>`).join('');
          })()}
        </div>
        <div>
          <div style="font-size:11px;font-weight:600;color:var(--fp-text-muted);margin-bottom:8px">VILLES</div>
          ${(() => {
            const cityMap = {};
            geoRows.forEach(r => {
              const city = r.dimensionValues?.[1]?.value||'Unknown';
              if (city && city !== '(not set)') {
                const s = parseFloat(r.metricValues?.[0]?.value||0);
                cityMap[city] = (cityMap[city]||0)+s;
              }
            });
            const cities = Object.entries(cityMap).sort((a,b)=>(b[1])-(a[1])).slice(0,8);
            const maxS = cities[0]?.[1] || 1;
            const display = cities.length ? cities : [];
            if(!display.length)return '<div style="padding:16px;text-align:center;font-size:12px;color:var(--fp-text-muted)">🔌 Connectez Google Analytics 4 pour voir vos villes</div>';
            return display.map(([c,s]) => `<div style="display:grid;grid-template-columns:1fr 60px 40px;gap:0 8px;align-items:center;margin-bottom:8px">
              <div style="font-size:11px;color:var(--fp-text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${escHtml(c)}</div>
              <div class="fp-progress-track" style="height:4px"><div class="fp-progress-fill" style="width:${Math.round((s)/maxS*100)}%;background:#8b5cf6"></div></div>
              <span style="font-size:11px;font-weight:700;color:var(--fp-text);text-align:right">${fmtNum(s)}</span>
            </div>`).join('');
          })()}
        </div>
      </div>
    </div>

    <!-- INSIGHTS AUDIENCE IA -->
    <div class="fp-card">
      <div class="fp-card-title" style="margin-bottom:14px">🧠 Insights audience IA</div>
      ${(() => {
        if (!_ga4Connected()) return `<div style="padding:16px;text-align:center"><div style="font-size:13px;color:var(--fp-text-muted);margin-bottom:10px">🔌 Connectez GA4 pour des insights sur votre audience.</div><button class="fp-btn fp-btn-primary fp-btn-sm" onclick="window.FP_GA4_API&&window.FP_GA4_API.connectGoogle()">Connecter GA4</button></div>`;
        const _aIns = [];
        const _devEntries = Object.entries(devMap).sort((a,b)=>b[1]-a[1]);
        if (_devEntries.length && totalSess > 0) { const [_topDev, _topN]=_devEntries[0]; const _pct=Math.round(_topN/totalSess*100); _aIns.push({icon:_topDev==='mobile'?'📱':'🖥️',color:'#8b5cf6',title:`${_topDev.charAt(0).toUpperCase()+_topDev.slice(1)} dominant (${_pct}%)`,desc:`Priorisez l'UX ${_topDev} dans vos optimisations de conversion.`}); }
        const _geoEntries = Object.entries((() => { const cm={}; geoRows.forEach(r=>{const c=r.dimensionValues?.[0]?.value||'Unknown';const s=parseFloat(r.metricValues?.[0]?.value||0);cm[c]=(cm[c]||0)+s;}); return cm; })()).sort((a,b)=>b[1]-a[1]);
        if (_geoEntries.length && totalSess > 0) { const _topGeo=_geoEntries[0]; const _gpct=Math.round(_topGeo[1]/totalSess*100); _aIns.push({icon:'🌍',color:'#2563EB',title:`Principal marché : ${_topGeo[0]} (${_gpct}%)`,desc:'Adaptez vos contenus et horaires de publication à ce marché.'}); }
        if (!_aIns.length) return `<div style="padding:16px;text-align:center;font-size:12px;color:var(--fp-text-muted)">Actualisez vos données GA4 pour générer des insights audience.<br><button class="fp-btn fp-btn-ghost fp-btn-sm" style="margin-top:8px" onclick="window.FP_GA4_API&&window.FP_GA4_API.reload()">🔄 Actualiser</button></div>`;
        return _aIns.map(x=>`<div style="display:flex;align-items:flex-start;gap:10px;padding:8px 10px;border-radius:8px;background:${x.color}08;border-left:3px solid ${x.color};margin-bottom:6px"><span style="font-size:16px;flex-shrink:0">${x.icon}</span><div><div style="font-size:12px;font-weight:700;color:var(--fp-text);margin-bottom:2px">${x.title}</div><div style="font-size:11px;color:var(--fp-text-muted)">${x.desc}</div></div></div>`).join('');
      })()}
    </div>
  `;
}

// ══════════════════════════════════════════════════════════════════════
// GA4 CAMPAIGNS
// ══════════════════════════════════════════════════════════════════════
function renderGA4Campaigns() {
  const _campS = window._fpCampaignsState || {};
  if (!_campS.loaded && !_campS.loading) setTimeout(() => window._fpCampaignsAPI.loadAll(), 60);
  if (_campS.loading && !(_campS.data?.campaigns) && !(window.FP_DATA?.ga4?.campaigns)) return _fpCampLoadingSkeleton();
  if (_campS.error  && !(_campS.data?.campaigns) && !(window.FP_DATA?.ga4?.campaigns)) return _fpCampErrorSkeleton(_campS.error);
  const ga4  = _campS.data || window.FP_DATA?.ga4 || {};
  const rows = ga4.campaigns?.rows || [];
  const fmtNum = n => n>=1000?(n/1000).toFixed(1)+'k':Math.round(n).toLocaleString('fr-FR');
  const fmtDur = s => `${Math.floor(s/60)}m${Math.round(s%60).toString().padStart(2,'0')}s`;

  const prevRows = ga4.campaigns?.totals || [];

  return `
    <div class="fp-section-header">
      <div><h1>📡 Campagnes & Attribution</h1><div class="fp-section-sub">Performance des campagnes marketing et attribution des conversions</div></div>
      <div class="fp-section-actions">
        <select onchange="window._fpCampaignsAPI.loadAll(parseInt(this.value))"
          style="background:var(--fp-track);border:1px solid var(--fp-border);border-radius:6px;color:var(--fp-text);font-size:12px;padding:5px 8px">
          <option value="7">7 jours</option><option value="30" selected>30 jours</option><option value="90">90 jours</option>
        </select>
        <button class="fp-btn fp-btn-ghost fp-btn-sm" onclick="window._fpCampaignsAPI.loadAll()">🔄 Actualiser</button>
        <button class="fp-btn fp-btn-primary fp-btn-sm" onclick="window._fpExportCampaigns()">📥 CSV</button>
      </div>
    </div>

    ${_ga4NotConnectedBanner()}

    ${aiBlock(
      _ga4Connected()
        ? rows.length > 0
          ? (() => {
              const _totSess = rows.reduce((s,r)=>s+parseFloat(r.metricValues?.[0]?.value||0),0);
              const _totConv = rows.reduce((s,r)=>s+parseFloat(r.metricValues?.[2]?.value||0),0);
              const _cr      = _totSess > 0 ? (_totConv/_totSess*100).toFixed(2) : 0;
              const _topCamp = rows[0]?.dimensionValues?.[0]?.value || '—';
              return `<strong>${rows.length} campagne${rows.length>1?'s':''}</strong> analysées. Taux de conversion moyen : <strong>${_cr}%</strong>. Campagne principale : <strong>${_topCamp}</strong>. Optimisez les campagnes à faible taux de conversion.`;
            })()
          : "Actualisez vos données GA4 pour voir la performance de vos campagnes."
        : "Connectez GA4 pour analyser vos campagnes marketing et leur attribution.",
      _ga4Connected() ? ['Voir l\'audience', 'Analyser le trafic', 'Rapport campagnes'] : ['Connecter GA4']
    )}

    <!-- CAMPAIGN TABLE -->
    <div class="fp-card fp-mb-20">
      <div class="fp-card-title" style="margin-bottom:14px">📋 Performance par campagne</div>
      <div style="overflow-x:auto;-webkit-overflow-scrolling:touch">
      <table style="width:100%;min-width:640px;border-collapse:collapse;font-size:12px">
        <thead><tr style="border-bottom:1px solid var(--fp-border)">
          ${['Campagne','Canal','Source/Medium','Sessions','Utilisateurs','Conversions','Taux conv.','Durée moy.','Rebond'].map(h=>`<th style="padding:6px 8px;text-align:left;font-size:10px;color:var(--fp-text-faint);font-weight:600;white-space:nowrap">${h}</th>`).join('')}
        </tr></thead>
        <tbody>
          ${rows.slice(0,30).map(r => {
            const camp = r.dimensionValues?.[0]?.value||'(non définie)';
            const ch   = r.dimensionValues?.[1]?.value||'—';
            const sm   = r.dimensionValues?.[2]?.value||'—';
            const s    = parseFloat(r.metricValues?.[0]?.value||0);
            const u    = parseFloat(r.metricValues?.[1]?.value||0);
            const c    = parseFloat(r.metricValues?.[2]?.value||0);
            const b    = parseFloat(r.metricValues?.[3]?.value||0)*100;
            const dur  = parseFloat(r.metricValues?.[4]?.value||0);
            const cr   = parseFloat(r.metricValues?.[5]?.value||0)*100;
            const color = GA4_CHANNEL_COLORS[ch]||'#64748b';
            return `<tr style="border-bottom:1px solid rgba(255,255,255,0.03)">
              <td style="padding:7px 8px;font-weight:600;color:var(--fp-text);max-width:160px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${escHtml(camp)}</td>
              <td style="padding:7px 8px"><span style="font-size:10px;padding:2px 6px;border-radius:5px;background:${color}18;color:${color};font-weight:600">${ch}</span></td>
              <td style="padding:7px 8px;font-size:10px;font-family:var(--fp-font-mono);color:var(--fp-text-muted)">${escHtml(sm)}</td>
              <td style="padding:7px 8px;font-weight:700">${fmtNum(s)}</td>
              <td style="padding:7px 8px">${fmtNum(u)}</td>
              <td style="padding:7px 8px;color:#22c55e;font-weight:800">${fmtNum(c)}</td>
              <td style="padding:7px 8px"><span style="color:${cr>5?'#22c55e':cr>2?'#f59e0b':'#ef4444'};font-weight:700">${cr.toFixed(2)}%</span></td>
              <td style="padding:7px 8px;font-size:11px">${fmtDur(dur)}</td>
              <td style="padding:7px 8px"><span style="color:${b>50?'#ef4444':b>35?'#f59e0b':'#22c55e'}">${b.toFixed(0)}%</span></td>
            </tr>`;
          }).join('')||`<tr><td colspan="9" style="padding:24px;text-align:center;color:var(--fp-text-muted)">${_ga4Connected()?'Chargement des campagnes…<br><button class="fp-btn fp-btn-ghost fp-btn-sm" style="margin-top:8px" onclick="window.FP_GA4_API&&window.FP_GA4_API.reload()">🔄 Charger</button>':'Connectez GA4 pour voir vos campagnes'}</td></tr>`}
        </tbody>
      </table>
      </div>
    </div>

    <!-- UTM + ROI -->
    <div class="fp-grid-2">
      <div class="fp-card">
        <div class="fp-card-title" style="margin-bottom:14px">🏷️ Tracking UTM — Guide</div>
        ${[
          {param:'utm_source', ex:'google, newsletter, linkedin', desc:'Source du trafic'},
          {param:'utm_medium', ex:'cpc, email, social', desc:'Type de canal'},
          {param:'utm_campaign', ex:'promo_ete, lancement_v2', desc:'Nom de la campagne'},
          {param:'utm_content', ex:'banner_blue, cta_top', desc:'Variante créative'},
          {param:'utm_term', ex:'seo tool, analytics', desc:'Mot-clé (SEA)'},
        ].map(u => `<div style="margin-bottom:8px;padding:8px;background:var(--fp-inner-card);border-radius:6px">
          <div style="display:flex;align-items:center;gap:6px;margin-bottom:2px">
            <code style="font-size:11px;color:#2563EB;font-family:var(--fp-font-mono)">${u.param}</code>
            <span style="font-size:10px;color:var(--fp-text-faint)">— ${u.desc}</span>
          </div>
          <div style="font-size:10px;color:var(--fp-text-faint);font-style:italic">ex: ${u.ex}</div>
        </div>`).join('')}
        <button class="fp-btn fp-btn-ghost fp-btn-sm" disabled style="margin-top:4px;width:100%;opacity:0.55;cursor:not-allowed" title="Générateur UTM — bientôt disponible">🔗 Générateur UTM (bientôt)</button>
      </div>

      <div class="fp-card">
        <div class="fp-card-title" style="margin-bottom:14px">💰 ROI estimé par canal</div>
        ${(() => {
          if (!_ga4Connected()) return `<div style="padding:16px;text-align:center;font-size:12px;color:var(--fp-text-muted)">🔌 Connectez GA4 pour voir le ROI réel par canal d'acquisition.</div>`;
          const _cRows = rows.slice(0,8);
          if (!_cRows.length) return `<div style="padding:16px;text-align:center;font-size:12px;color:var(--fp-text-muted)">⏳ Actualisez vos données GA4 pour voir le ROI par canal.</div>`;
          const _chConv = {};
          _cRows.forEach(r => { const ch=r.dimensionValues?.[1]?.value||'(Other)'; const c=parseFloat(r.metricValues?.[2]?.value||0); const s=parseFloat(r.metricValues?.[0]?.value||0); if(!_chConv[ch])_chConv[ch]={conv:0,sess:0}; _chConv[ch].conv+=c; _chConv[ch].sess+=s; });
          return Object.entries(_chConv).sort((a,b)=>b[1].conv-a[1].conv).slice(0,5).map(([ch,d]) => {
            const color=GA4_CHANNEL_COLORS[ch]||'#64748b';
            const cr=d.sess>0?(d.conv/d.sess*100).toFixed(1):'—';
            return `<div style="display:flex;align-items:center;gap:10px;margin-bottom:8px"><div style="width:10px;height:10px;border-radius:2px;background:${color};flex-shrink:0"></div><div style="flex:1"><div style="font-size:11px;font-weight:600;color:var(--fp-text)">${ch}</div><div style="font-size:10px;color:var(--fp-text-faint)">${d.conv.toLocaleString('fr-FR')} conv. · ${d.sess.toLocaleString('fr-FR')} sessions</div></div><div style="text-align:right"><div style="font-size:13px;font-weight:800;color:${parseFloat(cr)>3?'#22c55e':parseFloat(cr)>1?'#f59e0b':'#ef4444'}">${cr}%</div><div style="font-size:10px;color:var(--fp-text-faint)">taux conv.</div></div></div>`;
          }).join('');
        })()}
      </div>
    </div>
  `;
}

// ══════════════════════════════════════════════════════════════════════
// GA4 LIVE
// ══════════════════════════════════════════════════════════════════════
function renderGA4Live() {
  const _liveS = window._fpLiveState || {};
  if (!_liveS.loaded && !_liveS.loading) setTimeout(() => window._fpLiveAPI?.startPolling(), 60);
  if (_liveS.loading && !_liveS.data && !(window.FP_DATA?.ga4?.realtime)) return _fpLiveLoadingSkeleton();
  if (_liveS.error  && !_liveS.data && !(window.FP_DATA?.ga4?.realtime)) return _fpLiveErrorSkeleton(_liveS.error);
  const ga4 = _liveS.data || window.FP_DATA?.ga4 || {};
  const rt  = ga4.realtime || {};
  const active = rt.activeUsers || 0;
  const rows   = rt.rows || [];

  const pageMap = {}; const cityMap = {}; const devMap = {}; const evMap = {};
  rows.forEach(r => {
    const city  = r.dimensionValues?.[1]?.value||'Inconnu';
    const page  = r.dimensionValues?.[2]?.value||'/';
    const dev   = r.dimensionValues?.[3]?.value||'desktop';
    const u     = parseInt(r.metricValues?.[0]?.value||1);
    const views = parseInt(r.metricValues?.[1]?.value||0);
    pageMap[page]=(pageMap[page]||0)+u; cityMap[city]=(cityMap[city]||0)+u;
    devMap[dev]=(devMap[dev]||0)+u; evMap[page]=(evMap[page]||0)+views;
  });

  const topPages = Object.entries(pageMap).sort((a,b)=>(b[1])-(a[1])).slice(0,10);
  const topCities = Object.entries(cityMap).sort((a,b)=>(b[1])-(a[1])).slice(0,8);
  const totalActive = active || Object.values(devMap).reduce((a,b)=>a+(b),0) || 0;

  return `
    <div class="fp-section-header">
      <div>
        <h1 style="display:flex;align-items:center;gap:10px">
          Live Analytics
          <span style="font-size:11px;animation:pulse 2s infinite;background:rgba(239,68,68,0.15);border:1px solid rgba(239,68,68,0.4);color:#ef4444;padding:3px 10px;border-radius:20px;font-weight:700">LIVE</span>
        </h1>
        <div class="fp-section-sub">Données en temps réel — actualisation automatique toutes les 30 secondes</div>
      </div>
      <div class="fp-section-actions">
        <span style="font-size:11px;color:var(--fp-text-faint)" id="fp-live-last-update">Dernière MAJ : maintenant</span>
        <button class="fp-btn fp-btn-primary fp-btn-sm" onclick="window._fpLiveAPI?.refresh()">🔄 Actualiser</button>
      </div>
    </div>

    <!-- AI BLOCK -->
    ${aiBlock(
      _ga4Connected()
        ? totalActive > 0
          ? `<strong>${totalActive} utilisateur(s) actif(s)</strong> en ce moment. ${topPages.length>0?'Page la plus visitée : <strong>'+topPages[0][0]+'</strong> ('+topPages[0][1]+' users). ':''} ${topCities.length>0&&topCities[0][0]!=='Inconnu'?'Localisation principale : <strong>'+topCities[0][0]+'</strong>. ':''} Analysez les pages chaudes pour optimiser le parcours utilisateur en temps réel.`
          : "Aucun visiteur actif en ce moment. Vérifiez votre intégration GA4 ou attendez du trafic entrant."
        : "Connectez GA4 pour voir vos visiteurs en temps réel, leurs pages actives et leur localisation.",
      _ga4Connected() ? ['Voir l\'audience', 'Analyser le trafic'] : ['Connecter GA4']
    )}

    <!-- BIG COUNTER -->
    <div class="fp-card fp-mb-20" style="text-align:center;padding:40px;background:radial-gradient(ellipse at center, rgba(239,68,68,0.06) 0%, transparent 70%)">
      <div style="font-size:10px;letter-spacing:2px;text-transform:uppercase;color:var(--fp-text-faint);margin-bottom:8px">Utilisateurs actifs en ce moment</div>
      <div style="font-size:96px;font-weight:900;color:#ef4444;font-family:var(--fp-font-head);line-height:1;margin-bottom:8px" id="fp-live-count">${totalActive}</div>
      <div style="display:flex;justify-content:center;gap:24px;font-size:12px;color:var(--fp-text-muted)">
        ${totalActive > 0 ? `
        <span>📱 Mobile : ${Math.round((devMap['mobile']||0)/totalActive*100)}%</span>
        <span>🖥️ Desktop : ${Math.round((devMap['desktop']||0)/totalActive*100)}%</span>
        <span>📱 Tablet : ${Math.round((devMap['tablet']||0)/totalActive*100)}%</span>
        ` : `<span style="color:var(--fp-text-faint)">${_ga4Connected()?'Aucun visiteur actif en ce moment':'Connectez GA4 pour les données live'}</span>`}
      </div>
    </div>

    <!-- LIVE GRID -->
    <div class="fp-grid-2 fp-mb-20">
      <!-- Active pages -->
      <div class="fp-card">
        <div class="fp-card-title" style="margin-bottom:14px">📄 Pages actives maintenant</div>
        ${topPages.length ? topPages.map(([page, u], i) => {
          const barPct = Math.round((u)/((topPages[0][1])||1)*100);
          return `<div style="display:flex;align-items:center;gap:8px;padding:7px 0;border-bottom:1px solid rgba(255,255,255,0.04)">
            <div style="font-size:10px;font-weight:800;color:var(--fp-text-faint);width:16px;text-align:center">${i+1}</div>
            <div style="flex:1;overflow:hidden">
              <div style="font-size:11px;color:var(--fp-text);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${escHtml(page)}</div>
              <div style="height:3px;background:var(--fp-track);border-radius:2px;margin-top:3px">
                <div style="height:100%;width:${barPct}%;background:#ef4444;border-radius:2px"></div>
              </div>
            </div>
            <div style="display:flex;align-items:center;gap:4px;flex-shrink:0">
              <div style="width:6px;height:6px;border-radius:50%;background:#ef4444;animation:pulse 1.5s infinite"></div>
              <span style="font-size:12px;font-weight:800;color:#ef4444">${u}</span>
            </div>
          </div>`;
        }).join('') : `<div style="text-align:center;padding:24px;color:var(--fp-text-muted);font-size:11px">
          ${_ga4Connected() ? 'Actualisez pour voir les pages actives' : 'Connectez GA4 pour voir les données live'}
          ${_ga4Connected() ? '<br><button class="fp-btn fp-btn-ghost fp-btn-sm" style="margin-top:8px" onclick="window._fpLiveAPI?.refresh()">🔄 Actualiser</button>' : ''}
        </div>`}
      </div>

      <!-- Live geo -->
      <div class="fp-card">
        <div class="fp-card-title" style="margin-bottom:14px">🌍 Localisation live</div>
        ${topCities.length ? topCities.map(([city, u]) => `
          <div style="display:flex;align-items:center;gap:10px;margin-bottom:8px">
            <div style="flex:1;font-size:12px;color:var(--fp-text)">${escHtml(city)}</div>
            <div class="fp-progress-track" style="width:80px;height:6px">
              <div class="fp-progress-fill" style="width:${Math.round((u)/(topCities[0][1]||1)*100)}%;background:#ef4444"></div>
            </div>
            <div style="font-size:12px;font-weight:700;color:#ef4444;min-width:28px;text-align:right">${u}</div>
          </div>`).join('') : `<div style="text-align:center;padding:24px;color:var(--fp-text-muted);font-size:11px">
          ${_ga4Connected() ? 'Actualisez pour voir la géolocalisation live' : 'Connectez GA4'}
        </div>`}

        <div style="margin-top:16px;padding:10px;background:rgba(239,68,68,0.06);border-radius:8px">
          <div style="font-size:11px;font-weight:600;color:var(--fp-text);margin-bottom:4px">📡 Fréquence d\'actualisation</div>
          <select onchange="window._fpLiveAPI?.setInterval(parseInt(this.value)*1000)"
            style="background:var(--fp-inner-card);border:1px solid var(--fp-border);border-radius:6px;color:var(--fp-text);font-size:11px;padding:4px 8px;width:100%">
            <option value="30">Toutes les 30 secondes</option>
            <option value="60">Toutes les minutes</option>
            <option value="300">Toutes les 5 minutes</option>
          </select>
        </div>
      </div>
    </div>

    <!-- EVENT STREAM SIMULATION -->
    <div class="fp-card">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:14px">
        <div class="fp-card-title" style="margin-bottom:0">⚡ Flux d\'événements live</div>
        <div style="display:flex;align-items:center;gap:4px;font-size:11px;color:#ef4444">
          <div style="width:6px;height:6px;border-radius:50%;background:#ef4444;animation:pulse 1s infinite"></div>
          LIVE
        </div>
      </div>
      <div id="fp-event-stream" style="font-family:var(--fp-font-mono);font-size:11px;color:var(--fp-text-muted);max-height:200px;overflow-y:auto">
        ${(()=>{
          const _rt = (window._fpLiveState?.data?.realtime) || (window.FP_DATA?.ga4?.realtime);
          const _rtRows = _rt?.rows || [];
          if (!_ga4Connected()) return '<div style="padding:24px;text-align:center;color:var(--fp-text-muted);font-size:11px">🔌 Connectez Google Analytics 4 pour voir les événements en temps réel.</div>';
          if (!_rtRows.length) return '<div style="padding:24px;text-align:center;color:var(--fp-text-muted);font-size:11px">📡 Actualisez les données temps réel pour voir le flux d\u2019événements.<br><button class="fp-btn fp-btn-ghost fp-btn-sm" style="margin-top:8px" onclick="window._fpLiveAPI?.refresh()">🔄 Actualiser</button></div>';
          return _rtRows.slice(0,10).map(r => {
            const page = r.dimensionValues?.[2]?.value || '/';
            const city = r.dimensionValues?.[1]?.value || '';
            const dev  = r.dimensionValues?.[3]?.value || 'desktop';
            const u    = parseInt(r.metricValues?.[0]?.value || 1);
            const devI = dev==='mobile'?'📱':dev==='tablet'?'📱':'🖥️';
            return '<div style="padding:4px 0;border-bottom:1px solid rgba(255,255,255,0.04);display:flex;align-items:center;gap:8px"><span style="font-size:12px">' + devI + '</span><span style="flex:1;font-size:11px;color:var(--fp-text);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">' + escHtml(page) + '</span>' + (city ? '<span style="font-size:10px;color:var(--fp-text-faint)">' + escHtml(city) + '</span>' : '') + '<span style="font-size:11px;font-weight:700;color:#ef4444;flex-shrink:0">' + u + ' actif' + (u>1?'s':'') + '</span></div>';
          }).join('');
        })()}
      </div>
    </div>

    <style>
      @keyframes pulse { 0%,100%{opacity:1} 50%{opacity:0.4} }
    </style>
  `;
}

// ─────────────────────────────────────────────────────────────────
// EXPOSE GLOBALS — pour fp-backend.js (Socket.IO/SSE réaltime)
// ─────────────────────────────────────────────────────────────────
// fp-backend.js utilise window.STATE, window.render, window.showToast
// pour mettre à jour le dashboard en temps réel sans modifier ce fichier.
window.STATE     = STATE;
window.render    = render;

// ─────────────────────────────────────────────────────────────────
// getBillingStatus() — canonical read for the current subscription status.
// Reads from STATE.billing first (both .subscriptionStatus and .status),
// then falls back to STATE.me.subscriptionStatus.
// Always returns a string — never undefined or null.
// ─────────────────────────────────────────────────────────────────
window.getBillingStatus = function() {
  var b = STATE.billing || {};
  var m = STATE.me || {};
  return b.subscriptionStatus || b.status || m.subscriptionStatus || 'pending_billing';
};

window._fpToggleChecklistExtra = function(id, done) {
  if (!STATE.checklistExtra) STATE.checklistExtra = {};
  STATE.checklistExtra[id] = !done;
  saveChecklistExtra();
  render();
};
window.showToast   = showToast;
window.navigate    = navigate;
window.navigateSub = navigateSub;
window.apiAction   = apiAction;

// ── Geocode / GPS helpers (window-scope to avoid inline multiline issues) ─
window._fpGeocodeAddr = async function() {
  var q=(document.getElementById('fp-loc-address')||{value:''}).value||'';
  var q2=(document.getElementById('fp-loc-city')||{value:''}).value||'';
  var query=(q||q2).trim();
  if(!query){showToast('warning','Saisissez une adresse ou une ville à géocoder');return;}
  showToast('info','Géocodage en cours…');
  try{
    var r=await apiAction('POST','/api/org/geocode',{address:query});
    if(r&&r.ok){
      if(r.address&&document.getElementById('fp-loc-address'))document.getElementById('fp-loc-address').value=r.address;
      if(r.city&&document.getElementById('fp-loc-city'))document.getElementById('fp-loc-city').value=r.city;
      if(r.postalCode&&document.getElementById('fp-loc-postal'))document.getElementById('fp-loc-postal').value=r.postalCode;
      if(r.country&&document.getElementById('fp-loc-country'))document.getElementById('fp-loc-country').value=r.country;
      if(r.latitude!=null&&document.getElementById('fp-loc-lat'))document.getElementById('fp-loc-lat').value=r.latitude.toFixed(6);
      if(r.longitude!=null&&document.getElementById('fp-loc-lng'))document.getElementById('fp-loc-lng').value=r.longitude.toFixed(6);
      showToast('success','✓ Coordonnées : '+r.latitude.toFixed(4)+', '+r.longitude.toFixed(4));
    }else{showToast('error',(r&&r.error)||'Adresse introuvable');}
  }catch(e){showToast('error','Erreur de géocodage — vérifiez votre adresse');}
};
window._fpDetectPos = function() {
  if(!navigator.geolocation){showToast('error','Géolocalisation non supportée par ce navigateur');return;}
  showToast('info','Demande d\'autorisation GPS…');
  navigator.geolocation.getCurrentPosition(async function(pos){
    var lat=pos.coords.latitude,lng=pos.coords.longitude;
    if(document.getElementById('fp-loc-lat'))document.getElementById('fp-loc-lat').value=lat.toFixed(6);
    if(document.getElementById('fp-loc-lng'))document.getElementById('fp-loc-lng').value=lng.toFixed(6);
    showToast('info','Position obtenue — géocodage inverse…');
    try{
      var r=await apiAction('POST','/api/org/geocode',{lat:lat,lng:lng});
      if(r&&r.ok){
        if(r.address&&document.getElementById('fp-loc-address'))document.getElementById('fp-loc-address').value=r.address;
        if(r.city&&document.getElementById('fp-loc-city'))document.getElementById('fp-loc-city').value=r.city;
        if(r.postalCode&&document.getElementById('fp-loc-postal'))document.getElementById('fp-loc-postal').value=r.postalCode;
        if(r.country&&document.getElementById('fp-loc-country'))document.getElementById('fp-loc-country').value=r.country;
        showToast('success','📡 Position : '+r.city+', '+r.country);
      }else{showToast('success','📡 GPS : '+lat.toFixed(4)+', '+lng.toFixed(4));}
    }catch(e){showToast('success','📡 GPS : '+lat.toFixed(4)+', '+lng.toFixed(4));}
  },function(err){
    var msgs={1:'Autorisation refusée — activez la géolocalisation dans les réglages',2:'Position indisponible',3:'Délai dépassé'};
    showToast('error',msgs[err.code]||'Erreur GPS');
  },{enableHighAccuracy:true,timeout:10000});
};

