// ─────────────────────────────────────────────────────────────────────────────
// PERFORMANCE / PAGESPEED PAGES
// ─────────────────────────────────────────────────────────────────────────────

// ── BUG-W1-007/008/009 helpers ────────────────────────────────────────────────
function safePercent(value, total) {
  var n = Number(value), d = Number(total);
  if (!Number.isFinite(n) || !Number.isFinite(d) || d <= 0) return 0;
  return Math.round((n / d) * 100);
}

function getWebVitalRating(metric, value) {
  if (!Number.isFinite(value)) return 'unavailable';
  var t = { lcp:{good:2500,poor:4000}, cls:{good:0.1,poor:0.25}, inp:{good:200,poor:500}, ttfb:{good:800,poor:1800}, fcp:{good:1800,poor:3000}, tbt:{good:200,poor:600}, si:{good:3400,poor:5800} }[metric];
  if (!t) return 'unknown';
  return value <= t.good ? 'good' : value <= t.poor ? 'needs-improvement' : 'poor';
}

// ── BUG-W1-002/004/005/006 — PSI normalizer ───────────────────────────────────
function _psiCategoryFromId(id) {
  var s = String(id||'').toLowerCase();
  if (s.includes('render-block') || s.includes('critical-request')) return 'render-blocking';
  if (s.includes('unused-js') || s.includes('unused-javascript') || s.includes('unminified-javascript')) return 'unused-js';
  if (s.includes('unused-css') || s.includes('unminified-css')) return 'unused-css';
  if (s.includes('image') || s.includes('webp') || s.includes('offscreen')) return 'images';
  return 'other';
}

function _normalizePSIStrategy(r) {
  if (!r) return null;
  if (r.cwv) return r; // already normalized
  var m = r.metrics || {};
  return {
    scores:       r.scores || {},
    cwv: {
      lcp:        Number.isFinite(m.lcp)  ? m.lcp  : null,
      fcp:        Number.isFinite(m.fcp)  ? m.fcp  : null,
      cls:        Number.isFinite(m.cls)  ? m.cls  : null,
      tbt:        Number.isFinite(m.tbt)  ? m.tbt  : null,
      inp:        null,
      ttfb:       null,
      speedIndex: Number.isFinite(m.si)   ? m.si   : null,
    },
    opportunities: (r.opportunities || []).map(function(o) {
      return {
        id:          o.id || '',
        title:       o.title || '',
        description: o.description || '',
        category:    _psiCategoryFromId(o.id),
        savingsMs:   typeof o.savings === 'number' ? o.savings * 1000 : 0,
        savingsBytes: o.savingsBytes || 0,
      };
    }),
    criticalIssues: (r.criticalIssues || []).map(function(i) {
      return typeof i === 'string' ? i : (i && i.title) || '';
    }).filter(Boolean),
    passedAudits:  null,
    totalAudits:   null,
    url:           r.url || '',
    strategy:      r.strategy || '',
    analyzedAt:    r.analyzedAt || null,
  };
}

function normalizePageSpeedResult(raw) {
  if (!raw) return null;
  return {
    url:              raw.url || '',
    analyzedAt:       raw.analyzedAt || null,
    mobile:           _normalizePSIStrategy(raw.mobile),
    desktop:          _normalizePSIStrategy(raw.desktop),
    aiRecommendations: raw.aiRecommendations || null,
  };
}

// ── BUG-W1-V32-001 — Single source of truth for pagespeed storage ─────────────
// FP_PAGESPEED_API.analyze() stores raw data directly; always call this to
// normalize and overwrite so render functions see mobile.cwv.* not mobile.metrics.*
function setPageSpeedResult(raw) {
  var normalized = normalizePageSpeedResult(raw);
  if (window.FP_DATA) window.FP_DATA.pagespeed = normalized;
  // ── Persist PSI results across sessions / tab restores ────────────────────
  try {
    if (normalized) {
      localStorage.setItem('fp-psi-last', JSON.stringify({ data: normalized, _ts: Date.now() }));
    }
  } catch(_) {}
  return normalized;
}
window.setPageSpeedResult = setPageSpeedResult;

// ── BUG-W1-V32-003 — Metric formatter — no ? fallback ────────────────────────
function formatMetricOrUnavailable(value, metric) {
  if (!Number.isFinite(value)) return 'N/A';
  if (metric === 'cls') return value.toFixed(3);
  return Math.round(value) + ' ms';
}

// ── BUG-W1-008/009 — Audit summary builder ────────────────────────────────────
function buildTechnicalAuditSummary(audits, psiMobile) {
  var list = Array.isArray(audits) ? audits : [];
  var completedAudits  = list.filter(function(a){ return ['ok','warn','completed','success'].includes(a.status); });
  var processingAudits = list.filter(function(a){ return a.status === 'processing'; });
  var failedAudits     = list.filter(function(a){ return a.status === 'error' || a.status === 'failed'; });
  var opps = (psiMobile && psiMobile.opportunities) || [];
  return {
    totalAudits:          list.length,
    completedAudits:      completedAudits.length,
    processingAudits:     processingAudits.length,
    failedAudits:         failedAudits.length,
    renderBlockingIssues: opps.filter(function(o){ return o.category === 'render-blocking'; }),
    jsCssIssues:          opps.filter(function(o){ return o.category === 'unused-js' || o.category === 'unused-css'; }),
    imageIssues:          opps.filter(function(o){ return o.category === 'images'; }),
    accessibilityIssues:  [],
    technicalSeoIssues:   [],
  };
}

function psiScoreColor(score) {
  if (score >= 90) return '#10b981';
  if (score >= 50) return '#f59e0b';
  return '#ef4444';
}

function psiScoreLabel(score) {
  if (score >= 90) return 'Bon';
  if (score >= 50) return 'À améliorer';
  return 'Faible';
}

function cwvBadgeClass(metric, value) {
  const thresholds = {
    lcp:  { good: 2500, poor: 4000 },
    cls:  { good: 0.1,  poor: 0.25 },
    inp:  { good: 200,  poor: 500  },
    ttfb: { good: 800,  poor: 1800 },
    fcp:  { good: 1800, poor: 3000 },
    tbt:  { good: 200,  poor: 600  },
  };
  const t = thresholds[metric];
  if (!t) return 'good';
  if (value <= t.good) return 'good';
  if (value <= t.poor) return 'needs-improvement';
  return 'poor';
}

function cwvBadgeLabel(cls) {
  return { good: '✓ Bon', 'needs-improvement': '⚠ À améliorer', poor: '✗ Faible' }[cls] || cls;
}

function renderPSIRing(score, size) {
  size = size || 88;
  const r = (size / 2) - 8;
  const circ = 2 * Math.PI * r;
  const pct = Math.max(0, Math.min(100, score)) / 100;
  const color = psiScoreColor(score);
  return `<div class="fp-psi-score-ring" style="width:${size}px;height:${size}px">
    <svg width="${size}" height="${size}" viewBox="0 0 ${size} ${size}">
      <circle cx="${size/2}" cy="${size/2}" r="${r}" stroke="var(--fp-border)" stroke-width="6"/>
      <circle cx="${size/2}" cy="${size/2}" r="${r}" stroke="${color}" stroke-width="6"
        stroke-dasharray="${circ}" stroke-dashoffset="${circ*(1-pct)}"
        stroke-linecap="round" style="transition:stroke-dashoffset 1s ease"/>
    </svg>
    <div class="fp-psi-score-text" style="color:${color};font-size:${size>70?'20px':'14px'}">${score}</div>
  </div>`;
}

function renderPSIScoreCards(data, label) {
  if (!data) return `<div class="fp-empty-state"><p>Aucune donnée ${label} — lancez une analyse.</p></div>`;
  const s = data.scores || {};
  const cats = [
    { key: 'performance',   label: 'Performance',   score: s.performance  || 0 },
    { key: 'accessibility', label: 'Accessibilité', score: s.accessibility || 0 },
    { key: 'seo',           label: 'SEO',           score: s.seo          || 0 },
    { key: 'bestPractices', label: 'Bonnes pratiques', score: s.bestPractices || 0 },
  ];
  return `<div class="fp-grid" style="grid-template-columns:repeat(4,1fr);gap:12px">
    ${cats.map(c => `<div class="fp-psi-score-card">
      ${renderPSIRing(c.score)}
      <div class="fp-psi-score-label">${escHtml(c.label)}</div>
      <div class="fp-badge" style="background:${psiScoreColor(c.score)}22;color:${psiScoreColor(c.score)};font-size:10px">${psiScoreLabel(c.score)}</div>
    </div>`).join('')}
  </div>`;
}

function renderCWVCards(cwv) {
  if (!cwv) return '';
  const metrics = [
    { key:'lcp',  label:'LCP',   value: cwv.lcp,        unit:'ms',  desc:'Largest Contentful Paint',  good:2500, poor:4000 },
    { key:'cls',  label:'CLS',   value: cwv.cls,        unit:'',    desc:'Cumulative Layout Shift',    good:0.1,  poor:0.25 },
    { key:'inp',  label:'INP',   value: cwv.inp,        unit:'ms',  desc:'Interaction to Next Paint',  good:200,  poor:500  },
    { key:'ttfb', label:'TTFB',  value: cwv.ttfb,       unit:'ms',  desc:'Time to First Byte',         good:800,  poor:1800 },
    { key:'fcp',  label:'FCP',   value: cwv.fcp,        unit:'ms',  desc:'First Contentful Paint',     good:1800, poor:3000 },
    { key:'tbt',  label:'TBT',   value: cwv.tbt,        unit:'ms',  desc:'Total Blocking Time',        good:200,  poor:600  },
    { key:'si',   label:'SI',    value: cwv.speedIndex, unit:'ms',  desc:'Speed Index',                good:3400, poor:5800 },
  ];
  return `<div class="fp-grid" style="grid-template-columns:repeat(4,1fr);gap:12px">
    ${metrics.map(m => {
      // BUG-W1-004/005: null protection — show "Donnée indisponible" if metric is absent
      if (m.value === null || m.value === undefined || !Number.isFinite(m.value)) {
        return `<div class="fp-cwv-card">
          <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:8px">
            <span style="font-size:11px;font-weight:700;letter-spacing:1px;color:var(--fp-text-faint)">${m.label}</span>
          </div>
          <div style="font-size:13px;color:var(--fp-text-faint);padding:6px 0">Donnée indisponible</div>
          <div style="font-size:10px;color:var(--fp-text-faint)">${escHtml(m.desc)}</div>
        </div>`;
      }
      const cls = cwvBadgeClass(m.key, m.value);
      const pct = Math.min(100, (m.value / (m.poor * 1.5)) * 100);
      const markerLeft = Math.min(96, Math.max(4, pct));
      const color = { good:'#10b981','needs-improvement':'#f59e0b', poor:'#ef4444' }[cls];
      const displayVal = m.key === 'cls' ? m.value.toFixed(3) : Math.round(m.value).toLocaleString('fr-FR');
      return `<div class="fp-cwv-card">
        <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:8px">
          <span style="font-size:11px;font-weight:700;letter-spacing:1px;color:var(--fp-text-faint)">${m.label}</span>
          <span class="fp-cwv-badge fp-cwv-badge--${cls}">${cwvBadgeLabel(cls)}</span>
        </div>
        <div style="margin-bottom:4px">
          <span class="fp-cwv-value" style="color:${color}">${displayVal}</span>
          <span class="fp-cwv-unit">${m.unit}</span>
        </div>
        <div style="font-size:11px;color:var(--fp-text-faint);margin-bottom:10px">${escHtml(m.desc)}</div>
        <div class="fp-cwv-threshold-bar">
          <div class="fp-cwv-threshold-marker" style="left:${markerLeft}%;background:${color}"></div>
        </div>
        <div style="display:flex;justify-content:space-between;font-size:9px;color:var(--fp-text-faint);margin-top:6px">
          <span>${m.key==='cls'?m.good.toFixed(1):m.good+'ms'}</span>
          <span>${m.key==='cls'?m.poor.toFixed(2):m.poor+'ms'}</span>
        </div>
      </div>`;
    }).join('')}
  </div>`;
}

function renderOpportunities(opps) {
  if (!opps || !opps.length) return `<div class="fp-empty-state" style="padding:24px"><p>Aucune opportunité détectée — super score !</p></div>`;
  const catIcons = { 'render-blocking':'⚡','unused-js':'📦','unused-css':'🎨','images':'🖼','other':'🔧' };
  return `<div class="fp-flex-col" style="gap:8px">
    ${opps.slice(0,10).map(o => {
      const savings = o.savingsMs > 0 ? `-${(o.savingsMs/1000).toFixed(1)}s` : o.savingsBytes > 0 ? `-${(o.savingsBytes/1024).toFixed(0)}KB` : '';
      return `<div class="fp-psi-opportunity">
        <div class="fp-psi-opp-icon" style="background:var(--fp-bg-body)">${catIcons[o.category]||'🔧'}</div>
        <div style="flex:1;min-width:0">
          <div style="font-size:13px;font-weight:600;color:var(--fp-text);margin-bottom:2px">${escHtml(o.title)}</div>
          <div style="font-size:11px;color:var(--fp-text-faint);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${escHtml(o.description||'')}</div>
        </div>
        ${savings ? `<span class="fp-psi-savings">${savings}</span>` : ''}
      </div>`;
    }).join('')}
  </div>`;
}

function renderPerformanceUrlBar(currentUrl) {
  const suggestions = (STATE.audits||[]).slice(0,5).map(a=>a.url);
  return `<div style="margin-bottom:20px">
    <div class="fp-psi-url-bar">
      <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="color:var(--fp-text-faint);flex-shrink:0"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
      <input id="fp-psi-url-input" class="fp-psi-url-input" type="url" placeholder="https://example.com" value="${escHtml(currentUrl||'')}" list="fp-psi-url-list" autocomplete="off"/>
      <datalist id="fp-psi-url-list">${suggestions.map(u=>`<option value="${escHtml(u)}">`).join('')}</datalist>
      <button class="fp-btn fp-btn-primary" id="fp-psi-analyze-btn" style="white-space:nowrap;padding:8px 20px">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="23 4 23 10 17 10"/><path d="M20.49 15a9 9 0 1 1-2.12-9.36L23 10"/></svg>
        Analyser
      </button>
    </div>
    ${suggestions.length ? `<div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:8px">${suggestions.slice(0,4).map(u=>`<button class="fp-badge fp-badge--ghost" onclick="document.getElementById('fp-psi-url-input').value='${escHtml(u)}'" style="cursor:pointer;font-size:11px">${escHtml(u)}</button>`).join('')}</div>` : ''}
  </div>`;
}

function getFirstAuditUrl() {
  return (STATE.audits && STATE.audits[0] && STATE.audits[0].url) || '';
}

function renderPerformance() {
  const sub = STATE.subRoute;
  const psi = window.FP_DATA && window.FP_DATA.pagespeed;

  if (sub === 'mobile')       return renderPerformanceStrategy('mobile');
  if (sub === 'desktop')      return renderPerformanceStrategy('desktop');
  if (sub === 'history')      return renderPerformanceHistory();
  if (sub === 'opportunities') return renderPerformanceOpportunities();
  if (sub === 'ai')           return renderPerformanceAIReco();

  // Overview
  const mobile  = psi && psi.mobile;
  const desktop = psi && psi.desktop;
  const isAnalyzing = window._fpPsiAnalyzing || false;

  return `
  <div class="fp-section-header">
    <div>
      <h1 class="fp-section-title">Performance Web</h1>
      <p class="fp-section-sub">Analyse PageSpeed Insights · Core Web Vitals · Optimisations</p>
    </div>
    <div class="fp-section-actions">
      <button class="fp-btn fp-btn-primary" onclick="navigate('core-web-vitals')">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M22 12h-4l-3 9L9 3l-3 9H2"/></svg>
        Core Web Vitals
      </button>
      <button class="fp-btn fp-btn-primary" onclick="navigate('technical-audit')">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="16 18 22 12 16 6"/><polyline points="8 6 2 12 8 18"/></svg>
        Audit Technique
      </button>
    </div>
  </div>

  ${renderPerformanceUrlBar(getFirstAuditUrl())}

  ${aiBlock(
    psi
      ? `Score mobile : <strong>${psi.mobile?.scores?.performance||0}/100</strong> · Score desktop : <strong>${psi.desktop?.scores?.performance||0}/100</strong>. ${(psi.mobile?.scores?.performance||0) < 70 ? 'Performance mobile insuffisante — optimisez images et serveur pour améliorer les conversions.' : 'Bonne performance. Analysez les Core Web Vitals pour aller plus loin.'}`
      : (STATE.audits||[]).length > 0
        ? `${(STATE.audits||[]).length} site${(STATE.audits||[]).length>1?'s':''} dans votre portefeuille. Entrez une URL et lancez une analyse PageSpeed pour voir les scores en temps réel.`
        : "Entrez une URL et lancez une analyse PageSpeed Insights pour obtenir vos scores mobile, desktop et Core Web Vitals.",
    ['Analyser mes sites', 'Core Web Vitals', 'Audit technique']
  )}

  ${isAnalyzing ? `
  <div class="fp-psi-loading">
    <div class="fp-psi-spinner"></div>
    <div style="text-align:center">
      <div style="font-size:15px;font-weight:600;margin-bottom:6px">Analyse PageSpeed en cours…</div>
      <div style="font-size:13px;color:var(--fp-text-faint)">Récupération des données mobile et desktop depuis Google</div>
    </div>
  </div>` : !psi ? `
  <div class="fp-card" style="text-align:center;padding:48px 32px">
    <div style="font-size:48px;margin-bottom:16px">⚡</div>
    <h3 style="margin-bottom:8px">Analysez votre première page</h3>
    <p style="color:var(--fp-text-muted);font-size:14px;margin-bottom:24px">Entrez une URL et cliquez sur Analyser pour obtenir un rapport complet PageSpeed Insights avec tous les Core Web Vitals.</p>
    <div style="display:flex;gap:12px;justify-content:center;flex-wrap:wrap">
      <div class="fp-badge" style="background:rgba(16,185,129,0.14);color:#10b981;padding:8px 16px;border-radius:10px;font-size:12px;border:1px solid rgba(16,185,129,0.35)">✓ Score Performance</div>
      <div class="fp-badge" style="background:rgba(37,99,235,0.14);color:#2563EB;padding:8px 16px;border-radius:10px;font-size:12px;border:1px solid rgba(37,99,235,0.35)">✓ LCP / CLS / INP / TTFB</div>
      <div class="fp-badge" style="background:rgba(139,92,246,0.14);color:#8b5cf6;padding:8px 16px;border-radius:10px;font-size:12px;border:1px solid rgba(139,92,246,0.35)">✓ Recommandations IA</div>
    </div>
  </div>` : `
  <!-- Score Cards Grid — Mobile vs Desktop -->
  <div class="fp-grid" style="grid-template-columns:1fr 1fr;gap:16px;margin-bottom:20px">
    <div class="fp-card">
      <div class="fp-card-header" style="margin-bottom:16px">
        <div style="display:flex;align-items:center;gap:8px">
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="5" y="2" width="14" height="20" rx="2"/><line x1="12" y1="18" x2="12.01" y2="18"/></svg>
          <span style="font-weight:600">Mobile</span>
        </div>
        <span class="fp-badge" style="background:${psiScoreColor(mobile?.scores?.performance||0)}22;color:${psiScoreColor(mobile?.scores?.performance||0)}">${mobile?.scores?.performance||0}/100</span>
      </div>
      ${renderPSIScoreCards(mobile,'mobile')}
    </div>
    <div class="fp-card">
      <div class="fp-card-header" style="margin-bottom:16px">
        <div style="display:flex;align-items:center;gap:8px">
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="2" y="3" width="20" height="14" rx="2"/><line x1="8" y1="21" x2="16" y2="21"/><line x1="12" y1="17" x2="12" y2="21"/></svg>
          <span style="font-weight:600">Desktop</span>
        </div>
        <span class="fp-badge" style="background:${psiScoreColor(desktop?.scores?.performance||0)}22;color:${psiScoreColor(desktop?.scores?.performance||0)}">${desktop?.scores?.performance||0}/100</span>
      </div>
      ${renderPSIScoreCards(desktop,'desktop')}
    </div>
  </div>

  <!-- Core Web Vitals Mobile -->
  <div class="fp-card" style="margin-bottom:20px">
    <div class="fp-card-header" style="margin-bottom:16px">
      <h3 class="fp-card-title">Core Web Vitals · Mobile</h3>
      <button class="fp-btn fp-btn-primary" onclick="navigateSub('mobile')" style="font-size:12px">Voir détails →</button>
    </div>
    ${mobile?.cwv ? renderCWVCards(mobile.cwv) : '<div class="fp-empty-state"><p>Données CWV non disponibles.</p></div>'}
  </div>

  <!-- Opportunities -->
  <div class="fp-grid" style="grid-template-columns:1fr 1fr;gap:16px">
    <div class="fp-card">
      <div class="fp-card-header" style="margin-bottom:16px">
        <h3 class="fp-card-title">Opportunités d\'optimisation</h3>
        <span class="fp-badge fp-badge--accent">${(mobile?.opportunities||[]).length} items</span>
      </div>
      ${renderOpportunities(mobile?.opportunities||[])}
    </div>
    <div class="fp-card">
      <div class="fp-card-header" style="margin-bottom:16px">
        <h3 class="fp-card-title">Problèmes critiques</h3>
        <span class="fp-badge" style="background:rgba(239,68,68,0.12);color:#ef4444">${(mobile?.criticalIssues||[]).length} critiques</span>
      </div>
      ${(mobile?.criticalIssues||[]).length ? `
      <div class="fp-flex-col" style="gap:8px">
        ${(mobile.criticalIssues).map(issue=>`
        <div style="display:flex;align-items:flex-start;gap:10px;padding:10px;background:rgba(239,68,68,0.06);border:1px solid rgba(239,68,68,0.2);border-radius:8px">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#ef4444" stroke-width="2" style="flex-shrink:0;margin-top:2px"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>
          <span style="font-size:13px;color:var(--fp-text)">${escHtml(issue)}</span>
        </div>`).join('')}
      </div>` : `<div class="fp-empty-state" style="padding:20px"><p style="color:#10b981">✓ Aucun problème critique détecté</p></div>`}

      <!-- AI Recommendations button -->
      <div style="margin-top:16px;padding-top:16px;border-top:1px solid var(--fp-border)">
        <button class="fp-btn fp-btn-primary" style="width:100%" onclick="navigateSub('ai')">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 2a2 2 0 0 1 2 2c0 .74-.4 1.39-1 1.73V7h1a7 7 0 0 1 7 7h1a1 1 0 0 1 0 2h-1v1a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-1H2a1 1 0 0 1 0-2h1a7 7 0 0 1 7-7h1V5.73c-.6-.34-1-.99-1-1.73a2 2 0 0 1 2-2z"/></svg>
          Obtenir des recommandations IA
        </button>
      </div>
    </div>
  </div>
  `}`;
}

function renderPerformanceStrategy(strategy) {
  const psi = window.FP_DATA && window.FP_DATA.pagespeed;
  const data = psi && psi[strategy];
  const label = strategy === 'mobile' ? 'Mobile' : 'Desktop';

  return `
  <div class="fp-section-header">
    <h1 class="fp-section-title">Performance ${label}</h1>
  </div>
  ${renderPerformanceUrlBar(psi && psi.url)}
  ${!data ? `<div class="fp-card" style="text-align:center;padding:40px"><p>Lancez une analyse pour voir les données ${label}.</p></div>` : `
  <div class="fp-card" style="margin-bottom:16px">
    <div class="fp-card-header" style="margin-bottom:16px">
      <h3 class="fp-card-title">Scores ${label}</h3>
      <span style="font-size:12px;color:var(--fp-text-faint)">${psi.url}</span>
    </div>
    ${renderPSIScoreCards(data, strategy)}
  </div>
  <div class="fp-card" style="margin-bottom:16px">
    <div class="fp-card-header" style="margin-bottom:16px"><h3 class="fp-card-title">Core Web Vitals</h3></div>
    ${renderCWVCards(data.cwv)}
  </div>
  <div class="fp-card">
    <div class="fp-card-header" style="margin-bottom:16px">
      <h3 class="fp-card-title">Opportunités</h3>
      <span class="fp-badge fp-badge--accent">${(data.opportunities||[]).length}</span>
    </div>
    ${renderOpportunities(data.opportunities||[])}
  </div>`}`;
}

function renderPerformanceHistory() {
  const hist = window.FP_DATA && window.FP_DATA.pagespeedHistory;
  const history = hist && hist.history || [];

  return `
  <div class="fp-section-header">
    <h1 class="fp-section-title">Historique des scores</h1>
    <button class="fp-btn fp-btn-primary" onclick="if(window.FP_PAGESPEED_API){window.FP_PAGESPEED_API.history(document.getElementById('fp-psi-url-input')&&document.getElementById('fp-psi-url-input').value||'').then(()=>render())}">Actualiser</button>
  </div>
  ${renderPerformanceUrlBar(window.FP_DATA&&window.FP_DATA.pagespeed&&window.FP_DATA.pagespeed.url)}
  ${!history.length ? `
  <div class="fp-card" style="text-align:center;padding:40px">
    <p style="color:var(--fp-text-muted)">Aucun historique disponible.<br>L\'historique se construit après chaque analyse.</p>
  </div>` : `
  <div class="fp-card" style="margin-bottom:16px">
    <div class="fp-card-header" style="margin-bottom:16px">
      <h3 class="fp-card-title">Évolution du score Performance</h3>
      <span class="fp-badge fp-badge--ghost">${history.length} points</span>
    </div>
    <svg class="fp-psi-history-chart" viewBox="0 0 800 120" preserveAspectRatio="none">
      ${(()=>{
        const w=800,h=100,pts=history.map((r,i)=>({x:i*(w/(history.length-1||1)),y:h-(r.performance/100)*h}));
        const path=pts.map((p,i)=>i===0?`M${p.x},${p.y}`:`L${p.x},${p.y}`).join(' ');
        const area=path+` L${pts[pts.length-1].x},${h} L0,${h} Z`;
        return `
          <defs><linearGradient id="histGrad" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="var(--fp-accent)" stop-opacity="0.3"/><stop offset="100%" stop-color="var(--fp-accent)" stop-opacity="0"/></linearGradient></defs>
          <path d="${area}" fill="url(#histGrad)"/>
          <path d="${path}" fill="none" stroke="var(--fp-accent)" stroke-width="2"/>
          ${pts.map(p=>`<circle cx="${p.x}" cy="${p.y}" r="4" fill="var(--fp-accent)"/>`).join('')}`;
      })()}
    </svg>
    <div style="display:flex;justify-content:space-between;font-size:11px;color:var(--fp-text-faint);margin-top:6px">
      <span>${new Date(history[0]?.createdAt||Date.now()).toLocaleDateString('fr-FR')}</span>
      <span>${new Date(history[history.length-1]?.createdAt||Date.now()).toLocaleDateString('fr-FR')}</span>
    </div>
  </div>
  <div class="fp-card">
    <div class="fp-card-header" style="margin-bottom:16px"><h3 class="fp-card-title">Détail des mesures</h3></div>
    <table class="fp-table" style="width:100%">
      <thead><tr>
        <th>Date</th><th>Performance</th><th>Accessibilité</th><th>SEO</th><th>Bonnes pratiques</th><th>LCP</th><th>CLS</th>
      </tr></thead>
      <tbody>${history.slice().reverse().slice(0,20).map(r=>`<tr>
        <td style="font-size:12px;color:var(--fp-text-faint)">${new Date(r.createdAt).toLocaleDateString('fr-FR')}</td>
        <td><span style="color:${psiScoreColor(r.performance)};font-weight:700">${r.performance}</span></td>
        <td><span style="color:${psiScoreColor(r.accessibility)};font-weight:600">${r.accessibility}</span></td>
        <td><span style="color:${psiScoreColor(r.seo)};font-weight:600">${r.seo}</span></td>
        <td><span style="color:${psiScoreColor(r.bestPractices)};font-weight:600">${r.bestPractices}</span></td>
        <td style="font-size:12px">${Math.round(r.lcp)}ms</td>
        <td style="font-size:12px">${Number(r.cls).toFixed(3)}</td>
      </tr>`).join('')}</tbody>
    </table>
  </div>`}`;
}

function renderPerformanceOpportunities() {
  const psi = window.FP_DATA && window.FP_DATA.pagespeed;
  const opps = (psi && psi.mobile && psi.mobile.opportunities) || [];

  const grouped = { 'render-blocking':[], 'unused-js':[], 'unused-css':[], 'images':[], other:[] };
  opps.forEach(o => { (grouped[o.category] || grouped.other).push(o); });

  const catLabels = { 'render-blocking':'Ressources bloquantes','unused-js':'JavaScript non utilisé','unused-css':'CSS non utilisé','images':'Optimisation images','other':'Autres' };
  const catColors = { 'render-blocking':'#ef4444','unused-js':'#f59e0b','unused-css':'#8b5cf6','images':'#06b6d4','other':'#64748b' };

  return `
  <div class="fp-section-header">
    <h1 class="fp-section-title">Opportunités d\'optimisation</h1>
    <span class="fp-badge fp-badge--accent">${opps.length} total · ${opps.reduce((s,o)=>s+(o.savingsMs||0),0)/1000|0}s économisables</span>
  </div>
  ${!psi ? `<div class="fp-card" style="text-align:center;padding:40px"><p>Lancez une analyse pour découvrir les opportunités.</p></div>` : `
  ${Object.entries(grouped).filter(([,items])=>items.length>0).map(([cat,items])=>`
  <div class="fp-card" style="margin-bottom:16px">
    <div class="fp-card-header" style="margin-bottom:14px">
      <h3 class="fp-card-title">${catLabels[cat]}</h3>
      <span class="fp-badge" style="background:${catColors[cat]}22;color:${catColors[cat]}">${items.length} item${items.length>1?'s':''}</span>
    </div>
    <div class="fp-flex-col" style="gap:8px">${renderOpportunities(items)}</div>
  </div>`).join('')}
  `}`;
}

function renderPerformanceAIReco() {
  const psi = window.FP_DATA && window.FP_DATA.pagespeed;
  const reco = psi && psi.aiRecommendations;

  return `
  <div class="fp-section-header">
    <h1 class="fp-section-title">Recommandations IA</h1>
    <button class="fp-btn fp-btn-primary" id="fp-psi-ai-btn" onclick="fpGetPSIAIReco()">
      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 2a2 2 0 0 1 2 2c0 .74-.4 1.39-1 1.73V7h1a7 7 0 0 1 7 7h1a1 1 0 0 1 0 2h-1v1a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-1H2a1 1 0 0 1 0-2h1a7 7 0 0 1 7-7h1V5.73c-.6-.34-1-.99-1-1.73a2 2 0 0 1 2-2z"/></svg>
      Générer les recommandations
    </button>
  </div>
  <div class="fp-card">
    ${!psi ? `<div class="fp-empty-state" style="padding:40px"><p>Lancez d\'abord une analyse PageSpeed.</p></div>` :
      reco ? `<div class="fp-ai-block-content" style="font-size:14px;line-height:1.8">${fpMarkdown(reco)}</div>` :
      `<div style="text-align:center;padding:40px">
        <div style="font-size:48px;margin-bottom:16px">🤖</div>
        <h3 style="margin-bottom:8px">Obtenir les recommandations IA</h3>
        <p style="color:var(--fp-text-muted);margin-bottom:20px">L\'IA analysera vos données PageSpeed et génèrera un plan d\'optimisation détaillé.</p>
        <button class="fp-btn fp-btn-primary fp-btn-lg" onclick="fpGetPSIAIReco()">Analyser avec l\'IA</button>
      </div>`}
  </div>`;
}

// ─────────────────────────────────────────────────────────────────────────────
// CORE WEB VITALS PAGE
// ─────────────────────────────────────────────────────────────────────────────

function renderCoreWebVitals() {
  const sub = STATE.subRoute;
  const psi = window.FP_DATA && window.FP_DATA.pagespeed;
  const mobile  = psi && psi.mobile;
  const desktop = psi && psi.desktop;

  if (sub === 'compare') return renderCWVComparison(mobile, desktop);

  const metricPages = { lcp:'LCP', cls:'CLS', inp:'INP', ttfb:'TTFB' };
  if (metricPages[sub]) return renderCWVMetricDetail(sub, mobile, desktop);

  // Default dashboard
  const cwv = mobile && mobile.cwv;
  return `
  <div class="fp-section-header">
    <div>
      <h1 class="fp-section-title">Core Web Vitals</h1>
      <p class="fp-section-sub">LCP · CLS · INP · TTFB · FCP · TBT · Speed Index</p>
    </div>
    <div class="fp-section-actions">
      <button class="fp-btn fp-btn-primary" onclick="navigate('performance')">← Performance</button>
      ${psi ? `<button class="fp-btn fp-btn-primary" onclick="navigateSub('compare')">Comparaison →</button>` : ''}
    </div>
  </div>

  ${aiBlock(
    psi
      ? (() => { const _cwv = psi.mobile && psi.mobile.cwv; const _lcp = (_cwv && Number.isFinite(_cwv.lcp)) ? _cwv.lcp : null; const _cls = (_cwv && Number.isFinite(_cwv.cls)) ? _cwv.cls : null; const _inp = (_cwv && Number.isFinite(_cwv.inp)) ? _cwv.inp : null; const _av = [_lcp,_cls,_inp].filter(function(v){return v!==null;}).length; const _perf = (psi.mobile && psi.mobile.scores) ? (psi.mobile.scores.performance || 0) : 0; const _cwvMsg = _av === 3 ? 'Core Web Vitals analysés. Consultez les opportunités pour optimiser chaque métrique.' : _av > 0 ? 'Données Core Web Vitals partielles.' : 'Données Core Web Vitals indisponibles pour cette analyse.'; return 'LCP mobile : <strong>' + formatMetricOrUnavailable(_lcp,'lcp') + '</strong> · CLS : <strong>' + formatMetricOrUnavailable(_cls,'cls') + '</strong> · INP : <strong>' + formatMetricOrUnavailable(_inp,'inp') + '</strong>. ' + (_perf < 60 ? '⚠️ Score mobile critique — priorité aux optimisations LCP et CLS.' : _cwvMsg); })()
      : "Lancez une analyse depuis Performance pour voir vos Core Web Vitals (LCP, CLS, INP, TTFB) en temps réel.",
    ['Analyser LCP', 'Comparer mobile vs desktop', 'Voir les opportunités']
  )}

  ${!psi ? `
  <div class="fp-card" style="text-align:center;padding:48px">
    <div style="font-size:48px;margin-bottom:16px">📊</div>
    <h3 style="margin-bottom:8px">Aucune donnée CWV</h3>
    <p style="color:var(--fp-text-muted);margin-bottom:24px">Analysez un site depuis la page Performance pour voir les Core Web Vitals.</p>
    <button class="fp-btn fp-btn-primary" onclick="navigate('performance')">Analyser un site</button>
  </div>` : `

  <!-- CWV Status Banner -->
  <div class="fp-card" style="margin-bottom:20px;background:linear-gradient(135deg,rgba(37,99,235,0.08),rgba(139,92,246,0.08));border-color:rgba(37,99,235,0.2)">
    <div style="display:flex;align-items:center;gap:16px;flex-wrap:wrap">
      <div style="flex:1;min-width:200px">
        <div style="font-size:14px;font-weight:700;margin-bottom:4px">${escHtml(psi.url)}</div>
        <div style="font-size:12px;color:var(--fp-text-faint)">Analysé le ${psi.analyzedAt ? new Date(psi.analyzedAt).toLocaleString('fr-FR') : 'récemment'}</div>
      </div>
      <div style="display:flex;gap:20px;flex-wrap:wrap">
        ${[
          {label:'Mobile',score:mobile?.scores?.performance||0},
          {label:'Desktop',score:desktop?.scores?.performance||0},
          {label:'Accessibilité',score:mobile?.scores?.accessibility||0},
          {label:'SEO',score:mobile?.scores?.seo||0},
        ].map(s=>`<div style="text-align:center">
          <div style="font-size:22px;font-weight:800;color:${psiScoreColor(s.score)}">${s.score}</div>
          <div style="font-size:11px;color:var(--fp-text-faint)">${s.label}</div>
        </div>`).join('')}
      </div>
    </div>
  </div>

  <!-- Full CWV grid -->
  <div class="fp-card" style="margin-bottom:20px">
    <div class="fp-card-header" style="margin-bottom:16px">
      <h3 class="fp-card-title">Métriques Mobile</h3>
      <span class="fp-badge fp-badge--ghost">Cliquez sur une métrique pour les détails</span>
    </div>
    ${cwv ? `<div class="fp-grid" style="grid-template-columns:repeat(4,1fr);gap:12px">
      ${['lcp','cls','inp','ttfb'].map(key=>{
        const metricNames={lcp:'LCP',cls:'CLS',inp:'INP',ttfb:'TTFB'};
        const units={lcp:'ms',cls:'',inp:'ms',ttfb:'ms'};
        // BUG-W1-004: null-safe inline CWV card
        const val = (cwv && Number.isFinite(cwv[key])) ? cwv[key] : null;
        const cls2 = val !== null ? cwvBadgeClass(key,val) : 'needs-improvement';
        const color = {good:'#10b981','needs-improvement':'#f59e0b',poor:'#ef4444'}[cls2] || 'var(--fp-text-faint)';
        const display = val === null ? '—' : key==='cls' ? val.toFixed(3) : Math.round(val).toLocaleString('fr-FR');
        return `<div class="fp-cwv-card" style="cursor:pointer" onclick="navigateSub('${key}')">
          <div style="font-size:11px;font-weight:700;letter-spacing:1px;color:var(--fp-text-faint);margin-bottom:8px">${metricNames[key]}</div>
          <div style="font-size:32px;font-weight:800;color:${color};margin-bottom:4px">${display}<span style="font-size:14px;color:var(--fp-text-muted)">${val !== null ? units[key] : ''}</span></div>
          <span class="fp-cwv-badge fp-cwv-badge--${cls2}" style="font-size:11px">${val !== null ? cwvBadgeLabel(cls2) : 'Indisponible'}</span>
          <div style="font-size:10px;color:var(--fp-text-faint);margin-top:8px">→ Voir détails</div>
        </div>`;
      }).join('')}
    </div>` : ''}

    ${cwv ? `<div style="margin-top:16px">${renderCWVCards(cwv)}</div>` : ''}
  </div>

  <!-- Mobile vs Desktop comparison preview -->
  <div class="fp-card">
    <div class="fp-card-header" style="margin-bottom:16px">
      <h3 class="fp-card-title">Mobile vs Desktop</h3>
      <button class="fp-btn fp-btn-primary" onclick="navigateSub('compare')" style="font-size:12px">Comparaison complète →</button>
    </div>
    <div class="fp-grid" style="grid-template-columns:1fr 1fr;gap:16px">
      ${['mobile','desktop'].map(strat=>{
        const d = psi[strat];
        return `<div>
          <div style="font-size:12px;font-weight:700;margin-bottom:12px;color:var(--fp-text-muted);text-transform:uppercase;letter-spacing:1px">${strat}</div>
          ${d && d.cwv ? ['lcp','cls','inp','ttfb'].map(key=>{
            // BUG-W1-004: null-safe comparison preview
            const val=(d.cwv && Number.isFinite(d.cwv[key])) ? d.cwv[key] : null;
            const cls2=val!==null?cwvBadgeClass(key,val):'needs-improvement';
            const color={good:'#10b981','needs-improvement':'#f59e0b',poor:'#ef4444'}[cls2]||'var(--fp-text-faint)';
            const display=val===null?'N/A':key==='cls'?val.toFixed(3):Math.round(val)+'ms';
            return `<div style="display:flex;align-items:center;justify-content:space-between;padding:8px 0;border-bottom:1px solid var(--fp-border)">
              <span style="font-size:12px;font-weight:700;color:var(--fp-text-faint)">${key.toUpperCase()}</span>
              <span style="font-size:14px;font-weight:700;color:${color}">${display}</span>
            </div>`;
          }).join('') : '<p style="color:var(--fp-text-faint);font-size:13px">Non disponible</p>'}
        </div>`;
      }).join('')}
    </div>
  </div>
  `}`;
}

function renderCWVMetricDetail(metric, mobile, desktop) {
  const names = {lcp:'Largest Contentful Paint',cls:'Cumulative Layout Shift',inp:'Interaction to Next Paint',ttfb:'Time to First Byte'};
  const guides = {
    lcp: { desc:"Le LCP mesure le temps de chargement de l\'élément visible le plus grand.", good:'< 2,5s', needs:'2,5s – 4s', poor:'> 4s', tips:['Préchargez l\'image hero avec <link rel="preload">','Utilisez un CDN pour servir les ressources statiques','Optimisez et compressez les images (WebP)','Réduisez le temps de réponse serveur (TTFB < 600ms)','Évitez les ressources bloquantes au-dessus du fold'] },
    cls: { desc:"Le CLS mesure la stabilité visuelle de la page.", good:'< 0,1', needs:'0,1 – 0,25', poor:'> 0,25', tips:['Définissez toujours les dimensions width/height des images','Évitez l\'injection de contenu au-dessus du contenu existant','Préchargez les polices avec font-display: swap','Réservez l\'espace pour les publicités et embeds','Évitez les animations CSS qui déplacent le contenu'] },
    inp: { desc:"L\'INP mesure la réactivité aux interactions utilisateur.", good:'< 200ms', needs:'200ms – 500ms', poor:'> 500ms', tips:['Réduisez le JavaScript exécuté sur le thread principal','Utilisez Web Workers pour les tâches lourdes','Déférez le JS non critique avec defer ou lazy loading','Optimisez les event handlers (debounce, throttle)','Supprimez les scripts tiers non essentiels'] },
    ttfb: { desc:"Le TTFB mesure le temps avant le premier octet de réponse serveur.", good:'< 800ms', needs:'800ms – 1800ms', poor:'> 1800ms', tips:['Utilisez un CDN avec edge caching','Optimisez les requêtes DB (index, cache)','Activez la compression gzip/brotli côté serveur','Utilisez HTTP/2 ou HTTP/3','Minimisez les redirections (chaque redirect = +100-300ms)'] },
  };
  const g = guides[metric] || {};
  // BUG-W1-005: null-safe — show "Indisponible" instead of 0ms for absent CWV metrics
  const mval = (mobile && mobile.cwv && Number.isFinite(mobile.cwv[metric])) ? mobile.cwv[metric] : null;
  const dval = (desktop && desktop.cwv && Number.isFinite(desktop.cwv[metric])) ? desktop.cwv[metric] : null;
  const mcls = mval !== null ? cwvBadgeClass(metric, mval) : 'needs-improvement';
  const dcls = dval !== null ? cwvBadgeClass(metric, dval) : 'needs-improvement';

  return `
  <div class="fp-section-header">
    <div>
      <h1 class="fp-section-title">${metric.toUpperCase()} — ${escHtml(names[metric]||metric)}</h1>
      <p class="fp-section-sub">${escHtml(g.desc||'')}</p>
    </div>
    <button class="fp-btn fp-btn-primary" onclick="navigateSub(null)">← Core Web Vitals</button>
  </div>

  <!-- Values -->
  <div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:12px">
    <div class="fp-card" style="text-align:center">
      <div style="font-size:11px;font-weight:700;color:var(--fp-text-faint);letter-spacing:1px;margin-bottom:12px">MOBILE</div>
      ${renderPSIRing(mcls==='good'?95:mcls==='needs-improvement'?60:25,100)}
      <div style="font-size:22px;font-weight:800;color:${{good:'#10b981','needs-improvement':'#f59e0b',poor:'#ef4444'}[mcls]};margin:8px 0;white-space:nowrap">
        ${mval===null ? '<span style="color:var(--fp-text-faint);font-size:16px">Indisponible</span>' : metric==='cls'?mval.toFixed(3):Math.round(mval)+'ms'}
      </div>
      <span class="fp-cwv-badge fp-cwv-badge--${mcls}">${cwvBadgeLabel(mcls)}</span>
    </div>
    <div class="fp-card" style="text-align:center">
      <div style="font-size:11px;font-weight:700;color:var(--fp-text-faint);letter-spacing:1px;margin-bottom:12px">DESKTOP</div>
      ${renderPSIRing(dcls==='good'?95:dcls==='needs-improvement'?60:25,100)}
      <div style="font-size:22px;font-weight:800;color:${{good:'#10b981','needs-improvement':'#f59e0b',poor:'#ef4444'}[dcls]};margin:8px 0;white-space:nowrap">
        ${dval===null ? '<span style="color:var(--fp-text-faint);font-size:16px">Indisponible</span>' : metric==='cls'?dval.toFixed(3):Math.round(dval)+'ms'}
      </div>
      <span class="fp-cwv-badge fp-cwv-badge--${dcls}">${cwvBadgeLabel(dcls)}</span>
    </div>
  </div>
  <div class="fp-card" style="margin-bottom:20px">
    <div style="font-size:12px;font-weight:700;margin-bottom:12px">Seuils de référence</div>
    <div style="display:flex;flex-direction:row;flex-wrap:wrap;gap:10px">
      ${[{cls:'good',val:g.good||''},{cls:'needs-improvement',val:g.needs||''},{cls:'poor',val:g.poor||''}].map(t=>`
      <div style="display:flex;align-items:center;gap:8px">
        <span class="fp-cwv-badge fp-cwv-badge--${t.cls}" style="font-size:10px">${cwvBadgeLabel(t.cls)}</span>
        <span style="font-size:13px;font-family:'JetBrains Mono',monospace;color:var(--fp-text)">${t.val}</span>
      </div>`).join('')}
    </div>
  </div>

  <!-- Tips -->
  <div class="fp-card">
    <div class="fp-card-header" style="margin-bottom:16px">
      <h3 class="fp-card-title">Recommandations d\'optimisation</h3>
      <span class="fp-badge fp-badge--accent">${(g.tips||[]).length} conseils</span>
    </div>
    <div class="fp-flex-col" style="gap:8px">
      ${(g.tips||[]).map((tip,i)=>`<div style="display:flex;align-items:flex-start;gap:12px;padding:12px;background:var(--fp-bg-body);border-radius:10px">
        <div style="width:24px;height:24px;border-radius:6px;background:var(--fp-accent);color:white;display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:700;flex-shrink:0">${i+1}</div>
        <span style="font-size:13px;line-height:1.6">${escHtml(tip)}</span>
      </div>`).join('')}
    </div>
  </div>`;
}

function renderCWVComparison(mobile, desktop) {
  return `
  <div class="fp-section-header">
    <h1 class="fp-section-title">Comparaison Mobile vs Desktop</h1>
    <button class="fp-btn fp-btn-primary" onclick="navigateSub(null)">← Vue d\'ensemble</button>
  </div>
  ${!mobile && !desktop ? `<div class="fp-card" style="text-align:center;padding:40px"><p>Lancez une analyse pour comparer les données.</p></div>` : `
  <div class="fp-card">
    <table class="fp-table" style="width:100%">
      <thead><tr>
        <th>Métrique</th>
        <th>Mobile</th>
        <th>Desktop</th>
        <th>Différence</th>
        <th>Statut Mobile</th>
      </tr></thead>
      <tbody>
        ${['lcp','cls','inp','ttfb','fcp','tbt','speedIndex'].map(key=>{
          const labels={lcp:'LCP',cls:'CLS',inp:'INP',ttfb:'TTFB',fcp:'FCP',tbt:'TBT',speedIndex:'Speed Index'};
          // BUG-W1-006: null-safe — show N/A instead of 0ms for absent CWV metrics
          const mv = (mobile?.cwv && Number.isFinite(mobile.cwv[key])) ? mobile.cwv[key] : null;
          const dv = (desktop?.cwv && Number.isFinite(desktop.cwv[key])) ? desktop.cwv[key] : null;
          const diff = (mv !== null && dv !== null) ? mv - dv : null;
          const mcls = mv !== null ? cwvBadgeClass(key==='speedIndex'?'si':key, mv) : 'needs-improvement';
          const fmt = v => v === null ? '<span style="color:var(--fp-text-faint)">N/A</span>' : key==='cls' ? v.toFixed(3) : Math.round(v).toLocaleString('fr-FR')+'ms';
          return `<tr>
            <td style="font-weight:600">${labels[key]||key}</td>
            <td style="font-weight:700;color:${{good:'#10b981','needs-improvement':'#f59e0b',poor:'#ef4444'}[mcls]}">${fmt(mv)}</td>
            <td>${fmt(dv)}</td>
            <td style="color:${diff===null?'var(--fp-text-faint)':diff>0?'#ef4444':'#10b981'}">${diff===null?'—':((diff>0?'+':'')+fmt(diff))}</td>
            <td><span class="fp-cwv-badge fp-cwv-badge--${mcls}">${cwvBadgeLabel(mcls)}</span></td>
          </tr>`;
        }).join('')}
      </tbody>
    </table>
  </div>`}`;
}

