function renderTechnicalAudit() {
  // BUG-W1-010: trigger audit poller check on every render of this page
  if (window._fpStartAuditPoll) window._fpStartAuditPoll();

  const sub = STATE.subRoute;
  const psi = window.FP_DATA && window.FP_DATA.pagespeed;
  const mobile = psi && psi.mobile;
  const opps = (mobile && mobile.opportunities) || [];

  const renderBlockingOpps = opps.filter(o=>o.category==='render-blocking');
  const jsOpps  = opps.filter(o=>o.category==='unused-js');
  const cssOpps = opps.filter(o=>o.category==='unused-css');
  const imgOpps = opps.filter(o=>o.category==='images');

  if (sub === 'render-blocking') {
    return renderTechSection('Ressources bloquantes','⚡',renderBlockingOpps,'Ces ressources bloquent l\'affichage de la page. Utilisez defer/async pour les scripts et media queries pour les CSS.');
  }
  if (sub === 'js-css') {
    return renderTechSection('JavaScript & CSS non utilisés','📦',[...jsOpps,...cssOpps],'Du code JS et CSS est chargé mais jamais exécuté. Utilisez tree-shaking et du CSS critique inline.');
  }
  if (sub === 'images') {
    return renderTechSection('Optimisation images','🖼',imgOpps,'Optimisez les images avec le format WebP, les dimensions adaptées et le lazy loading.');
  }
  if (sub === 'accessibility') {
    return renderTechnicalAccessibility(mobile);
  }
  if (sub === 'seo') {
    return renderTechnicalSEO(mobile);
  }
  if (sub === 'ai') {
    return renderTechnicalAIAudit();
  }

  // Command Center overview
  const totalSavingsMs = opps.reduce((s,o)=>s+(o.savingsMs||0),0);
  // BUG-W1-008: use real STATE.audits counts — passedAudits/totalAudits not in PSI response
  const _techSummary = buildTechnicalAuditSummary(STATE.audits||[], mobile);
  const passRate = safePercent(_techSummary.completedAudits, _techSummary.totalAudits || 1);

  return `
  <div class="fp-section-header">
    <div>
      <h1 class="fp-section-title">Audit Technique</h1>
      <p class="fp-section-sub">Analyse complète des problèmes techniques · Recommandations d\'optimisation</p>
    </div>
    <div class="fp-section-actions">
      ${psi ? `<button class="fp-btn fp-btn-primary" onclick="navigate('performance')">← Performance</button>` : ''}
      <button class="fp-btn fp-btn-primary" onclick="navigateSub('ai')">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 2a2 2 0 0 1 2 2c0 .74-.4 1.39-1 1.73V7h1a7 7 0 0 1 7 7h1a1 1 0 0 1 0 2h-1v1a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-1H2a1 1 0 0 1 0-2h1a7 7 0 0 1 7-7h1V5.73c-.6-.34-1-.99-1-1.73a2 2 0 0 1 2-2z"/></svg>
        IA Audit
      </button>
    </div>
  </div>

  ${!psi ? `
  <div class="fp-card" style="text-align:center;padding:48px">
    <div style="font-size:48px;margin-bottom:16px">🔍</div>
    <h3>Audit technique requis</h3>
    <p style="color:var(--fp-text-muted);margin-bottom:20px">Analysez un site depuis Performance pour obtenir l\'audit technique complet.</p>
    <button class="fp-btn fp-btn-primary" onclick="navigate('performance')">Lancer une analyse</button>
  </div>` : `

  <!-- KPI summary -->
  <div class="fp-kpi-grid" style="margin-bottom:20px">
    <div class="fp-kpi-card">
      <div class="fp-kpi-label">Audits terminés</div>
      <div class="fp-kpi-value" style="color:#10b981">${_techSummary.completedAudits}</div>
      <div class="fp-kpi-sub">${passRate}% · ${_techSummary.processingAudits ? `<span style="color:#f59e0b">${_techSummary.processingAudits} en cours</span>` : 'aucun en cours'}</div>
    </div>
    <div class="fp-kpi-card">
      <div class="fp-kpi-label">Opportunités</div>
      <div class="fp-kpi-value" style="color:#f59e0b">${opps.length}</div>
      <div class="fp-kpi-sub">amélioration possible</div>
    </div>
    <div class="fp-kpi-card">
      <div class="fp-kpi-label">Temps économisable</div>
      <div class="fp-kpi-value" style="color:var(--fp-accent)">${(totalSavingsMs/1000).toFixed(1)}s</div>
      <div class="fp-kpi-sub">sur le chargement total</div>
    </div>
    <div class="fp-kpi-card">
      <div class="fp-kpi-label">Problèmes critiques</div>
      <div class="fp-kpi-value" style="color:#ef4444">${(mobile.criticalIssues||[]).length}</div>
      <div class="fp-kpi-sub">priorité absolue</div>
    </div>
  </div>

  <!-- Category grid -->
  <div class="fp-grid" style="grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:20px">
    ${[
      {sub:'render-blocking',icon:'⚡',label:'Ressources bloquantes',count:renderBlockingOpps.length,color:'#ef4444',savings:renderBlockingOpps.reduce((s,o)=>s+(o.savingsMs||0),0)},
      {sub:'js-css',icon:'📦',label:'JS & CSS non utilisés',count:jsOpps.length+cssOpps.length,color:'#f59e0b',savings:(jsOpps.concat(cssOpps)).reduce((s,o)=>s+(o.savingsMs||0),0)},
      {sub:'images',icon:'🖼',label:'Optimisation images',count:imgOpps.length,color:'#06b6d4',savings:imgOpps.reduce((s,o)=>s+(o.savingsBytes||0)/1024,0)},
      {sub:'accessibility',icon:'♿',label:'Accessibilité',count:_techSummary.accessibilityIssues.length,color:'#8b5cf6',savings:0},
      {sub:'seo',icon:'🔍',label:'SEO Technique',count:_techSummary.technicalSeoIssues.length,color:'#10b981',savings:0},
      {sub:'ai',icon:'🤖',label:'IA Audit Complet',count:null,color:'var(--fp-accent)',savings:0},
    ].map(c=>`<div class="fp-card" style="cursor:pointer;transition:border-color 0.15s" onclick="navigateSub('${c.sub}')" onmouseenter="this.style.borderColor='${c.color}'" onmouseleave="this.style.borderColor=''">
      <div style="font-size:28px;margin-bottom:8px">${c.icon}</div>
      <div style="font-size:14px;font-weight:600;margin-bottom:4px">${c.label}</div>
      <div style="font-size:12px;color:var(--fp-text-faint)">
        ${c.count!==null ? `<span style="color:${c.color};font-weight:700">${c.count}</span> problème${c.count>1?'s':''}` : 'Analyse complète →'}
        ${c.savings>0 ? ` · <span style="color:#10b981">${c.sub==='images'?Math.round(c.savings)+'KB':((c.savings/1000).toFixed(1))+'s'} économisables</span>` : ''}
      </div>
    </div>`).join('')}
  </div>

  <!-- Critical issues -->
  ${(mobile.criticalIssues||[]).length ? `
  <div class="fp-card">
    <div class="fp-card-header" style="margin-bottom:16px">
      <h3 class="fp-card-title">🚨 Problèmes critiques</h3>
      <span class="fp-badge" style="background:rgba(239,68,68,0.12);color:#ef4444">${mobile.criticalIssues.length} critique${mobile.criticalIssues.length>1?'s':''}</span>
    </div>
    <div class="fp-flex-col" style="gap:8px">
      ${mobile.criticalIssues.map(issue=>`<div style="display:flex;align-items:flex-start;gap:10px;padding:12px;background:rgba(239,68,68,0.06);border:1px solid rgba(239,68,68,0.2);border-radius:8px">
        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#ef4444" stroke-width="2" style="flex-shrink:0;margin-top:1px"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>
        <span style="font-size:13px">${escHtml(issue)}</span>
      </div>`).join('')}
    </div>
  </div>` : ''}
  `}`;
}

