// ── PSI helper functions for UI ───────────────────────────────────────────────

function fpMarkdown(text) {
  if (!text) return '';
  return text
    .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
    .replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>')
    .replace(/\*(.+?)\*/g,'<em>$1</em>')
    .replace(/`(.+?)`/g,'<code style="background:rgba(0,0,0,0.2);padding:2px 6px;border-radius:4px;font-family:\'JetBrains Mono\',monospace;font-size:0.9em">$1</code>')
    .replace(/^## (.+)$/gm,'<h3 style="font-size:16px;font-weight:700;margin:20px 0 8px;color:var(--fp-text)">$1</h3>')
    .replace(/^# (.+)$/gm,'<h2 style="font-size:18px;font-weight:800;margin:24px 0 10px;color:var(--fp-text)">$1</h2>')
    .replace(/^- (.+)$/gm,'<div style="display:flex;gap:8px;margin:4px 0;padding-left:4px"><span style="color:var(--fp-accent);flex-shrink:0">•</span><span>$1</span></div>')
    .replace(/^\d+\. (.+)$/gm,'<div style="display:flex;gap:8px;margin:6px 0"><span style="font-weight:700;color:var(--fp-accent);flex-shrink:0">›</span><span>$1</span></div>')
    .replace(/\n\n/g,'<br/><br/>')
    .replace(/\n/g,'<br/>');
}

async function fpAnalyzePSI() {
  const input = document.getElementById('fp-psi-url-input');
  const btn = document.getElementById('fp-psi-analyze-btn');
  const rawUrl = input && input.value.trim();
  if (!rawUrl) { showToast && showToast('error','Entrez une URL valide'); return; }
  // BUG-W1-001: validate URL with new URL() — reject plain text, javascript:, ftp:, etc.
  let _parsedUrl;
  try { _parsedUrl = new URL(rawUrl.startsWith('http') ? rawUrl : 'https://' + rawUrl); } catch(_) { _parsedUrl = null; }
  if (!_parsedUrl || !['http:','https:'].includes(_parsedUrl.protocol) || !_parsedUrl.hostname || _parsedUrl.hostname.split('.').filter(Boolean).length < 2) {
    if (input && input.reportValidity) input.reportValidity();
    showToast && showToast('error', 'Veuillez saisir une URL valide (ex: https://example.com)');
    return;
  }
  // P1.3: anti-double-click guard
  if (window._fpPsiAnalyzing) return;

  const url = _parsedUrl.href;
  if (btn) { btn.disabled = true; btn.textContent = 'Analyse en cours…'; }
  window._fpPsiAnalyzing = true;
  render();

  try {
    // BUG-W1-V32-001+002: Always use raw fetch — FP_PAGESPEED_API.analyze() stores
    // raw data (mobile.metrics.*) without normalizing to mobile.cwv.*, and returns
    // null on error making status codes (409/402/4xx) invisible to the caller.
    const _psiBase = window.__FP_BACKEND_URL || '';
    const resp = await fetch(_psiBase + '/api/pagespeed/analyze', _fpSessionFetchOptions({
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ url: url, force: true }),
    }));
    if (resp.ok) {
      const raw = await resp.json();
      if (raw && (raw.mobile || raw.desktop)) {
        setPageSpeedResult(raw);
        showToast && showToast('success', 'Analyse terminée !');
      } else {
        showToast && showToast('error', 'Réponse invalide du serveur');
      }
    } else if (resp.status === 409) {
      showToast && showToast('warning', 'Une analyse est déjà en cours pour cette URL. Réessayez dans quelques instants.');
    } else if (resp.status === 402) {
      showToast && showToast('error', 'Crédits insuffisants pour lancer une analyse PageSpeed');
    } else if (resp.status === 401) {
      showToast && showToast('error', 'Session expirée — veuillez vous reconnecter');
    } else if (resp.status === 400) {
      showToast && showToast('error', 'URL invalide ou non accessible publiquement');
    } else if (resp.status === 429) {
      showToast && showToast('warning', 'Trop de requêtes — réessayez dans quelques instants');
    } else {
      showToast && showToast('error', 'Erreur lors de l\'analyse — URL accessible publiquement ?');
    }
  } catch(_e) {
    showToast && showToast('error', 'Erreur réseau lors de l\'analyse PageSpeed');
  } finally {
    window._fpPsiAnalyzing = false;
    if (btn) { btn.disabled = false; btn.textContent = 'Analyser'; }
    render();
  }
}

async function fpGetPSIAIReco() {
  const btn = document.getElementById('fp-psi-ai-btn');
  if (btn) { btn.disabled = true; btn.textContent = 'Génération en cours…'; }

  const psi = window.FP_DATA && window.FP_DATA.pagespeed;
  if (!psi) {
    showToast && showToast('warning', 'Lancez d\'abord une analyse PageSpeed pour obtenir des recommandations.');
    if (btn) { btn.disabled = false; btn.textContent = 'Générer les recommandations'; }
    return;
  }

  try {
    // ── Build a detailed, real prompt from actual PSI data ──────────────────
    const _mScore = psi.mobile && psi.mobile.score != null ? Math.round(psi.mobile.score <= 1 ? psi.mobile.score * 100 : psi.mobile.score) : null;
    const _dScore = psi.desktop && psi.desktop.score != null ? Math.round(psi.desktop.score <= 1 ? psi.desktop.score * 100 : psi.desktop.score) : null;
    const _cwv   = (psi.mobile && psi.mobile.cwv) || {};
    const _opps  = (psi.mobile && psi.mobile.opportunities) || [];
    const _diag  = (psi.mobile && psi.mobile.diagnostics) || [];
    const _metricFmt = (val, unit) => (val != null && isFinite(Number(val))) ? `${Math.round(Number(val))}${unit}` : 'N/A';
    const _sMobile  = _mScore  != null ? `${_mScore}/100`  : 'N/A';
    const _sDesktop = _dScore  != null ? `${_dScore}/100` : 'N/A';

    const _oppLines = _opps.slice(0, 10).map(o => {
      const savMs = o.savings_ms ? ` (économie estimée : ${Math.round(o.savings_ms)} ms)` : '';
      const savKb = o.savings_bytes ? ` (économie : ${Math.round(o.savings_bytes / 1024)} KB)` : '';
      return `- ${o.title || o.id}${savMs || savKb}`;
    }).join('\n');

    const _prompt = [
      `Voici les données PageSpeed Insights réelles pour le site **${psi.url}** :`,
      ``,
      `**Scores de performance :**`,
      `- Mobile : ${_sMobile}`,
      `- Desktop : ${_sDesktop}`,
      ``,
      `**Core Web Vitals (stratégie mobile) :**`,
      `- LCP (Largest Contentful Paint) : ${_metricFmt(_cwv.lcp, ' ms')}`,
      `- CLS (Cumulative Layout Shift) : ${_cwv.cls != null ? Number(_cwv.cls).toFixed(3) : 'N/A'}`,
      `- INP (Interaction to Next Paint) : ${_metricFmt(_cwv.inp, ' ms')}`,
      `- TTFB (Time to First Byte) : ${_metricFmt(_cwv.ttfb, ' ms')}`,
      `- FCP (First Contentful Paint) : ${_metricFmt(_cwv.fcp, ' ms')}`,
      `- TBT (Total Blocking Time) : ${_metricFmt(_cwv.tbt, ' ms')}`,
      ``,
      _opps.length ? `**Opportunités d'optimisation identifiées (${_opps.length}) :**\n${_oppLines}` : `**Aucune opportunité majeure détectée**`,
      ``,
      `Sur la base de ces données **réelles et précises**, génère un **plan d'optimisation complet et personnalisé** pour ce site. Pour chaque Core Web Vital hors des seuils recommandés (LCP > 2500ms, CLS > 0.1, INP > 200ms, TTFB > 800ms), explique la cause probable et les actions concrètes. Priorise par impact sur le score. Termine par un plan d'action en 3 phases : Quick Wins (< 1 semaine), Améliorations structurelles (1 mois), Refactoring long terme.`,
    ].join('\n');

    const _base = window.__FP_BACKEND_URL || '';
    const resp = await fetch(_base + '/api/ai/chat', _fpSessionFetchOptions({
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ message: _prompt, mode: 'performant' }),
    }));

    if (resp.ok) {
      const _result = await resp.json();
      const _reco = (_result && (_result.message || _result.response || _result.text || _result.content)) || '';
      if (_reco) {
        if (window.FP_DATA && window.FP_DATA.pagespeed) {
          window.FP_DATA.pagespeed.aiRecommendations = _reco;
          // Persist updated recommendations to localStorage
          try {
            var _saved = JSON.parse(localStorage.getItem('fp-psi-last') || '{}');
            if (_saved && _saved.data) {
              _saved.data.aiRecommendations = _reco;
              localStorage.setItem('fp-psi-last', JSON.stringify(_saved));
            }
          } catch(_) {}
        }
        showToast && showToast('success', 'Recommandations IA générées avec succès !');
        render();
      } else {
        showToast && showToast('error', 'L\'IA n\'a pas renvoyé de réponse — réessayez');
      }
    } else if (resp.status === 402) {
      showToast && showToast('error', 'Crédits IA insuffisants — upgradez votre plan');
    } else if (resp.status === 401) {
      showToast && showToast('error', 'Session expirée — veuillez vous reconnecter');
    } else {
      showToast && showToast('error', 'Erreur lors de la génération IA — réessayez dans quelques instants');
    }
  } catch(_e) {
    console.warn('[fpGetPSIAIReco]', _e);
    showToast && showToast('error', 'Erreur réseau — vérifiez votre connexion et réessayez');
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = 'Générer les recommandations'; }
  }
}

// ── Quick Wins "+ Mission" buttons — stable document-level delegation ─────────
// Registered at IIFE global scope so it works across all re-renders and
// sub-route changes. Uses data-attributes (never JSON.stringify in onclick attrs).
document.addEventListener('click', function(e) {
  var btn = e.target && e.target.closest && e.target.closest('.qw-mission-btn');
  if (!btn) return;
  if (btn.disabled) return;
  var title = btn.dataset.qwTitle || 'Mission Quick Win';
  var cat   = btn.dataset.qwCat   || 'Optimisation';
  var prio  = btn.dataset.qwPriority || 'medium';
  btn.disabled = true;
  btn.textContent = '…';
  Promise.resolve(window._fpMQ ? window._fpMQ(title, cat, prio) : null)
    .then(function() {
      btn.textContent = '✓ Créé';
      btn.style.color = '#22c55e';
      btn.style.fontWeight = '700';
      btn.style.border = '1px solid #22c55e40';
    })
    .catch(function() {
      btn.disabled = false;
      btn.textContent = '+ Mission';
    });
});

// ── Sidebar nav item clicks — global document delegation ────────────────────────
// Registered at IIFE global scope (NOT inside init()) so it fires correctly even
// when init() is paused at `await loadData()` or encounters an async error before
// bindGlobalEvents() is reached. This replaces the per-element binding that used
// to live inside bindGlobalEvents() and could silently miss clicks during load.
document.addEventListener('click', function _navDelegation(e) {
  var navEl = e.target && e.target.closest && e.target.closest('.fp-nav-item, .fp-nav-ai');
  if (!navEl || !navEl.dataset || !navEl.dataset.route) return;
  navigate(navEl.dataset.route);
  if (window.innerWidth <= 768) {
    var sb = document.getElementById('fp-sidebar');
    var ov = document.getElementById('fp-mobile-overlay');
    var hb = document.getElementById('fp-hamburger');
    if (sb) sb.classList.remove('mobile-open');
    if (ov) ov.classList.remove('show');
    if (hb) { hb.classList.remove('open'); hb.setAttribute('aria-expanded', 'false'); }
  }
});

// ── Wire analyze button after render (delegated — avoids function redeclaration hoisting conflict) ──
document.addEventListener('click', function(e) {
  if (e.target && e.target.closest && e.target.closest('#fp-psi-analyze-btn')) fpAnalyzePSI();
});
document.addEventListener('keydown', function(e) {
  if (e.target && e.target.id === 'fp-psi-url-input' && e.key === 'Enter') fpAnalyzePSI();
});

// ── Activity panel button + filter delegation ─────────────────────────────────
// Registered at IIFE global scope (not inside init()) so it works even when
// init() encounters an async error before bindActivityPanel() is reached.
document.addEventListener('click', function _activityDelegation(e) {
  // Toggle panel open/close via header button
  if (e.target.closest('#fp-activity-btn')) {
    e.stopPropagation();
    if (STATE.activityPanelOpen) closeActivityPanel();
    else openActivityPanel();
    return;
  }
  // ACT-001: filter button inside the activity panel
  const filterBtn = e.target.closest('.fp-activity-filter');
  if (filterBtn && filterBtn.closest('#fp-activity-filters')) {
    const filters = document.getElementById('fp-activity-filters');
    if (!filters) return;
    filters.querySelectorAll('.fp-activity-filter').forEach(function(b) { b.classList.remove('active'); });
    filterBtn.classList.add('active');
    var nextFilter = filterBtn.dataset.filter || 'all';
    STATE.activityFilter = nextFilter;
    if (nextFilter === 'all') {
      STATE.activityFilteredEvents = null;
      STATE.activityFilterLoading = false;
      renderActivityList();
    } else {
      STATE.activityFilteredEvents = null;
      STATE.activityFilterLoading = true;
      renderActivityList();
      apiFetch('/api/activity?type=' + encodeURIComponent(nextFilter) + '&limit=50')
        .then(function(res) { STATE.activityFilteredEvents = Array.isArray(res) ? res : []; })
        .catch(function() { STATE.activityFilteredEvents = []; })
        .finally(function() { STATE.activityFilterLoading = false; renderActivityList(); });
    }
  }
});

// ── BUG-W1-V32-005 — Audit polling controller ────────────────────────────────
// Replaces the old initAuditPoller IIFE. Key fixes:
// • pollAudits() fetches FIRST, then decides — never uses stale snapshot to stop early
// • startAuditPolling(id) tracks specific audit ids; stops only when ALL tracked ids resolve
// • in-flight guard prevents overlapping GETs when one takes > 7s
// • global scope — not page-dependent; continues across navigations
// • bootstrap on load covers audits already processing before page render
var auditPolling = {
  timer:          null,
  running:        false,
  inFlight:       false,
  intervalMs:     7000,
  trackedAuditIds: new Set(),
};

function stopAuditPolling() {
  if (auditPolling.timer) clearInterval(auditPolling.timer);
  auditPolling.timer   = null;
  auditPolling.running = false;
  auditPolling.trackedAuditIds.clear();
}

async function pollAudits() {
  if (auditPolling.inFlight) return;
  auditPolling.inFlight = true;
  try {
    var fresh = await apiFetch('/api/audits', { force: true, backgroundPoll: true });
    if (!Array.isArray(fresh)) return;
    var prev = Array.isArray(STATE && STATE.audits) ? STATE.audits : [];
    var changed = fresh.some(function(a) {
      var old = prev.find(function(o) { return o.id === a.id; });
      return !old || old.status !== a.status;
    });
    STATE.audits = fresh.map(function(a) {
      return Object.assign({}, a, { pinned: !!(STATE.pinned && STATE.pinned['audit_'+a.id]) });
    });
    if (changed) render();
    // Stop only when ALL explicitly tracked audits have left processing state
    if (auditPolling.trackedAuditIds.size > 0) {
      var trackedStillProcessing = fresh.some(function(a) {
        return auditPolling.trackedAuditIds.has(a.id) && a.status === 'processing';
      });
      if (!trackedStillProcessing) stopAuditPolling();
    } else {
      // No tracked ids (legacy path) — stop when no audits are processing at all
      var anyProcessing = fresh.some(function(a) { return a.status === 'processing'; });
      if (!anyProcessing) stopAuditPolling();
    }
  } catch(_) {
    // Network error — do not stop; will retry on next interval
  } finally {
    auditPolling.inFlight = false;
  }
}

function startAuditPolling(auditId) {
  if (auditId) auditPolling.trackedAuditIds.add(String(auditId));
  if (auditPolling.running) return;
  auditPolling.running = true;
  pollAudits(); // immediate first fetch — do not wait for first interval tick
  auditPolling.timer = setInterval(pollAudits, auditPolling.intervalMs);
}

// Backward-compat shim — renderTechnicalAudit still calls window._fpStartAuditPoll
window._fpStartAuditPoll = function() {
  var list = Array.isArray(STATE && STATE.audits) ? STATE.audits : [];
  if (list.some(function(a) { return a.status === 'processing'; }) && !auditPolling.running) {
    startAuditPolling();
  }
};

// Bootstrap: cover audits already processing when the page loads/reloads
setTimeout(function() {
  var list = Array.isArray(STATE && STATE.audits) ? STATE.audits : [];
  if (list.some(function(a) { return a.status === 'processing'; })) startAuditPolling();
}, 1500);

// ─────────────────────────────────────────────────────────────────────────────
// AI CHAT PANEL — Side assistant
// ─────────────────────────────────────────────────────────────────────────────

(function initAIChatPanel() {
  function openPanel() {
    const panel = document.getElementById('fp-ai-chat-panel');
    const overlay = document.getElementById('fp-ai-chat-overlay');
    if (!panel || !overlay) return;
    panel.hidden = false;
    overlay.hidden = false;
    overlay.removeAttribute('aria-hidden');
    document.body.style.overflow = '';
    setTimeout(() => {
      const inp = document.getElementById('fp-ai-chat-input');
      if (inp) inp.focus();
    }, 300);
  }

  function closePanel() {
    const panel = document.getElementById('fp-ai-chat-panel');
    const overlay = document.getElementById('fp-ai-chat-overlay');
    if (panel) panel.hidden = true;
    if (overlay) { overlay.hidden = true; overlay.setAttribute('aria-hidden','true'); }
  }

  function appendMessage(role, content, streaming) {
    const container = document.getElementById('fp-ai-chat-messages');
    if (!container) return null;
    // Hide welcome on first message
    const welcome = container.querySelector('.fp-ai-chat-welcome');
    if (welcome) welcome.style.display = 'none';

    const id = 'fp-ai-msg-' + Date.now();
    const initials = role === 'user' ? 'Vous' : 'IA';
    const div = document.createElement('div');
    div.className = `fp-ai-msg fp-ai-msg--${role}`;
    div.id = id;
    const aiAvatarSvg = `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="display:block"><path d="M12 2a2 2 0 0 1 2 2c0 .74-.4 1.39-1 1.73V7h1a7 7 0 0 1 7 7h1a1 1 0 0 1 0 2h-1v1a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-1H2a1 1 0 0 1 0-2h1a7 7 0 0 1 7-7h1V5.73c-.6-.34-1-.99-1-1.73a2 2 0 0 1 2-2z"/><circle cx="9" cy="14" r="1" fill="white" stroke="none"/><circle cx="15" cy="14" r="1" fill="white" stroke="none"/></svg>`;
    div.innerHTML = `
      <div class="fp-ai-msg-avatar" style="display:flex;align-items:center;justify-content:center">${role==='user'?'V':aiAvatarSvg}</div>
      <div class="fp-ai-msg-bubble">${fpMarkdown(content)}</div>`;
    container.appendChild(div);
    container.scrollTop = container.scrollHeight;
    return id;
  }

  function updateMessage(id, content, done) {
    const el = document.getElementById(id);
    if (!el) return;
    const bubble = el.querySelector('.fp-ai-msg-bubble');
    if (bubble) bubble.innerHTML = fpMarkdown(content);
    const container = document.getElementById('fp-ai-chat-messages');
    if (container) container.scrollTop = container.scrollHeight;
  }

  function setTyping(show) {
    const el = document.getElementById('fp-ai-chat-typing');
    if (el) el.hidden = !show;
  }

  function setSendEnabled(enabled) {
    const btn = document.getElementById('fp-ai-chat-send');
    if (btn) btn.disabled = !enabled;
  }

  function clearConversation() {
    const container = document.getElementById('fp-ai-chat-messages');
    if (!container) return;
    container.innerHTML = `<div class="fp-ai-chat-welcome">
      <div class="fp-ai-chat-welcome-icon">
        <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M12 2a2 2 0 0 1 2 2c0 .74-.4 1.39-1 1.73V7h1a7 7 0 0 1 7 7h1a1 1 0 0 1 0 2h-1v1a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-1H2a1 1 0 0 1 0-2h1a7 7 0 0 1 7-7h1V5.73c-.6-.34-1-.99-1-1.73a2 2 0 0 1 2-2z"/><circle cx="9" cy="14" r="1"/><circle cx="15" cy="14" r="1"/></svg>
      </div>
      <p><strong>Bonjour !</strong> Je suis votre assistant SEO FlowPoint.<br>Posez-moi des questions sur vos sites, performances, opportunités ou demandez-moi de générer un rapport.</p>
      <div class="fp-ai-chat-chips" id="fp-ai-chat-chips">
        <button class="fp-ai-quick-chip" data-msg="Quel est le score SEO moyen de mes sites ?">Score SEO moyen</button>
        <button class="fp-ai-quick-chip" data-msg="Quelles sont les 3 actions prioritaires à faire cette semaine ?">Actions prioritaires</button>
        <button class="fp-ai-quick-chip" data-msg="Analyse mes Core Web Vitals et donne-moi des recommandations.">Core Web Vitals</button>
        <button class="fp-ai-quick-chip" data-msg="Génère un résumé exécutif de la situation SEO.">Résumé exécutif</button>
      </div>
    </div>`;
    if (window.FP_AI_CHAT_API) window.FP_AI_CHAT_API.history = [];
    bindChips();
  }

  function _detectNavActions(text) {
    var t = (text || '').toLowerCase();
    var btns = [];
    if (t.includes('monitor') || t.includes('uptime') || t.includes('down'))
      btns.push({label:'Voir les monitors', route:'monitors', sub:null});
    if ((t.includes('audit') || t.includes('score seo') || t.includes('performance')) && !t.includes('audit log'))
      btns.push({label:'Audits SEO', route:'audits', sub:null});
    if (t.includes('concurrent') || t.includes('compétiteur') || t.includes('benchmark'))
      btns.push({label:'Concurrents', route:'competitor', sub:null});
    if (t.includes('local seo') || t.includes('google business') || t.includes('gbp') || t.includes('maps'))
      btns.push({label:'Local SEO', route:'local-seo', sub:null});
    if (t.includes('rapport') || t.includes('pdf') || t.includes('exporter'))
      btns.push({label:'Rapports', route:'reports', sub:null});
    if (t.includes('mission') || t.includes("plan d'action") || t.includes('priorit'))
      btns.push({label:'Missions', route:'missions', sub:null});
    if (t.includes('conversion') || t.includes('cro') || t.includes('friction') || t.includes('taux de conv'))
      btns.push({label:'Conversion', route:'conversion', sub:'ux-lab'});
    if (t.includes('alerte') || t.includes('incident'))
      btns.push({label:'Alertes', route:'alerts-center', sub:null});
    if (t.includes('facturation') || t.includes('abonnement') || t.includes('plan') || t.includes('upgrade'))
      btns.push({label:'Facturation', route:'billing', sub:null});
    if (t.includes('intégration') || t.includes('webhook') || t.includes('zapier') || t.includes('make'))
      btns.push({label:'Intégrations', route:'integrations', sub:'hub'});
    // Deduplicate and cap at 2 buttons max
    return btns.filter(function(b,i,a){ return a.findIndex(function(x){return x.route===b.route;})=== i; }).slice(0,2);
  }

  async function sendMessage(message) {
    if (!message || !message.trim()) return;
    const inp = document.getElementById('fp-ai-chat-input');
    if (inp) { inp.value = ''; inp.style.height = 'auto'; }
    setSendEnabled(false);

    appendMessage('user', message, false);
    setTyping(true);

    let msgId = null;
    let fullReply = '';

    try {
      if (window.FP_AI_CHAT_API) {
        await window.FP_AI_CHAT_API.sendMessage(message, {
          onDelta: function(delta, full) {
            // Keep typing dots until we have real content — avoids showing both
            // the empty cursor bubble AND the dots simultaneously (double indicator).
            if (!msgId) {
              setTyping(false);
              msgId = appendMessage('assistant', full, true); // create with first chunk
            } else {
              fullReply = full;
              updateMessage(msgId, fullReply, false);
            }
            fullReply = full;
          },
          onDone: function(full, _ai) {
            setTyping(false);
            if (msgId) updateMessage(msgId, full, true);
            else msgId = appendMessage('assistant', full, false);
            if (_ai && msgId) {
              var el = document.getElementById(msgId);
              if (el) {
                var providerLabel = { openai: 'GPT', anthropic: 'Claude', gemini: 'Gemini' }[_ai.provider] || _ai.provider;
                var badge = document.createElement('div');
                badge.className = 'fp-ai-provider-badge';
                badge.title = 'Modèle : ' + (_ai.model || _ai.provider);
                badge.style.cssText = 'margin-top:4px;font-size:10px;color:#6b7280;display:flex;align-items:center;gap:4px;padding-left:36px';
                badge.innerHTML = '<span style="display:inline-flex;align-items:center;gap:3px;background:rgba(37,99,235,0.07);border:1px solid rgba(37,99,235,0.15);border-radius:4px;padding:1px 6px;font-weight:600;letter-spacing:.02em">'
                  + '<svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" style="opacity:.7"><path d="M12 2a2 2 0 0 1 2 2v1a7 7 0 0 1 7 7v1a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-1a7 7 0 0 1 7-7V4a2 2 0 0 1 2-2z"/></svg>'
                  + providerLabel + '</span>';
                el.appendChild(badge);
                if (_ai.switchReason) {
                  if (typeof showToast === 'function') showToast('info', 'Basculement IA : ' + _ai.switchReason);
                }
              }
            }
            // Navigation action buttons based on AI response content
            if (msgId) {
              var _navBtns = _detectNavActions(full);
              if (_navBtns.length > 0) {
                var _el2 = document.getElementById(msgId);
                if (_el2) {
                  var _navBar = document.createElement('div');
                  _navBar.style.cssText = 'display:flex;gap:6px;flex-wrap:wrap;margin-top:8px;padding-left:36px';
                  _navBtns.forEach(function(nb) {
                    var _b = document.createElement('button');
                    _b.className = 'fp-btn fp-btn-primary fp-btn-sm';
                    _b.style.cssText = 'font-size:11px;padding:4px 12px;border-radius:20px;height:auto;line-height:1.5';
                    _b.textContent = nb.label + ' →';
                    _b.onclick = function() {
                      closePanel();
                      navigate(nb.route);
                      if (nb.sub) setTimeout(function(){ navigateSub(nb.sub); }, 80);
                    };
                    _navBar.appendChild(_b);
                  });
                  _el2.appendChild(_navBar);
                }
              }
            }
            // Refresh credit counter immediately after each reply — no page reload needed
            if (typeof loadAICredits === 'function') loadAICredits().catch(function(){});
            setSendEnabled(true);
          },
        });
      } else {
        setTyping(false);
        appendMessage('assistant', 'Assistant IA non disponible.', false);
        setSendEnabled(true);
      }
    } catch(e) {
      setTyping(false);
      appendMessage('assistant', 'Erreur de connexion — réessayez.', false);
      setSendEnabled(true);
    }
  }

  function bindChips() {
    document.querySelectorAll('.fp-ai-quick-chip').forEach(chip => {
      if (chip._bound) return;
      chip._bound = true;
      chip.addEventListener('click', () => sendMessage(chip.dataset.msg));
    });
  }

  function bindPanel() {
    // Open panel — topbar AI button
    const topbarAI = document.getElementById('topbar-ai');
    if (topbarAI) topbarAI.addEventListener('click', openPanel);

    // Close
    const closeBtn = document.getElementById('fp-ai-chat-close');
    if (closeBtn) closeBtn.addEventListener('click', closePanel);

    const overlay = document.getElementById('fp-ai-chat-overlay');
    if (overlay) overlay.addEventListener('click', closePanel);

    // Fullscreen → navigate to AI page
    const fullBtn = document.getElementById('fp-ai-chat-fullpage');
    if (fullBtn) fullBtn.addEventListener('click', () => { closePanel(); if (typeof navigate === 'function') navigate('ai'); });

    // Clear
    const clearBtn = document.getElementById('fp-ai-chat-clear');
    if (clearBtn) clearBtn.addEventListener('click', clearConversation);

    // Input auto-resize + send enable
    const input = document.getElementById('fp-ai-chat-input');
    const sendBtn = document.getElementById('fp-ai-chat-send');

    if (input) {
      input.addEventListener('input', () => {
        input.style.height = 'auto';
        input.style.height = Math.min(input.scrollHeight, 120) + 'px';
        if (sendBtn) sendBtn.disabled = !input.value.trim();
      });
      input.addEventListener('keydown', e => {
        if (e.key === 'Enter' && !e.shiftKey) {
          e.preventDefault();
          if (input.value.trim()) sendMessage(input.value.trim());
        }
      });
    }

    if (sendBtn) {
      sendBtn.addEventListener('click', () => {
        if (input && input.value.trim()) sendMessage(input.value.trim());
      });
    }

    // Chips
    bindChips();

    // Keyboard shortcut: Cmd/Ctrl+K or Cmd/Ctrl+I → toggle
    document.addEventListener('keydown', e => {
      if ((e.metaKey || e.ctrlKey) && e.key === 'i') {
        e.preventDefault();
        const panel = document.getElementById('fp-ai-chat-panel');
        if (panel && panel.hidden) openPanel(); else closePanel();
      }
    });
  }

  // Initialize after DOM ready
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', bindPanel);
  } else {
    bindPanel();
  }

  // Expose globally for context-aware calls from other pages
  window.fpOpenAIChat = openPanel;
  window.fpSendAIChat = sendMessage;
})();

// ═══════════════════════════════════════════════════════════════════════════════
// FP GITHUB API — client-side wrapper
// ═══════════════════════════════════════════════════════════════════════════════
window.FP_GITHUB_API = (() => {
  const base = (typeof window.FP_BASE_URL !== 'undefined' ? window.FP_BASE_URL : '') + '/api';

  async function _fetch(path, opts = {}) {
    const token = _fpCurrentSessionToken();
    const res = await fetch(`${base}${path}`, _fpSessionFetchOptions({
      ...opts,
      headers: { 'Content-Type': 'application/json', ...(opts.headers || {}) },
    }));
    if (!res.ok) { const e = await res.json().catch(() => ({})); throw new Error(e.error || `HTTP ${res.status}`); }
    return res.json();
  }

  return {
    getStatus: () => _fetch('/github/status'),
    getAuthUrl: () => _fetch('/github/auth'),
    getRepos: () => _fetch('/github/repos'),
    getCommits: (owner, repo, days = 30) => _fetch(`/github/commits/${owner}/${repo}?days=${days}`),
    getDeployments: (owner, repo) => _fetch(`/github/deployments/${owner}/${repo}`),
    analyzeRepo: (owner, repo) => _fetch(`/github/analysis/${owner}/${repo}`, { method: 'POST', body: '{}' }),
    getAnalysis: (owner, repo) => _fetch(`/github/analysis/${owner}/${repo}`),
    getIssues: (owner, repo) => _fetch(`/github/issues/${owner}/${repo}`),
    getHealth: (owner, repo) => _fetch(`/github/health/${owner}/${repo}`),
    getContributors: (owner, repo) => _fetch(`/github/contributors/${owner}/${repo}`),
    disconnect: () => _fetch('/github/disconnect', { method: 'POST', body: '{}' }),

    async connect() {
      try {
        const { url } = await _fetch('/github/auth');
        if (url) window.location.href = url;
        else showToast('error', 'URL OAuth GitHub introuvable');
      } catch(e) { showToast('error', 'Connexion GitHub impossible : ' + e.message); }
    },
  };
})();

// ═══════════════════════════════════════════════════════════════════════════════
// FEATURE GATE HELPER
// ═══════════════════════════════════════════════════════════════════════════════
window.fpGate = function fpGate(feature, requiredPlan = 'pro') {
  const me = window.STATE?.me;
  const plan = (me?.plan || 'standard').toLowerCase();
  const order = { standard: 0, pro: 1, ultra: 2, agency: 2 };
  const userLevel = order[plan] ?? 0;
  const reqLevel = order[requiredPlan.toLowerCase()] ?? 1;
  return userLevel >= reqLevel;
};

window.fpGateBlock = function fpGateBlock(feature, requiredPlan = 'pro', title, desc) {
  if (window.fpGate(feature, requiredPlan)) return '';
  const planLabel = requiredPlan === 'ultra' ? 'Ultra' : 'Pro';
  return `<div style="padding:14px 16px;background:rgba(37,99,235,0.06);border:1px solid rgba(37,99,235,0.2);border-radius:var(--fp-radius-lg);margin-bottom:20px;display:flex;align-items:center;gap:12px">
    <div style="font-size:22px">🔒</div>
    <div style="flex:1">
      <div style="font-size:13px;font-weight:700;color:var(--fp-text);margin-bottom:2px">${title || feature} — ${planLabel} requis</div>
      <div style="font-size:12px;color:var(--fp-text-muted)">${desc || ''}</div>
    </div>
    <button class="fp-btn fp-btn-primary fp-btn-sm" style="flex-shrink:0" onclick="(typeof FP_BILLING_API!=='undefined'?FP_BILLING_API.checkout('${requiredPlan}'):navigate('billing'))">Passer ${planLabel}</button>
  </div>`;
};

