// ═══════════════════════════════════════════════════════════════════════════════
// FP BETTERSTACK API — Real uptime monitoring client
// ═══════════════════════════════════════════════════════════════════════════════
window.FP_BETTERSTACK_API = {
  async loadAll() {
    try {
      const [config, stats, monitors, incidents, heartbeats, statusPages] = await Promise.allSettled([
        apiFetch('/api/betterstack/config').catch(() => null),
        apiFetch('/api/betterstack/stats').catch(() => null),
        apiFetch('/api/betterstack/monitors').catch(() => null),
        apiFetch('/api/betterstack/incidents').catch(() => null),
        apiFetch('/api/betterstack/heartbeats').catch(() => null),
        apiFetch('/api/betterstack/status-pages').catch(() => null),
      ]);
      const cfg = config.status === 'fulfilled' ? config.value : null;
      window.FP_DATA = window.FP_DATA || {};
      window.FP_DATA.betterstack = {
        configured: cfg?.configured ?? false,
        stats: stats.status === 'fulfilled' ? stats.value : null,
        monitors: monitors.status === 'fulfilled' ? (monitors.value?.data || []) : [],
        incidents: incidents.status === 'fulfilled' ? (incidents.value?.data || []) : [],
        heartbeats: heartbeats.status === 'fulfilled' ? (heartbeats.value?.data || []) : [],
        statusPages: statusPages.status === 'fulfilled' ? (statusPages.value?.data || []) : [],
        loadedAt: Date.now(),
      };
      return window.FP_DATA.betterstack;
    } catch(e) { console.warn('[FP_BETTERSTACK_API] loadAll error:', e); return null; }
  },
  async loadStats() {
    try { return await apiFetch('/api/betterstack/stats').catch(() => null); } catch(e) { return null; }
  },
  async loadMonitors() {
    try { const r = await apiFetch('/api/betterstack/monitors').catch(() => null); return r?.data || []; } catch(e) { return []; }
  },
  async loadIncidents(params) {
    try {
      const q = params ? '?' + new URLSearchParams(params).toString() : '';
      const r = await apiFetch('/api/betterstack/incidents' + q).catch(() => null);
      return r?.data || [];
    } catch(e) { return []; }
  },
  async loadHeartbeats() {
    try { const r = await apiFetch('/api/betterstack/heartbeats').catch(() => null); return r?.data || []; } catch(e) { return []; }
  },
  async loadStatusPages() {
    try { const r = await apiFetch('/api/betterstack/status-pages').catch(() => null); return r?.data || []; } catch(e) { return []; }
  },
  async createMonitor(payload) {
    try { return await apiFetch('/api/betterstack/monitors', { method: 'POST', body: JSON.stringify(payload) }); } catch(e) { return null; }
  },
  async updateMonitor(bsId, attrs) {
    try { return await apiFetch(`/api/betterstack/monitors/${bsId}`, { method: 'PATCH', body: JSON.stringify(attrs) }); } catch(e) { return null; }
  },
  async deleteMonitor(bsId) {
    try { return await apiFetch(`/api/betterstack/monitors/${bsId}`, { method: 'DELETE' }); } catch(e) { return null; }
  },
  async pauseMonitor(bsId) {
    try { return await apiFetch(`/api/betterstack/monitors/${bsId}/pause`, { method: 'POST', body: '{}' }); } catch(e) { return null; }
  },
  async resumeMonitor(bsId) {
    try { return await apiFetch(`/api/betterstack/monitors/${bsId}/resume`, { method: 'POST', body: '{}' }); } catch(e) { return null; }
  },
  async acknowledgeIncident(bsId) {
    try { return await apiFetch(`/api/betterstack/incidents/${bsId}/acknowledge`, { method: 'POST', body: '{}' }); } catch(e) { return null; }
  },
  async createHeartbeat(payload) {
    try { return await apiFetch('/api/betterstack/heartbeats', { method: 'POST', body: JSON.stringify(payload) }); } catch(e) { return null; }
  },
  async createStatusPage(payload) {
    try { return await apiFetch('/api/betterstack/status-pages', { method: 'POST', body: JSON.stringify(payload) }); } catch(e) { return null; }
  },
  async getMonitorSLA(bsId, from, to) {
    try {
      const q = new URLSearchParams();
      if (from) q.set('from', from);
      if (to) q.set('to', to);
      return await apiFetch(`/api/betterstack/monitors/${bsId}/sla?${q}`).catch(() => null);
    } catch(e) { return null; }
  },
  async getResponseTimes(bsId, period = '24h') {
    try { return await apiFetch(`/api/betterstack/monitors/${bsId}/response-times?period=${period}`).catch(() => null); } catch(e) { return null; }
  },
};


