// ═══════════════════════════════════════════════════════════════════════════════
// FP INTEGRATIONS API — Zapier/Make/Webhook Integration Hub client
// ═══════════════════════════════════════════════════════════════════════════════
window.FP_INTEGRATIONS_API = {
  async load() {
    try {
      const [intgData, statsData, templData, logsData, runsData, incomingData] = await Promise.allSettled([
        apiFetch('/api/integrations').catch(() => null),
        apiFetch('/api/integrations/stats').catch(() => null),
        apiFetch('/api/integrations/templates').catch(() => null),
        apiFetch('/api/integrations/automation-logs?limit=30').catch(() => null),
        apiFetch('/api/integrations/runs?limit=30').catch(() => null),
        apiFetch('/api/integrations/incoming-webhooks').catch(() => null),
      ]);
      window.FP_DATA = window.FP_DATA || {};
      window.FP_DATA.integrations = {
        integrations:    intgData.status  === 'fulfilled' ? (intgData.value?.integrations  || []) : [],
        stats:           statsData.status === 'fulfilled' ? (statsData.value               || {}) : {},
        templates:       templData.status === 'fulfilled' ? (templData.value?.templates    || []) : [],
        logs:            logsData.status  === 'fulfilled' ? (logsData.value?.logs          || []) : [],
        runs:            runsData.status  === 'fulfilled' ? (runsData.value?.runs          || []) : [],
        incomingWebhooks:incomingData.status==='fulfilled'? (incomingData.value?.webhooks  || []) : [],
        loadedAt: Date.now(),
      };
      return window.FP_DATA.integrations;
    } catch(e) { console.warn('[FP_INTEGRATIONS_API] load error:', e); return null; }
  },

  async connect(platform, data) {
    try {
      const endpoint = platform === 'zapier' ? '/api/integrations/zapier/connect'
                     : platform === 'make'   ? '/api/integrations/make/connect'
                     : '/api/integrations/connections';
      return await apiFetch(endpoint, { method:'POST', body: JSON.stringify({ ...data, platform }) });
    } catch(e) { console.warn('[FP_INTEGRATIONS_API] connect error:', e); return null; }
  },

  async test(integrationId) {
    try {
      return await apiFetch(`/api/integrations/connections/${integrationId}/test`, { method:'POST' });
    } catch(e) { console.warn('[FP_INTEGRATIONS_API] test error:', e); return null; }
  },

  async toggle(integrationId, active) {
    try {
      return await apiFetch(`/api/integrations/connections/${integrationId}`, { method:'PATCH', body: JSON.stringify({ active }) });
    } catch(e) { console.warn('[FP_INTEGRATIONS_API] toggle error:', e); return null; }
  },

  async delete(integrationId) {
    try {
      return await apiFetch(`/api/integrations/connections/${integrationId}`, { method:'DELETE' });
    } catch(e) { console.warn('[FP_INTEGRATIONS_API] delete error:', e); return null; }
  },

  async dispatch(event, payload) {
    try {
      return await apiFetch('/api/integrations/dispatch', { method:'POST', body: JSON.stringify({ event, payload }) });
    } catch(e) { console.warn('[FP_INTEGRATIONS_API] dispatch error:', e); return null; }
  },

  async createIncoming(name, action, source) {
    try {
      return await apiFetch('/api/integrations/incoming-webhooks', { method:'POST', body: JSON.stringify({ name, action, source }) });
    } catch(e) { console.warn('[FP_INTEGRATIONS_API] createIncoming error:', e); return null; }
  },

  async retry(runId) {
    try {
      return await apiFetch(`/api/integrations/runs/${runId}/retry`, { method:'POST' });
    } catch(e) { console.warn('[FP_INTEGRATIONS_API] retry error:', e); return null; }
  },
};

window.FP_AUTOMATION_API = {
  async load() {
    try {
      const data = await apiFetch('/api/automation/workflows').catch(() => null);
      if (!data) return;
      window.FP_DATA = window.FP_DATA || {};
      window.FP_DATA.automation = { workflows: data.workflows || data || [] };
    } catch(e) { console.warn('[FP_AUTOMATION_API] load error:', e); }
  },

  async toggle(workflowId, enabled) {
    try {
      await apiFetch(`/api/automation/workflows/${encodeURIComponent(workflowId)}`, {
        method: 'PATCH', body: JSON.stringify({ enabled })
      });
      if (window.FP_DATA?.automation?.workflows) {
        const wf = window.FP_DATA.automation.workflows.find(w => w.id === workflowId);
        if (wf) { wf.enabled = enabled; render(); }
      }
      showToast('success', enabled ? 'Workflow activé' : 'Workflow désactivé');
    } catch(e) { showToast('error', String(e)); }
  },

  async run(workflowId) {
    showToast('info', 'Exécution du workflow lancée…');
    try {
      const r = await apiFetch(`/api/automation/workflows/${encodeURIComponent(workflowId)}/run`, { method: 'POST' });
      if (r?.ok !== false) showToast('success', 'Workflow exécuté avec succès');
      else showToast('error', r?.error || 'Erreur d\'exécution');
    } catch(e) { showToast('error', String(e)); }
  },

  async create(workflowData) {
    try {
      const r = await apiFetch('/api/automation/workflows', { method: 'POST', body: JSON.stringify(workflowData) });
      if (r?.ok !== false) {
        await this.load();
        render();
        showToast('success', 'Workflow créé');
      } else showToast('error', r?.error || 'Erreur');
      return r;
    } catch(e) { showToast('error', String(e)); return null; }
  },
};

// ═══════════════════════════════════════════════════════════════════════════════
// FP ADDONS API — Real Add-ons Marketplace client
// ═══════════════════════════════════════════════════════════════════════════════

window.FP_ADDONS_API = {
  async load() {
    try {
      const data = await apiFetch('/api/addons').catch(() => null);
      if (!data) return;
      window.FP_DATA = window.FP_DATA || {};
      window.FP_DATA.addons = {
        active:      data.addons      || {},
        orgAddons:   data.orgAddons   || [],
        definitions: data.definitions || {},
        quotas:      data.quotas      || {},
        plan:        data.plan        || 'pro',
      };
    } catch(e) { console.warn('[FP_ADDONS_API] load error:', e); }
  },

  async activate(addonKey) {
    showToast('info', `Activation de ${addonKey}…`);
    try {
      const r = await apiFetch(`/api/addons/${encodeURIComponent(addonKey)}/activate`, { method: 'POST' });
      if (r?.ok) {
        if (window.FP_DATA?.addons) window.FP_DATA.addons.active = r.addons || window.FP_DATA.addons.active;
        render();
        showToast('success', `Add-on ${addonKey} activé`);
      } else showToast('error', r?.error || 'Activation impossible');
      return r;
    } catch(e) { showToast('error', String(e)); return null; }
  },

  async deactivate(addonKey) {
    try {
      const r = await apiFetch(`/api/addons/${encodeURIComponent(addonKey)}/deactivate`, { method: 'POST' });
      if (r?.ok && window.FP_DATA?.addons?.active) {
        window.FP_DATA.addons.active[addonKey] = false;
        render();
        showToast('success', `Add-on ${addonKey} désactivé`);
      }
      return r;
    } catch(e) { showToast('error', String(e)); return null; }
  },

  async buyCredits(pack) {
    showToast('info', 'Redirection vers la page tarifs…');
    try {
      const _packKeyMap = { 'ai_credits_50k': 'aiCreditsPack50k', 'ai_credits_200k': 'aiCreditsPack200k', 'ai_credits_500k': 'aiCreditsPack500k' };
      const cartKey = _packKeyMap[pack] || pack;
      const cart = { plan: null, addons: {}, fromDashboard: true };
      cart.addons[cartKey] = 1;
      localStorage.setItem('fp_cart', JSON.stringify(cart));
      window.location.href = '/pricing.html?from=dashboard&addon=' + encodeURIComponent(cartKey);
    } catch(e) { showToast('error', String(e)); return null; }
  },
};

// ═══════════════════════════════════════════════════════════════════════════════
// FP AI CREDITS API — Real AI Credits & Usage client
// ═══════════════════════════════════════════════════════════════════════════════

window.FP_AI_CREDITS_API = {
  async load() {
    try {
      const [stats, usage] = await Promise.all([
        apiFetch('/api/ai-credits').catch(() => null),
        apiFetch('/api/ai-credits/usage').catch(() => null),
      ]);
      window.FP_DATA = window.FP_DATA || {};
      const _m = stats?.monthly || {};
      const _used   = _m.creditsUsed  || 0;
      const _limit  = _m.creditsLimit || 200000;
      const _extra  = _m.creditsExtra || 0;
      window.FP_DATA.aiCredits = {
        total:        _limit + _extra,
        used:         _used,
        remaining:    _limit + _extra - _used,
        pct:          _limit > 0 ? Math.round((_used / (_limit + _extra)) * 100) : 0,
        plan:         stats?.plan        || 'pro',
        monthly:      _m,
        byFeature:    usage?.byFeature   || stats?.byFeature || [],
        dailyHistory: usage?.dailyHistory || stats?.dailyHistory || [],
        alerts:       stats?.alerts      || [],
        requestCount: _m.requestCount    || 0,
        costEur:      _m.costEur         || 0,
        resetAt:      _m.resetAt         || null,
      };
    } catch(e) { console.warn('[FP_AI_CREDITS_API] load error:', e); }
  },

  async consume(feature, metadata) {
    try {
      return await apiFetch('/api/ai-credits/consume', { method: 'POST', body: JSON.stringify({ feature, metadata }) });
    } catch(e) { console.warn('[FP_AI_CREDITS_API] consume error:', e); return null; }
  },

  async buyCredits(pack) {
    showToast('info', 'Redirection vers la page tarifs…');
    try {
      const _packKeyMap = { 'ai_credits_50k':'aiCreditsPack50k', 'ai_credits_200k':'aiCreditsPack200k', 'ai_credits_500k':'aiCreditsPack500k' };
      const cartKey = _packKeyMap[pack] || pack;
      const _cart = { plan: null, addons: {}, fromDashboard: true };
      _cart.addons[cartKey] = 1;
      localStorage.setItem('fp_cart', JSON.stringify(_cart));
      window.location.href = '/pricing.html?from=dashboard&addon=' + encodeURIComponent(cartKey);
    } catch(e) { showToast('error', String(e)); return null; }
  },
};

// ── Auto-load all integrations on page start ──────────────────────────────────

(function _autoLoadGoogleIntegrations() {
  const doLoad = () => {
    if (typeof window === 'undefined') return;

    // Google integrations
    window.FP_GBP_API.load().then(() => { if (STATE.gbp?.connected) render(); }).catch(() => {});
    window.FP_GA4_API.load().then(() => { if (window.FP_DATA?.ga4?.connected) render(); }).catch(() => {});
    window.FP_GSC_API.load().then(() => { if (STATE.gsc?.connected) render(); }).catch(() => {});

    // SaaS engine integrations — load silently in background, re-render if data arrives
    const _reloadIfData = (key) => () => {
      const has = key === 'automation'
        ? window.FP_DATA?.automation?.workflows?.length > 0
        : window.FP_DATA?.[key] && (Array.isArray(window.FP_DATA[key]) ? window.FP_DATA[key].length > 0 : true);
      if (has) render();
    };

    window.FP_BEHAVIORAL_API.load().then(_reloadIfData('behavioral')).catch(() => {});
    window.FP_CRO_API.load().then(_reloadIfData('cro')).catch(() => {});
    window.FP_REVENUE_LEAK_API.load().then(_reloadIfData('revenueLeak')).catch(() => {});
    window.FP_FORECAST_API.load().then(_reloadIfData('forecast')).catch(() => {});
    window.FP_AUTOMATION_API.load().then(_reloadIfData('automation')).catch(() => {});
    window.FP_ADDONS_API.load().then(_reloadIfData('addons')).catch(() => {});
    window.FP_INTEGRATIONS_API.load().then(_reloadIfData('integrations')).catch(() => {});
    window.FP_CRM_API.load().then(_reloadIfData('crm')).catch(() => {});
    window.FP_MARKET_INTEL_API.load().then(_reloadIfData('marketIntel')).catch(() => {});
    window.FP_PERMISSIONS_API.load().then(_reloadIfData('permissions')).catch(() => {});
    window.FP_REVIEW_INTEL_API.load().then(_reloadIfData('reviewIntel')).catch(() => {});
    window.FP_GBP_POSTS_API.load().then(_reloadIfData('gbpPosts')).catch(() => {});
    window.FP_LOCAL_MAPS_API.load().then(_reloadIfData('localMaps')).catch(() => {});
    window.FP_SSO_API.load().then(_reloadIfData('sso')).catch(() => {});
    window.FP_AI_CREDITS_API.load().then(_reloadIfData('aiCredits')).catch(() => {});

    // Missions — load from real backend
    if (typeof window.FP_MISSIONS_API !== 'undefined') {
      window.FP_MISSIONS_API.load().then(missions => {
        if (missions && missions.length > 0) {
          STATE.missions = missions;
          if (STATE.route === 'missions') render();
        }
      }).catch(() => {});
    }
  };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => setTimeout(doLoad, 0), { once: true });
  } else {
    setTimeout(doLoad, 0);
  }
})();


